INSERT INTO `certificates` (`id`, `slug`, `nama`, `nama_idn`, `penerbit`, `tanggal`, `desk`, `desk_idn`, `gambar`, `icon`, `link`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'c-basic', 'C# Basic', 'Dasar C#', 'HackerRank', 'December 24, 2025', 'Competency certification in basic C# programming covering control structures, basic object-oriented programming, exception handling, and collections.', 'Sertifikasi kompetensi dalam pemrograman C# dasar yang mencakup struktur kontrol, pemrograman berorientasi objek dasar, penanganan pengecualian, dan koleksi.', 'https://res.cloudinary.com/droanqrew/image/upload/v1786757007/portfolio/certificates/phptkpj0t9fn3dfbYeGkK3_fu3r7o.webp', 'ri-code-line', 'https://www.hackerrank.com/certificates/f77a49aeb83c', 1, '2026-08-11 23:34:02', '2026-08-18 11:01:46'),
(2, 'learn-solid-programming-principles', 'Learn SOLID Programming Principles', 'Belajar Prinsip Pemrograman SOLID', 'dicoding', 'December 17, 2025', 'Certification of understanding in object-oriented programming paradigm covering Encapsulation, Inheritance, Polymorphism, and Abstraction.', 'Sertifikasi pemahaman dalam paradigma pemrograman berorientasi objek yang meliputi Enkapsulasi, Pewarisan, Polimorfisme, dan Abstraksi.', 'https://res.cloudinary.com/droanqrew/image/upload/v1786858999/portfolio/certificates/phpt1o8dv9qelje7aljg9e_n3fmvn.webp', 'ri-instance-line', 'https://www.dicoding.com/certificates/JLX15YG7NZ72', 2, '2026-08-11 23:34:02', '2026-08-18 10:59:11'),
(3, 'getting-started-with-programming-with-c', 'Getting Started with Programming with C', 'Memulai Pemrograman dengan C', 'Dicoding', 'December 14, 2025', 'Fundamental understanding of procedural programming with C language, memory management, pointers, array manipulation, and basic data structures.', 'Pemahaman mendasar tentang pemrograman prosedural dengan bahasa C, manajemen memori, pointer, manipulasi array, dan struktur data dasar.', 'https://res.cloudinary.com/droanqrew/image/upload/v1786859810/portfolio/certificates/phpq071amqr55r766dwLUz_rxwueb.webp', 'ri-code-box-line', 'https://www.dicoding.com/certificates/ERZR2J3YQPYV', 3, '2026-08-11 23:34:02', '2026-08-18 11:12:14'),
(4, 'junior-web-developer', 'Junior Web Developer', 'Pengembang Web Pratama', 'LPK Inixindo', 'November 05 - 08, 2025', 'Official national competency certification as a Junior Web Developer, validating skills in HTML, CSS, JavaScript, PHP relational databases, and static/dynamic web implementations.', 'Sertifikasi kompetensi nasional resmi sebagai Junior Web Developer, yang memvalidasi keterampilan dalam HTML, CSS, JavaScript, PHP, basis data relasional, dan implementasi web statis/dinamis.', 'https://res.cloudinary.com/droanqrew/image/upload/v1787078065/portfolio/certificates/php8tkui3amacun7r8Z7eA_gdds6f.webp', 'ri-global-line', 'https://drive.google.com/file/d/1iVXgcz8NM2euIptlUu6niZ6Ay_V3eiAG/view?usp=sharing', 4, '2026-08-11 23:34:02', '2026-08-18 11:34:26'),
(5, '2nd-place-in-game-development-competition', '2nd Place in Game Development Competition', 'Juara 2 Kompetisi Pengembangan Game', 'HMIF Fasilkom UNEJ', 'October 19, 2025', 'Award for achieving second place in a national creative game development competition, focusing on game mechanics design, asset integration, and gameplay.', 'Penghargaan atas pencapaian juara kedua dalam kompetisi pengembangan game kreatif nasional, yang berfokus pada desain mekanisme game, integrasi aset, dan gameplay.', 'https://res.cloudinary.com/droanqrew/image/upload/v1787078149/portfolio/certificates/phpf3a05rp34kbg45cQ0ii_ddettx.webp', 'ri-gamepad-fill', NULL, 5, '2026-08-11 23:34:02', '2026-08-18 11:35:50'),
(6, 'programming-division-staff', 'Programming Division Staff', 'Anggota Divisi Pemrograman', 'UKM LAOS', 'December 1, 2025', 'Certification of leadership and dedication as a programming staff member in the information technology community, mentoring members in understanding basic programming algorithms.', 'Sertifikasi kepemimpinan dan dedikasi sebagai anggota staf pemrograman di komunitas teknologi informasi, membimbing anggota dalam memahami algoritma pemrograman dasar.', 'https://res.cloudinary.com/droanqrew/image/upload/v1787078209/portfolio/certificates/php4nb5vev3557512nhhNF_x4myhu.webp', 'ri-team-line', NULL, 6, '2026-08-11 23:34:02', '2026-08-18 11:36:49'),
(7, 'it-staff-smagitv', 'IT Staff SMAGITV', 'Anggota IT SMAGITV', 'SMAN 1 Giri', 'October 13, 2023', 'Award for active contribution as information technology staff and school digital media broadcast management, designing local network infrastructure and live streaming portals.', 'Penghargaan atas kontribusi aktif sebagai staf teknologi informasi dan manajemen penyiaran media digital sekolah, perancangan infrastruktur jaringan lokal dan portal siaran langsung.', 'https://res.cloudinary.com/droanqrew/image/upload/v1787078255/portfolio/certificates/php0f8rgrpv0i5r9tCbPTm_podb5u.webp', 'ri-tv-line', NULL, 7, '2026-08-11 23:34:02', '2026-08-18 11:37:36'),
(8, 'gold-medal-in-physics-olympiad', 'Gold Medal in Physics Olympiad', 'Medali Emas di Olimpiade Fisika', 'OPN-SP', 'October 30, 2022', 'Gold medal award in a national level academic competition in the field of Physics, validating logical analysis and complex problem-solving abilities.', 'Meraih medali emas dalam kompetisi akademik tingkat nasional di bidang Fisika, yang membuktikan kemampuan analisis logis dan pemecahan masalah yang kompleks.', 'https://res.cloudinary.com/droanqrew/image/upload/v1787078368/portfolio/certificates/phpccsrsme50ssk5PhiJEX_ejyyt8.webp', 'ri-award-fill', NULL, 8, '2026-08-11 23:34:02', '2026-08-18 11:39:29'),
(9, 'bronze-medal-in-informatics-olympiad', 'Bronze Medal in Informatics Olympiad', 'Medali Perunggu di Olimpiade Informatika', 'OPN-SP', 'October 30, 2022', 'Bronze medal award in a national level Informatics competition, testing algorithm skills, data structures, and competitive programming problem-solving.', 'Penghargaan medali perunggu dalam kompetisi Informatika tingkat nasional, yang menguji kemampuan algoritma, struktur data, dan pemecahan masalah pemrograman kompetitif.', 'https://res.cloudinary.com/droanqrew/image/upload/v1787078426/portfolio/certificates/php51bigkbm4je0cHTeVLU_zcnlte.webp', 'ri-award-line', NULL, 9, '2026-08-11 23:34:02', '2026-08-18 11:40:27'),
(10, 'seo-content-marketing', 'SEO & Content Marketing', 'SEO & Content Marketing', 'MySkill', 'January 13, 2025', 'Certification in Search Engine Optimization (SEO) strategies covering keyword research, on-page optimization, technical SEO, and performance measurement to improve website visibility and organic search rankings.', 'Sertifikasi dalam strategi Search Engine Optimization (SEO) yang mencakup riset kata kunci, optimasi on-page, SEO teknis, dan pengukuran kinerja untuk meningkatkan visibilitas situs web dan peringkat pencarian organik.', 'https://res.cloudinary.com/droanqrew/image/upload/v1787078494/portfolio/certificates/phpfe8ehsuf7uks8GNa3se_wcet7h.webp', 'ri-line-chart-line', NULL, 10, '2026-08-11 23:34:02', '2026-08-18 11:41:34'),
(11, 'getting-prospective-clients', 'Getting Prospective Clients', 'Mendapatkan Calon Klien', 'MySkill', 'January 16, 2025', 'Certification in digital marketing client acquisition strategies, covering lead generation, conversion optimization, market analysis, and client relationship management for effective business growth.', 'Sertifikasi dalam strategi akuisisi klien pemasaran digital, meliputi pembuatan prospek, optimasi konversi, analisis pasar, dan manajemen hubungan klien untuk pertumbuhan bisnis yang efektif.', 'https://res.cloudinary.com/droanqrew/image/upload/v1787078540/portfolio/certificates/phpo7j04mh86q0h0eCRVpp_okz1jw.webp', 'ri-handshake-line', NULL, 11, '2026-08-11 23:34:02', '2026-08-18 11:42:21');

