INSERT INTO `courses` (`id`, `slug`, `nama`, `nama_idn`, `desk`, `desk_idn`, `gambar`, `sort_order`, `created_at`, `updated_at`, `konten`) VALUES
(1, 'pemrograman-web', 'Pemrograman Web', NULL, 'Pemrograman website mencakup pembuatan tampilan visual hingga pengolahan data di belakang layar. Tools yang digunakan HTML, CSS, JavaScript, PHP, Laravel', NULL, 'https://res.cloudinary.com/droanqrew/image/upload/v1787079348/portfolio/courses/php2cv4fmi1nssf90rXBL1_qo68co.webp', 1, '2026-08-18 00:03:51', '2026-10-15 20:02:35', '[{\"type\":\"subbab\",\"judul\":\"Persiapan Pemrograman Web\",\"judul_idn\":null},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"Web Programming atau Pemrograman Web merupakan istilah yang erat kaitannya dengan internet dan website. Memang benar, karena pemrograman web merupakan suatu proses pembuatan website untuk keperluan internet. Orang banyak mengenal web dengan istilah\\u00a0*WWW*\\u00a0atau\\u00a0*World Wide Web*.\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Instalasi Extension\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1787157652\\/portfolio\\/courses\\/phpqeuhcu7niqqga0o7q9R_nrzsfb.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1787157592\\/portfolio\\/courses\\/php228h7nkvekjo1OOn00T_lev1vg.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading\",\"teks\":\"Instalasi Laragon\"},{\"type\":\"paragraf\",\"teks\":\"Laragon digunakan sebagai sisi server database dengan base mysql dan path PHP\",\"align\":\"kiri\"},{\"type\":\"link\",\"href\":\"https:\\/\\/github.com\\/leokhoa\\/laragon\\/releases\\/tag\\/6.0.0\",\"label\":\"Instalasi Laragon\",\"desc\":\"\"},{\"type\":\"link\",\"href\":\"https:\\/\\/windows.php.net\\/download\\/\",\"label\":\"Instalasi PHP 8.3\",\"desc\":\"\"},{\"type\":\"subbab\",\"judul\":\"Konsep Aplikasi Web\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"Pengenalan HTML\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>HTML (HyperText Markup Language) <\\/strong>adalah bahasa standar yang digunakan untuk membuat dan merancang halaman web. Dalam dunia web development, HTML berfungsi sebagai kerangka dasar yang mendefinisikan struktur dan isi dari sebuah halaman web. HTML bukanlah bahasa pemrograman, melainkan&nbsp;<strong>markup language<\\/strong>&nbsp;(bahasa penanda) yang menggunakan elemen-elemen (tag) untuk memberi struktur pada konten seperti teks, gambar, link, dan lainnya.<\\/p>\",\"align\":\"justify\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1787885733\\/kerangka.png\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading\",\"teks\":\"Struktur Kode HTML\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<!DOCTYPE html>\\n<html lang=\\\"id\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Judul Halaman<\\/title>\\n<\\/head>\\n<body>\\n\\n    <h1>Halo, Dunia!<\\/h1>\\n    <p>Ini adalah struktur dasar dokumen HTML.<\\/p>\\n\\n<\\/body>\\n<\\/html>\"},{\"type\":\"tabel\",\"headers\":[\"Kode\",\"Penjelasan\"],\"rows\":[[\"`<!DOCTYPE html>`\",\"Mendeklarasikan bahwa dokumen ini menggunakan HTML5\"],[\"`<html>`\",\"Elemen pembungkus konten halaman web\"],[\"`<head>`\",\"Bagian kepala dokumen, berisi metadata yang tidak tampil langsung di halaman, tetapi penting untuk browser dan mesin pencari.\"],[\"`<meta>`\",\"Elemen untuk mengatur tampilan HP, dan informasi web\"],[\"`<title>`\",\"Untuk membarikan judul di tab browser\"],[\"`<body>`\",\"Bagian isi (teks, gambar, dll.) yang terlihat di website.\"]],\"caption\":\"\"},{\"type\":\"subheading\",\"teks\":\"Elemen Dasar HTML\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>1. Heading (Judul)<\\/strong><\\/p><p>Digunakan untuk membuat judul atau subjudul. Ada 6 level (h1 paling besar, h6 paling kecil).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<h1>Heading 1<\\/h1>\\n<h2>Heading 2<\\/h2>\\n<h3>Heading 3<\\/h3>\\n<h4>Heading 4<\\/h4>\\n<h5>Heading 5<\\/h5>\\n<h6>Heading 6<\\/h6>\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>2. Paragraf<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<p>Ini adalah sebuah paragraf.<\\/p>\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong> 3. Link (Hyperlink)<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<a href=\\\"https:\\/\\/www.google.com\\\">Kunjungi Google<\\/a>\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code><strong>href<\\/strong><\\/code>&nbsp;= atribut untuk menentukan tujuan link.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>4. Gambar Link :<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<img src=\\\"gambar.jpg\\\" alt=\\\"Deskripsi gambar\\\" width=\\\"300\\\">\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code><strong>src<\\/strong><\\/code>: alamat gambar yang diambil<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code><strong>alt<\\/strong><\\/code>: teks untuk alternatif gambar yang tidak muncul<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>5. Order List :<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<ol>\\n    <li>Langkah pertama<\\/li>\\n    <li>Langkah kedua<\\/li>\\n<\\/ol>\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>6. Unordered List :<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<ul>\\n    <li>Apel<\\/li>\\n    <li>Pisang<\\/li>\\n<\\/ul>\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>7. Comment (Komentar) :<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<!-- Ini Komentar -->\\n<p>Aku Budiono Siregar<\\/p>\"},{\"type\":\"subheading\",\"teks\":\"Semantik\"},{\"type\":\"paragraf\",\"teks\":\"<p>Penggunaan tag HTML yang sesuai dengan arti dan fungsi konten di dalamnya, bukan sekadar untuk mengatur tampilan.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1787291336\\/portfolio\\/courses\\/phpcih3t56auljk8gAV9l8_jdmgrm.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subbab\",\"judul\":\"SI ES ES\\ud83e\\udd76\",\"judul_idn\":null},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Materi : CSS <\\/strong>(Cascading Style Sheets)<\\/p><p><strong>Topik :<\\/strong> Selector, Cascade, Box Model, Typography, Positioning, Flexbox, Grid, Media Query, Responsive Design<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"1. Pendahuluan: Apa itu CSS dan Kenapa Kita Butuh CSS?\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">HTML bertugas membangun struktur dan konten halaman (heading, paragraf, gambar, tombol, dll). Tapi HTML sendiri tidak tahu bagaimana elemen-elemen itu harus terlihat.<\\/p><p class=\\\"ql-align-justify\\\">Coba bayangkan tanpa CSS : semua halaman web di dunia ini akan terlihat seperti dokumen teks polos font default, warna hitam-putih, semua elemen tersusun dari atas ke bawah tanpa tata letak. CSS (Cascading Style Sheets) adalah bahasa yang memberi \\\"wajah\\\" pada struktur HTML tersebut: warna, jarak, ukuran, posisi, animasi, hingga tata letak responsif di berbagai ukuran layar.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\">Analogi sederhana :<\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>HTML = kerangka rumah (dinding, pintu, jendela)<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>CSS = interior desain (cat, lantai, furniture, pencahayaan)<\\/li><\\/ol><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\">Cara Menghubungkan CSS ke HTML<\\/p><p class=\\\"ql-align-justify\\\">Ada 3 cara, tapi hanya 1 yang jadi best practice :<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Cara\",\"Contoh\",\"Kapan dipakai\"],\"rows\":[[\"Inline\",\"`<p style=\\\"color:red;\\\">Teks<\\/p>`\",\"Hindari \\u2014 susah dikelola, spesifisitas tinggi\"],[\"Internal\",\"`<style> p { color:red; } <\\/style> di <head>`\",\"Untuk contoh cepat \\/ prototipe kecil\"],[\"External (disarankan)\",\"`<link rel=\\\"stylesheet\\\" href=\\\"style.css\\\">`\",\"Untuk proyek nyata \\u2014 bisa dipakai ulang di banyak halaman, gampang di-maintain\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Kenapa external lebih disarankan?<\\/strong> Karena memisahkan <em>concern<\\/em> (struktur vs tampilan), file bisa di-cache browser (loading lebih cepat di kunjungan berikutnya), dan satu file CSS bisa dipakai di puluhan halaman HTML sekaligus.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"2. Selector CSS\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Selector adalah \\\"penunjuk\\\" atau cara kita memilih elemen HTML mana yang ingin diberi style.<\\/p><p><br><\\/p><p><strong>2.1 Selector Dasar<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"\\/* Element selector \\u2014 pilih semua tag <p> *\\/\\np { color: navy; }\\n\\n\\/* Class selector \\u2014 pilih elemen dengan class=\\\"highlight\\\" *\\/\\n.highlight { background-color: yellow; }\\n\\n\\/* ID selector \\u2014 pilih elemen dengan id=\\\"header\\\" (harus unik di 1 halaman) *\\/\\n#header { font-size: 24px; }\\n\\n\\/* Universal selector \\u2014 pilih SEMUA elemen *\\/\\n* { box-sizing: border-box; }\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Kapan pakai class vs id?<\\/strong><\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>class<\\/code> \\u2192 dipakai berkali-kali, untuk styling yang reusable (misalnya semua tombol punya class <code>.btn<\\/code>)<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>id<\\/code> \\u2192 hanya boleh 1 kali per halaman, biasanya dipakai untuk target JavaScript atau anchor link, <strong>bukan<\\/strong> untuk styling utama karena spesifisitasnya terlalu tinggi dan sulit di-override<\\/li><\\/ol><p><br><\\/p><p><strong>2.2 Selector Kombinasi<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"\\/* Descendant \\u2014 semua <a> di dalam <nav>, sejauh apapun turunannya *\\/\\nnav a { text-decoration: none; }\\n\\n\\/* Child \\u2014 hanya <li> yang LANGSUNG anak dari <ul> *\\/\\nul > li { list-style: none; }\\n\\n\\/* Adjacent sibling \\u2014 <p> yang persis setelah <h2> *\\/\\nh2 + p { font-weight: bold; }\\n\\n\\/* General sibling \\u2014 semua <p> setelah <h2> (di level sama) *\\/\\nh2 ~ p { color: gray; }\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Kenapa penting membedakan <\\/strong><code><strong>nav a<\\/strong><\\/code><strong> dan <\\/strong><code><strong>nav &gt; a<\\/strong><\\/code><strong>?<\\/strong> Kalau struktur HTML-mu bersarang dalam (misalnya <code>&lt;nav&gt;&lt;ul&gt;&lt;li&gt;&lt;a&gt;<\\/code>), <code>nav &gt; a<\\/code> tidak akan mengenai <code>&lt;a&gt;<\\/code> tersebut karena bukan anak langsung. Salah pilih combinator = style tidak muncul, dan ini salah satu bug paling umum pemula.<\\/p><p><br><\\/p><p><strong>2.3 Pseudo-class dan Pseudo-element<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"\\/* Pseudo-class \\u2014 kondisi\\/state elemen *\\/\\na:hover { color: red; }\\ninput:focus { border-color: blue; }\\nli:first-child { font-weight: bold; }\\nli:nth-child(2n) { background: #f0f0f0; } \\/* zebra striping *\\/\\n\\n\\/* Pseudo-element \\u2014 bagian tertentu dari elemen *\\/\\np::first-letter { font-size: 200%; }\\np::before { content: \\\"\\u2192 \\\"; }\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Jika tidak menggunakan pseudo-class<\\/strong>, kamu terpaksa menambahkan\\/menghapus class lewat JavaScript hanya untuk efek hover atau styling baris genap-ganjil pada tabel padahal browser sudah menyediakan mekanisme bawaan yang lebih ringan dan tanpa JavaScript sama sekali.<\\/p><p><br><\\/p><p><strong>2.4 Attribute Selector<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"input[type=\\\"text\\\"] { border: 1px solid gray; }\\na[target=\\\"_blank\\\"] { color: orange; }\"},{\"type\":\"paragraf\",\"teks\":\"<p>Berguna saat elemen tidak punya class tapi bisa dibedakan dari atributnya, misalnya membedakan <code>&lt;input type=\\\"text\\\"&gt;<\\/code> dan <code>&lt;input type=\\\"checkbox\\\"&gt;<\\/code> tanpa menambah class manual di HTML.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"3. Cascade & Specificity (Kenapa CSS Kadang \\\"Tidak Ngaruh\\\"?)\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Ini adalah bagian yang paling sering membingungkan pemula: <strong>kenapa style yang saya tulis tidak muncul, padahal tidak ada error?<\\/strong><\\/p><p class=\\\"ql-align-justify\\\">Jawabannya ada pada 3 konsep: <strong>Cascade<\\/strong>, <strong>Specificity<\\/strong>, dan <strong>Source Order<\\/strong>.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>3.1 Cascade (Urutan Prioritas)<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\">Ketika ada beberapa aturan yang bentrok pada elemen yang sama, browser menentukan pemenang berdasarkan urutan:<\\/p><ol><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Importance<\\/strong> - <code>!important<\\/code> menang di atas segalanya (tapi sebaiknya dihindari)<\\/li><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Specificity<\\/strong> - selector yang lebih spesifik menang<\\/li><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Source order<\\/strong> - kalau specificity sama, aturan yang ditulis paling akhir yang menang<\\/li><\\/ol><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>3.2 Specificity (Bobot Selector)<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\">Setiap selector punya \\\"skor\\\". Semakin spesifik, semakin tinggi skornya:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Selector\",\"Skor (id, class, element)\",\"Contoh\"],\"rows\":[[\"Element\",\"0-0-1\",\"`p`\"],[\"Class \\/ attribute \\/ pseudo-class\",\"0-1-0\",\"`.btn`, `:hover`\"],[\"ID\",\"1-0-0\",\"`#header`\"],[\"Inline style\",\"tertinggi\",\"`style=\\\"...\\\"`\"]],\"caption\":\"\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"p { color: blue; }              \\/* skor 0-0-1 *\\/\\n.text { color: green; }         \\/* skor 0-1-0 \\u2192 menang *\\/\\n#main p.text { color: red; }    \\/* skor 1-1-1 \\u2192 menang di atas semuanya *\\/\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Kenapa harus paham ini?<\\/strong> Kalau tidak paham cascade, pemula biasanya akan \\\"menyerah\\\" dan menyelesaikan masalah dengan menambahkan <code>!important<\\/code> di mana-mana. Ini <strong>anti-pattern<\\/strong>: begitu satu <code>!important<\\/code> dipakai, style lain butuh <code>!important<\\/code> juga untuk override, dan akhirnya CSS jadi tidak terkontrol dan sangat sulit di-maintain. Memahami specificity artinya kamu bisa menulis selector yang \\\"cukup spesifik\\\" tanpa perlu senjata pamungkas itu.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"4. Box Model\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Setiap elemen HTML pada dasarnya adalah sebuah <strong>kotak (box)<\\/strong>, tersusun dari 4 lapisan:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1788303616\\/portfolio\\/courses\\/php31p5qa5qa8qrey9Cmlw_fcpdf6.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".box {\\n  width: 300px;\\n  padding: 20px;\\n  border: 5px solid black;\\n  margin: 10px;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<h3><strong>4.1 Masalah Klasik : <\\/strong><code><strong>content-box<\\/strong><\\/code><strong> vs <\\/strong><code><strong>border-box<\\/strong><\\/code><\\/h3><p>Secara default, <code>width<\\/code> di CSS hanya mengatur <strong>content<\\/strong>, bukan total lebar kotak. Ini sering bikin bingung:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".box {\\n  width: 300px;\\n  padding: 20px;\\n  border: 5px solid black;\\n  \\/* Lebar total sebenarnya = 300 + 20+20 (padding) + 5+5 (border) = 350px! *\\/\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Pemula sering berencana membuat 3 kolom @300px pas 1 baris (900px), tapi ternyata meleber jadi 1050px dan malah turun ke baris baru inilah akibat tidak paham box model.<\\/p><p><br><\\/p><p><strong>Solusi standar industri:<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"* {\\n  box-sizing: border-box;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Dengan <code>border-box<\\/code>, <code>width: 300px<\\/code> sudah termasuk padding dan border di dalamnya \\u2014 jadi lebar total kotak <strong>pasti<\\/strong> 300px. Inilah alasan hampir semua CSS reset\\/framework modern (Bootstrap, Tailwind) langsung set <code>box-sizing: border-box<\\/code> di awal.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>4.2 Margin Collapsing<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\">Satu perilaku \\\"aneh\\\" yang wajib diketahui: margin vertikal antar elemen sibling <strong>tidak dijumlahkan<\\/strong>, melainkan diambil yang terbesar.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".a { margin-bottom: 30px; }\\n.b { margin-top: 20px; }\\n\\/* Jarak antara .a dan .b BUKAN 50px, tapi 30px (nilai terbesar) *\\/\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Ini sering membuat pemula bingung kenapa jarak antar elemen \\\"tidak nambah\\\" walau margin sudah ditambah dua-duanya.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"5. Typography\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Typography menentukan keterbacaan dan kenyamanan visual teks di halaman.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"body {\\n  font-family: \\\"Segoe UI\\\", Arial, sans-serif;\\n  font-size: 16px;\\n  line-height: 1.5;\\n  font-weight: 400;\\n  letter-spacing: 0.5px;\\n  text-align: left;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<h3 class=\\\"ql-align-justify\\\"><strong>5.1 Kenapa Selalu Sediakan Font Fallback?<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\"><code>font-family: \\\"Segoe UI\\\", Arial, sans-serif;<\\/code> daftar ini adalah urutan prioritas. Jika font pertama tidak tersedia di device pengguna (misalnya user pakai Linux\\/HP tanpa font tersebut ter-install), browser otomatis pindah ke font berikutnya. <strong>Jika tidak diberi fallback<\\/strong>, dan font utama gagal dimuat, browser akan menggunakan font default yang tidak konsisten antar device.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>5.2 Satuan Ukuran: px vs em vs rem<\\/strong><\\/h3>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Satuan\",\"Sifat\",\"Kapan dipakai\"],\"rows\":[[\"`px`\",\"Absolut, tetap\",\"Border, shadow, elemen kecil yang tidak perlu scaling\"],[\"`em`\",\"Relatif ke font-size parent\",\"terdekat\\tBisa \\\"menumpuk\\\" (compounding) \\u2014 hati-hati\"],[\"`rem`\",\"Relatif ke font-size root (html)\",\"Disarankan untuk font-size, spacing, agar konsisten dan mudah diskalakan\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Kenapa <\\/strong><code><strong>rem<\\/strong><\\/code><strong> lebih disukai daripada <\\/strong><code><strong>px<\\/strong><\\/code><strong> untuk font?<\\/strong> Karena <code>rem<\\/code> menghormati pengaturan aksesibilitas browser pengguna (misalnya user memperbesar font default browser untuk kenyamanan mata). Kalau kamu memaksa <code>px<\\/code>, ukuran teks di layar user akan tetap kaku sebesar itu mengabaikan preferensi aksesibilitas mereka. <code>rem<\\/code> juga membuat perubahan skala global jadi mudah: cukup ubah <code>font-size<\\/code> di <code>html<\\/code>, seluruh elemen yang pakai <code>rem<\\/code> ikut menyesuaikan proporsional.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\"><strong>Kenapa <\\/strong><code><strong>em<\\/strong><\\/code><strong> bisa berbahaya?<\\/strong> Karena bersifat relatif ke parent, jika elemen bersarang dalam (nested), ukurannya bisa \\\"membengkak\\\" tanpa disadari:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".parent { font-size: 20px; }\\n.child { font-size: 1.5em; }       \\/* = 30px *\\/\\n.grandchild { font-size: 1.5em; }  \\/* = 45px, bukan 30px! karena relatif ke .child *\\/\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"6. Positioning\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Property <code>position<\\/code> menentukan bagaimana elemen ditempatkan relatif terhadap elemen lain.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".static    { position: static; }    \\/* default \\u2014 mengikuti alur normal dokumen *\\/\\n.relative  { position: relative; top: 10px; left: 10px; }\\n.absolute  { position: absolute; top: 0; right: 0; }\\n.fixed     { position: fixed; bottom: 20px; right: 20px; }\\n.sticky    { position: sticky; top: 0; }\"},{\"type\":\"tabel\",\"headers\":[\"Nilai\",\"Perilaku\",\"Contoh Penggunaan\"],\"rows\":[[\"`static`\",\"Default, tidak bisa diatur `top\\/left\\/right\\/bottom`\",\"Elemen biasa\"],[\"`relative`\",\"Bergeser dari posisi aslinya, tapi tetap \\\"menyisakan ruang\\\" di layout asal\",\"Membuat elemen jadi referensi untuk child `absolute`\"],[\"`absolute`\",\"Keluar dari alur dokumen, posisi mengikuti ancestor terdekat yang `position`-nya bukan `static`\",\"Badge notifikasi, dropdown menu, tooltip\"],[\"`fixed`\",\"Posisi tetap relatif ke viewport, tidak ikut scroll\",\"Tombol \\\"back to top\\\", navbar melayang\"],[\"`sticky`\",\"Bertingkah seperti `relative `sampai titik scroll tertentu, lalu \\\"menempel\\\" seperti `fixed`\",\"Header tabel, navbar yang menempel saat discroll\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<h3 class=\\\"ql-align-justify\\\"><strong>6.1 Konsep Kunci: \\\"Positioning Context\\\"<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\"><code>absolute<\\/code> <strong>selalu<\\/strong> mencari ancestor terdekat yang punya <code>position<\\/code> selain <code>static<\\/code> sebagai acuan. Kalau tidak ketemu, acuannya adalah <code>&lt;html&gt;<\\/code> (viewport dokumen).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".card {\\n  position: relative;   \\/* jadi \\\"acuan\\\" untuk child absolute *\\/\\n}\\n.badge {\\n  position: absolute;\\n  top: 5px;\\n  right: 5px;            \\/* akan menempel di pojok kanan-atas .card, bukan halaman *\\/\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Jika <\\/strong><code><strong>.card<\\/strong><\\/code><strong> tidak diberi <\\/strong><code><strong>position: relative<\\/strong><\\/code>, maka <code>.badge<\\/code> akan mencari ancestor lain di atasnya bisa jadi melompat ke pojok kanan atas seluruh halaman, bukan pojok kartu. Ini salah satu bug positioning paling umum: lupa memberi <code>position: relative<\\/code> pada parent.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"7. Flexbox\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Flexbox dirancang untuk mengatur elemen dalam <strong>satu dimensi<\\/strong>  baris (row) <em>atau<\\/em> kolom (column).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".container {\\n  display: flex;\\n  flex-direction: row;        \\/* row | column *\\/\\n  justify-content: center;    \\/* pengaturan sumbu utama (horizontal jika row) *\\/\\n  align-items: center;        \\/* pengaturan sumbu silang (vertikal jika row) *\\/\\n  gap: 16px;\\n  flex-wrap: wrap;\\n}\\n\\n.item {\\n  flex: 1;    \\/* elemen tumbuh mengisi ruang tersedia secara proporsional *\\/\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<h3 class=\\\"ql-align-justify\\\"><strong>7.1 Kenapa Flexbox Ada? (Masalah Sebelum Flexbox)<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\">Sebelum Flexbox populer (sekitar 2015-an), developer membuat layout dengan <code>float<\\/code> atau <code>display: inline-block<\\/code>, yang punya banyak masalah:<\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Elemen <code>float<\\/code> keluar dari alur normal, sehingga parent-nya bisa \\\"collapse\\\" (tinggi jadi 0) perlu trik <code>clearfix<\\/code><\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Centering vertikal itu <strong>sangat sulit<\\/strong> tanpa Flexbox (butuh trik <code>position<\\/code> + <code>transform<\\/code>, atau tabel)<\\/li><\\/ol><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\">Dengan Flexbox, centering elemen secara vertikal &amp; horizontal cukup:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".center {\\n  display: flex;\\n  justify-content: center;\\n  align-items: center;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Jika tidak menggunakan Flexbox<\\/strong> untuk kasus seperti navbar (logo di kiri, menu di kanan, sejajar vertikal), kamu harus menghitung posisi manual dengan <code>position: absolute<\\/code> dan <code>margin<\\/code>, yang rapuh terhadap perubahan ukuran konten.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>7.2 Properti Kunci<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\"><strong>Pada container (parent):<\\/strong><\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>justify-content<\\/code> - mengatur sumbu utama (main axis)<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>align-items<\\/code> - mengatur sumbu silang (cross axis)<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>flex-wrap<\\/code> - apakah item boleh pindah baris jika ruang tidak cukup<\\/li><\\/ol><p class=\\\"ql-align-justify\\\"><strong>Pada item (child):<\\/strong><\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>flex-grow<\\/code> - seberapa besar item \\\"menyerap\\\" ruang kosong<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>flex-shrink<\\/code> - seberapa besar item boleh menyusut<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>flex-basis<\\/code> - ukuran awal sebelum grow\\/shrink dihitung<\\/li><\\/ol><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"8. CSS Grid\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Grid dirancang untuk mengatur elemen dalam <strong>dua dimensi<\\/strong> sekaligus baris <strong>dan<\\/strong> kolom.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".container {\\n  display: grid;\\n  grid-template-columns: repeat(3, 1fr);   \\/* 3 kolom sama lebar *\\/\\n  grid-template-rows: auto 200px auto;\\n  gap: 20px;\\n}\\n\\n.item-hero {\\n  grid-column: 1 \\/ 3;   \\/* elemen ini melebar 2 kolom *\\/\\n  grid-row: 1 \\/ 2;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<h3 class=\\\"ql-align-justify\\\"><strong>8.1 Kenapa Grid Dibutuhkan Kalau Sudah Ada Flexbox?<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\">Flexbox itu satu dimensi kalau kamu punya banyak baris, setiap baris \\\"tidak tahu-menahu\\\" ukuran kolom di baris lain, sehingga kolom antar baris <strong>tidak otomatis sejajar<\\/strong> kecuali diatur manual dengan trik tambahan.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\">Coba bayangkan membuat layout <strong>galeri foto<\\/strong> atau <strong>dashboard<\\/strong> dengan banyak baris &amp; kolom yang harus sejajar rapi  dengan Flexbox kamu harus membungkus banyak <code>div<\\/code> bersarang dan menghitung lebar manual. Dengan Grid, cukup definisikan struktur kolom &amp; baris sekali di parent, lalu setiap item otomatis menempati sel gridnya, bahkan bisa melintasi beberapa kolom\\/baris sekaligus (<code>grid-column: span 2<\\/code>).<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\">Grid juga mendukung template area yang sangat deskriptif:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\".layout {\\n  display: grid;\\n  grid-template-areas:\\n    \\\"header header\\\"\\n    \\\"sidebar content\\\"\\n    \\\"footer footer\\\";\\n  grid-template-columns: 200px 1fr;\\n}\\n.header  { grid-area: header; }\\n.sidebar { grid-area: sidebar; }\\n.content { grid-area: content; }\\n.footer  { grid-area: footer; }\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Bandingkan dengan cara lama (float\\/table layout) yang butuh markup HTML tambahan hanya demi keperluan visual Grid memisahkan struktur visual dari struktur HTML, sehingga HTML tetap semantik.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>8.2 Flexbox vs Grid: Kapan Pakai yang Mana?<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\">Ini pertanyaan yang <strong>sering <\\/strong>ditanyakan oleh pemula:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Aspek\\t\",\"Flexbox\\t\",\"Grid\"],\"rows\":[[\"Dimensi\",\"1 dimensi (baris atau kolom)\",\"2 dimensi (baris dan kolom sekaligus)\"],[\"Cocok untuk\",\"Navbar, tombol sejajar, daftar item, centering\",\"Layout halaman keseluruhan, dashboard, galeri foto\"],[\"Kontrol ukuran\\t\\t\",\"Item menyesuaikan konten (content-first)\",\"Kolom\\/baris didefinisikan dulu, item mengikuti (layout-first)\"],[\"Sifat\\t\\t\",\"Elemen bisa \\\"mengalir\\\" fleksibel\",\"Struktur grid lebih kaku & presisi\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Aturan praktis:<\\/strong> Kalau kamu berpikir <em>\\\"saya ingin mengatur baris ATAU kolom\\\"<\\/em> - <strong>Flexbox<\\/strong>. Kalau kamu berpikir <em>\\\"saya ingin mengatur baris DAN kolom sekaligus, dan ingin semuanya sejajar rapi\\\"<\\/em> - <strong>Grid<\\/strong>. Faktanya, dalam proyek nyata, keduanya sering dipakai <strong>bersamaan<\\/strong>: Grid untuk struktur besar halaman (header, sidebar, content, footer), dan Flexbox untuk menyusun elemen-elemen kecil di dalam masing-masing bagian tersebut (misalnya isi navbar).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"9. Media Query & Responsive Design\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Responsive design adalah pendekatan membuat 1 halaman web yang tampilannya menyesuaikan diri di berbagai ukuran layar - dari HP, tablet, hingga desktop - tanpa perlu membuat halaman terpisah untuk tiap device.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>9.1 Kenapa Responsive Design Wajib?<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\">Bayangkan tanpa responsive design: layout 3 kolom yang didesain untuk layar desktop 1200px, dibuka di HP dengan layar 375px. Kolom-kolom itu akan \\\"diperas\\\" jadi sangat sempit, teks jadi tidak terbaca, atau malah muncul scrollbar horizontal yang mengharuskan user menggeser layar ke samping - pengalaman yang sangat buruk. Mengingat mayoritas trafik web saat ini datang dari perangkat mobile, mengabaikan responsive design berarti mengabaikan sebagian besar calon pengguna.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>9.2 Media Query<\\/strong><\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"\\/* Style default untuk mobile (mobile-first) *\\/\\n.container {\\n  display: flex;\\n  flex-direction: column;\\n}\\n\\n\\/* Saat layar minimal 768px (tablet ke atas) *\\/\\n@media (min-width: 768px) {\\n  .container {\\n    flex-direction: row;\\n  }\\n}\\n\\n\\/* Saat layar minimal 1024px (desktop) *\\/\\n@media (min-width: 1024px) {\\n  .container {\\n    max-width: 1200px;\\n    margin: 0 auto;\\n  }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>9.3 Mobile-First vs Desktop-First<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Pendekatan\\t\",\"Cara kerja\\t\",\"Kelebihan\"],\"rows\":[[\"Mobile-first (disarankan)\\t\\t\",\"Style dasar untuk mobile, lalu min-width menambah kompleksitas untuk layar besar\",\"CSS lebih ringan di HP (device dengan resource paling terbatas dilayani duluan), memaksa developer fokus konten prioritas\"],[\"Desktop-first\\t\\t\",\"Style dasar untuk desktop, lalu max-width menyederhanakan untuk layar kecil\",\"Lebih intuitif jika desain awal dibuat untuk desktop, tapi sering menghasilkan CSS override yang lebih rumit\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Kenapa mobile-first jadi standar industri saat ini?<\\/strong> Karena lebih mudah \\\"menambahkan\\\" kompleksitas seiring bertambah lebarnya layar, dibanding \\\"membongkar\\\" layout kompleks jadi sederhana. Selain itu, browser mobile akan mengunduh &amp; memproses CSS lebih sedikit karena style tambahan hanya dimuat saat kondisi <code>min-width<\\/code> terpenuhi.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>9.4 Breakpoint Umum (Acuan, Bukan Aturan Mutlak)<\\/strong><\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"\\/* Extra small (HP) - default, tanpa media query *\\/\\n\\/* Small (tablet portrait) *\\/\\n@media (min-width: 576px)  { }\\n\\/* Medium (tablet landscape) *\\/\\n@media (min-width: 768px)  { }\\n\\/* Large (laptop) *\\/\\n@media (min-width: 992px)  { }\\n\\/* Extra large (desktop) *\\/\\n@media (min-width: 1200px) { }\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Catatan penting: breakpoint sebaiknya ditentukan berdasarkan <strong>di titik mana layout mulai \\\"rusak\\\"<\\/strong> (konten berantakan \\/ terlalu renggang), bukan berdasarkan ukuran device tertentu karena ukuran layar device di pasaran sangat beragam dan terus berubah.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><h3 class=\\\"ql-align-justify\\\"><strong>9.5 Unit Responsif Tambahan<\\/strong><\\/h3><p class=\\\"ql-align-justify\\\">Selain media query, elemen berikut membantu membuat layout otomatis fleksibel tanpa banyak breakpoint:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"img { max-width: 100%; height: auto; }  \\/* gambar tidak akan melebihi lebar container *\\/\\n\\n.grid {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\\n  \\/* kolom otomatis menyesuaikan jumlah sesuai lebar layar, tanpa perlu media query! *\\/\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Kenapa ini penting ditekankan?<\\/strong> Pemula sering berpikir \\\"responsive = banyak media query\\\". Padahal, kombinasi Flexbox\\/Grid dengan unit fleksibel (<code>fr<\\/code>, <code>%<\\/code>, <code>minmax()<\\/code>, <code>auto-fit<\\/code>) bisa membuat layout responsif secara alami dengan <strong>jauh lebih sedikit<\\/strong> kode media query.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"10. Rangkuman\"},{\"type\":\"tabel\",\"headers\":[\"Konsep\\t\",\"Fungsi Utama\\t\",\"Analogi\"],\"rows\":[[\"Selector\\t\\t\",\"Menunjuk elemen mana yang di-style\",\"Alamat rumah\"],[\"Cascade & Specificity\\t\\t\",\"Menentukan aturan mana yang menang saat bentrok\",\"Hierarki komando\"],[\"Box Model\\t\\t\",\"Struktur ruang tiap elemen\",\"Kotak berlapis (isi, bantalan, bingkai, jarak)\"],[\"Typography\\t\\t\",\"Keterbacaan & estetika teks\",\"Tata letak huruf di buku\"],[\"Positioning\\t\\t\",\"Menempatkan elemen di luar alur normal\",\"Menempel stiker di posisi tertentu\"],[\"Flexbox\\t\\t\",\"Layout 1 dimensi\",\"Barisan orang mengantre\"],[\"Grid\\t\\t\",\"Layout 2 dimensi\",\"Papan catur\"],[\"Media Query\\t\\t\",\"Adaptasi tampilan sesuai layar\",\"Baju yang menyesuaikan ukuran badan\"]],\"caption\":\"\"},{\"type\":\"subbab\",\"judul\":\"Pengantar JavaScript Dasar & Manipulasi DOM\",\"judul_idn\":null},{\"type\":\"paragraf\",\"teks\":\"<p>HTML digunakan untuk membuat struktur web, CSS untuk desain web, sedangkan <strong>JavaScript (JS)<\\/strong> bertugas untuk memberikan <em>logika<\\/em> dan <em>interaktivitas<\\/em> pada web (membuat web menjadi lebih \\\"hidup\\\").<\\/p>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buat folder baru di komputer\\/laptop dengan nama <code>Praktikum-JS<\\/code>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buka folder tersebut menggunakan Visual Studio Code.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buat dua buah file baru: <code>index.html<\\/code> dan <code>script.js<\\/code>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Tuliskan struktur dasar HTML pada <code>index.html<\\/code> dan hubungkan file JS menggunakan tag <code>&lt;script&gt;<\\/code> tepat di atas tag penutup <code>&lt;\\/body&gt;<\\/code>.<\\/li><\\/ol><p>Kode <code>index.html<\\/code>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<!DOCTYPE html>\\n<html lang=\\\"id\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Praktikum JavaScript Dasar<\\/title>\\n<\\/head>\\n<body>\\n    <h1>Selamat Datang di Praktikum JavaScript<\\/h1>\\n    <p>Silakan buka Console Browser untuk melihat output.<\\/p>\\n    \\n    <!-- Menghubungkan JS eksternal -->\\n    <script src=\\\"script.js\\\"><\\/script>\\n<\\/body>\\n<\\/html>\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buka <code>index.html<\\/code> di browser.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik kanan pada halaman browser -&gt; pilih <strong>Inspect (Inspeksi)<\\/strong> -&gt; pindah ke tab <strong>Console<\\/strong>. Ini adalah tempat kita melihat proses JavaScript yang berjalan di latar belakang.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"VARIABEL & TIPE DATA\"},{\"type\":\"paragraf\",\"teks\":\"<p>Variabel adalah wadah untuk menyimpan data. JavaScript modern menggunakan <code>let<\\/code> (nilainya bisa diubah) dan <code>const<\\/code> (nilainya tetap\\/konstan). Tipe data dasar meliputi <em>String<\\/em> (teks), <em>Number<\\/em> (angka), dan <em>Boolean<\\/em> (true\\/false).<\\/p><p>Buka file <code>script.js<\\/code> dan ketikkan kode berikut:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"console.log(\\\"=== BAGIAN 2: VARIABEL & TIPE DATA ===\\\");\\n\\n\\/\\/ 1. Menggunakan let (Bisa diubah)\\nlet namaMahasiswa = \\\"Budi Santoso\\\";\\nconsole.log(\\\"Nama Awal:\\\", namaMahasiswa);\\n\\nnamaMahasiswa = \\\"Andi Wijaya\\\"; \\/\\/ Mengubah isi variabel\\nconsole.log(\\\"Nama Setelah Diubah:\\\", namaMahasiswa);\\n\\n\\/\\/ 2. Menggunakan const (Tidak bisa diubah)\\nconst nim = \\\"2026101010\\\";\\nconsole.log(\\\"NIM:\\\", nim);\\n\\/\\/ nim = \\\"2026101011\\\"; \\/\\/ Jika baris ini diaktifkan, akan terjadi Error!\\n\\n\\/\\/ 3. Tipe Data\\nlet umur = 20; \\/\\/ Number\\nlet ipk = 3.85; \\/\\/ Number (Desimal)\\nlet isLulus = true; \\/\\/ Boolean\\n\\nconsole.log(\\\"Umur saya \\\" + umur + \\\" tahun.\\\");\"},{\"type\":\"paragraf\",\"teks\":\"<p>Simpan file dan cek Console di browser. Pastikan tidak ada error.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"STRUKTUR KONTROL (LOGIKA & PERULANGAN)\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>If...Else:<\\/strong> Digunakan untuk mengambil keputusan berdasarkan kondisi tertentu.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>For Loop:<\\/strong> Digunakan untuk menjalankan kode secara berulang-ulang selama kondisi terpenuhi.<\\/li><\\/ol><p>Tambahkan kode berikut di bawah kode sebelumnya pada <code>script.js<\\/code>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"console.log(\\\"\\\\n=== BAGIAN 3: LOGIKA & PERULANGAN ===\\\");\\n\\n\\/\\/ 1. Percabangan (If - Else If - Else)\\nlet nilaiAkhir = 75;\\n\\nif (nilaiAkhir >= 80) {\\n    console.log(\\\"Grade: A - Lulus dengan Sangat Baik\\\");\\n} else if (nilaiAkhir >= 60) {\\n    console.log(\\\"Grade: B - Lulus\\\");\\n} else {\\n    console.log(\\\"Grade: C - Belum Lulus, silakan mengulang\\\");\\n}\\n\\n\\/\\/ 2. Perulangan (For Loop)\\n\\/\\/ Format: for (nilai_awal; batas_kondisi; penambahan)\\nconsole.log(\\\"Menampilkan bilangan genap dari 2 sampai 10:\\\");\\nfor (let i = 2; i <= 10; i += 2) {\\n    console.log(\\\"Angka Genap: \\\" + i);\\n}\"},{\"type\":\"subheading\",\"teks\":\"FUNCTION (FUNGSI)\"},{\"type\":\"paragraf\",\"teks\":\"<p>Fungsi adalah blok kode yang dirancang untuk melakukan tugas tertentu dan bisa dipanggil berkali-kali tanpa harus menulis ulang kodenya. Terdapat fungsi tradisional dan <em>Arrow Function<\\/em> (fitur JS modern ES6).<\\/p><p>Tambahkan kode berikut pada <code>script.js<\\/code>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"console.log(\\\"\\\\n=== BAGIAN 4: FUNCTION ===\\\");\\n\\n\\/\\/ 1. Fungsi Tradisional\\nfunction hitungLuasSegitiga(alas, tinggi) {\\n    let luas = 0.5 * alas * tinggi;\\n    return luas;\\n}\\n\\n\\/\\/ Memanggil fungsi\\nlet hasilLuas = hitungLuasSegitiga(10, 5);\\nconsole.log(\\\"Luas Segitiga (alas 10, tinggi 5) adalah: \\\" + hasilLuas);\\n\\n\\/\\/ 2. Arrow Function\\nconst sapaUser = (nama) => {\\n    console.log(\\\"Halo, \\\" + nama + \\\"! Selamat belajar JS.\\\");\\n}\\n\\nsapaUser(\\\"Mahasiswa Web\\\");\"},{\"type\":\"subheading\",\"teks\":\"MANIPULASI DOM & EVENT LISTENER\"},{\"type\":\"paragraf\",\"teks\":\"<p>DOM (<em>Document Object Model<\\/em>) adalah representasi struktur HTML web kita. Dengan JS, kita bisa mengambil elemen HTML (seperti paragraf, tombol, dll) dan mengubahnya secara dinamis (mengubah warna, teks, dll). <em>Event Listener<\\/em> bertugas \\\"mendengarkan\\\" aksi user (seperti saat tombol diklik).<\\/p><p><strong>1. Ubah file <\\/strong><code><strong>index.html<\\/strong><\\/code><strong>:<\\/strong> Tambahkan elemen-elemen berikut di dalam tag <code>&lt;body&gt;<\\/code> (di atas tag script):<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<hr>\\n    <h2>Latihan DOM (Document Object Model)<\\/h2>\\n    <p id=\\\"teks-dom\\\">Ini adalah teks asli dari HTML.<\\/p>\\n    <button id=\\\"btn-ubah-teks\\\">Ubah Teks & Warna<\\/button>\"},{\"type\":\"paragraf\",\"teks\":\"<p>2. Tambahkan kode berikut pada <code>script.js<\\/code>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"console.log(\\\"\\\\n=== BAGIAN 5: DOM & EVENT LISTENER ===\\\");\\n\\n\\/\\/ Tahap 1: Seleksi Elemen dari HTML\\nconst teksDom = document.getElementById(\\\"teks-dom\\\");\\nconst btnUbah = document.getElementById(\\\"btn-ubah-teks\\\");\\n\\n\\/\\/ Tahap 2: Tambahkan Event Listener (Event \'click\')\\nbtnUbah.addEventListener(\\\"click\\\", function() {\\n    \\/\\/ Aksi yang dijalankan saat tombol diklik\\n    teksDom.textContent = \\\"Teks ini telah diubah menggunakan JavaScript!\\\";\\n    teksDom.style.color = \\\"red\\\";\\n    teksDom.style.fontWeight = \\\"bold\\\";\\n    \\n    \\/\\/ Munculkan notifikasi alert\\n    alert(\\\"Berhasil mengubah teks!\\\");\\n});\"},{\"type\":\"paragraf\",\"teks\":\"<p>Kembali ke browser, coba klik tombol \\\"Ubah Teks &amp; Warna\\\" dan lihat apa yang terjadi pada halaman web.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"MINI PROJECT - INTERACTIVE COUNTER\"},{\"type\":\"paragraf\",\"teks\":\"<p>Sebagai penerapan seluruh materi di atas, mari kita membuat aplikasi penghitung (Counter).<\\/p><p>1. Tambahkan ke dalam <code>index.html<\\/code>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<hr>\\n    <h2>Mini Project: Penghitung (Counter)<\\/h2>\\n    \\n    <!-- inline CSS sederhana agar tampilan di tengah -->\\n    <div style=\\\"text-align: center; border: 1px solid #ccc; padding: 20px; width: 300px;\\\">\\n        <h1 id=\\\"angka-counter\\\" style=\\\"font-size: 50px; margin: 10px;\\\">0<\\/h1>\\n        <button id=\\\"btn-kurang\\\" style=\\\"padding: 10px 20px;\\\">Kurang (-)<\\/button>\\n        <button id=\\\"btn-tambah\\\" style=\\\"padding: 10px 20px;\\\">Tambah (+)<\\/button>\\n        <br><br>\\n        <button id=\\\"btn-reset\\\">Reset<\\/button>\\n    <\\/div>\"},{\"type\":\"paragraf\",\"teks\":\"<p>2. Tambahkan logika berikut pada <code>script.js<\\/code>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ --- MINI PROJECT COUNTER ---\\n\\n\\/\\/ 1. Seleksi Elemen\\nconst teksAngka = document.getElementById(\\\"angka-counter\\\");\\nconst btnTambah = document.getElementById(\\\"btn-tambah\\\");\\nconst btnKurang = document.getElementById(\\\"btn-kurang\\\");\\nconst btnReset = document.getElementById(\\\"btn-reset\\\");\\n\\n\\/\\/ 2. Buat Variabel Penampung Angka\\nlet angka = 0;\\n\\n\\/\\/ 3. Logika Tombol Tambah\\nbtnTambah.addEventListener(\\\"click\\\", function() {\\n    angka++; \\/\\/ artinya angka = angka + 1\\n    teksAngka.textContent = angka;\\n    teksAngka.style.color = \\\"green\\\"; \\/\\/ warna teks hijau jika ditambah\\n});\\n\\n\\/\\/ 4. Logika Tombol Kurang\\nbtnKurang.addEventListener(\\\"click\\\", function() {\\n    \\/\\/ Syarat opsional: Angka tidak boleh minus\\n    if (angka > 0) {\\n        angka--; \\n        teksAngka.textContent = angka;\\n        teksAngka.style.color = \\\"red\\\"; \\/\\/ warna teks merah jika dikurang\\n    } else {\\n        alert(\\\"Angka sudah mencapai 0!\\\");\\n    }\\n});\\n\\n\\/\\/ 5. Logika Tombol Reset\\nbtnReset.addEventListener(\\\"click\\\", function() {\\n    angka = 0;\\n    teksAngka.textContent = angka;\\n    teksAngka.style.color = \\\"black\\\";\\n});\"},{\"type\":\"subheading\",\"teks\":\"LIVE CODINGGGGGGG\\ud83d\\udd25\\ud83d\\udd25\\ud83d\\udd25\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Modifikasi Counter:<\\/strong> Tambahkan fitur agar setiap kali nilai mencapai kelipatan 10 (10, 20, 30, dst), munculkan pop-up pesan <code>alert(\\\"Selamat, Anda mencapai \\\" + angka)!<\\/code>. <em>Clue: Gunakan operator Modulus (<\\/em><code><em>%<\\/em><\\/code><em>) di dalam event listener tambah.<\\/em><\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Kalkulator Luas Persegi Panjang:<\\/strong> Buatlah form sederhana (menggunakan tag <code>&lt;input&gt;<\\/code>) di HTML untuk memasukkan \\\"Panjang\\\" dan \\\"Lebar\\\". Buat tombol \\\"Hitung Luas\\\". Saat tombol diklik, JavaScript harus mengambil nilai (value) dari kedua input tersebut, menghitungnya, dan menampilkannya pada tag <code>&lt;p&gt;<\\/code> yang ada di bawah tombol.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subbab\",\"judul\":\"JavaScript Lanjutan: DOM Dinamis, Asynchronous JavaScript, dan Fetch API\",\"judul_idn\":null},{\"type\":\"gambar\",\"url\":\"https:\\/\\/s3-cdn.cmlabs.co\\/page\\/2024\\/01\\/04\\/apa-itu-api-pengertian-jenis-fungsi-dan-contohnya-295094.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading\",\"teks\":\"DOM Dinamis\"},{\"type\":\"paragraf\",\"teks\":\"<p>Selama ini kita biasanya ngubah elemen yang udah ada di file HTML (misal ganti warna atau ganti teks). Lewat DOM Dinamis, JavaScript bisa <strong>bikin elemen HTML baru dari nol<\\/strong> secara otomatis lewat kode.<\\/p><p>Kenapa nggak ditulis langsung aja di file HTML?<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Di file HTML biasa, tampilannya kaku dan statis.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Lewat JavaScript, kita bisa bikin elemen baru sesuai aksi user (misal user klik tombol tambah) atau mencetak puluhan data dari database tanpa ngetik tag HTML satu per satu secara manual.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<p>Proses bikin elemen baru di JavaScript kurang lebih selalu ngikutin 4 langkah:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"\\/\\/ 1. Siapkan Wadah Tujuan\\nconst container = document.querySelector(\\\"#container\\\");\\n\\n\\/\\/ 2. Bikin Elemen Baru\\nconst card = document.createElement(\\\"div\\\");\\n\\n\\/\\/ 3. Hias Elemen\\ncard.textContent = \\\"Data Mahasiswa\\\";\\ncard.classList.add(\\\"card\\\");\\n\\n\\/\\/ 4. Tempel ke Halaman Web\\ncontainer.appendChild(card);\"},{\"type\":\"paragraf\",\"teks\":\"<p>Hasil akhirnya di browser sama persis seperti kita ngetik manual di file HTML:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<div id=\\\"container\\\">\\n    <div class=\\\"card\\\">Data Mahasiswa<\\/div>\\n<\\/div>\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Praktik Langsung: Fitur Tambah Skill<\\/strong><\\/p><p>Biar kelihatan fungsinya di aplikasi nyata, kita gabungin 4 langkah tadi dengan event tombol dan input teks dari user.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<h2>Skill Saya<\\/h2>\\n\\n<input type=\\\"text\\\" id=\\\"skillInput\\\" placeholder=\\\"Masukkan skill\\\">\\n<button id=\\\"addSkill\\\">Tambah<\\/button>\\n\\n<ul id=\\\"skillList\\\"><\\/ul>\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"const skillInput = document.querySelector(\\\"#skillInput\\\");\\nconst addSkill = document.querySelector(\\\"#addSkill\\\");\\nconst skillList = document.querySelector(\\\"#skillList\\\");\\n\\naddSkill.addEventListener(\\\"click\\\", () => {\\n    const skill = skillInput.value;\\n\\n    \\/\\/ Jangan proses kalau input masih kosong\\n    if (skill === \\\"\\\") {\\n        return;\\n    }\\n\\n    \\/\\/ 1. Buat tag <li> baru\\n    const li = document.createElement(\\\"li\\\");\\n\\n    \\/\\/ 2. Isi teksnya dengan apa yang diketik user\\n    li.textContent = skill;\\n\\n    \\/\\/ 3. Masukkan ke dalam <ul>\\n    skillList.appendChild(li);\\n\\n    \\/\\/ 4. Kosongkan kembali form input\\n    skillInput.value = \\\"\\\";\\n});\"},{\"type\":\"subheading\",\"teks\":\"Synchronous JavaScript\"},{\"type\":\"paragraf\",\"teks\":\"<p>Secara bawaan, JavaScript ngerjain tugasnya secara <strong>Synchronous<\\/strong> (berurutan dari atas ke bawah). Baris berikutnya harus nunggu baris sebelumnya kelar.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"console.log(\\\"Mulai\\\");\\n\\nfor (let i = 1; i <= 3; i++) {\\n    console.log(\\\"Proses\\\", i);\\n}\\n\\nconsole.log(\\\"Selesai\\\");\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"Mulai\\nProses 1\\nProses 2\\nProses 3\\nSelesai\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Masalahnya:<\\/strong><\\/p><p>Gimana kalau salah satu baris kode butuh waktu lama? Misalnya minta data ke server luar negeri lewat internet lemot atau data yang ingin diambil jumlahnya ribuan bahkan jutaan.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Asynchronous\"},{\"type\":\"paragraf\",\"teks\":\"<p>Yap betul, Asynchronous adalah jawaban dari pertanyaan sebelumnya. Asynchronous ngebiarin proses yang butuh waktu lama berjalan di latar belakang. Kode baris berikutnya tetap bisa langsung jalan tanpa harus nungguin proses lambat itu beres.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"console.log(\\\"1. Mulai\\\");\\n\\n\\/\\/ Jalan 2 detik kemudian\\nsetTimeout(() => {\\n    console.log(\\\"2. Proses selesai!\\\");\\n}, 2000);\\n\\nconsole.log(\\\"3. Selesai\\\");\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"1. Mulai\\n3. Selesai\\n2. Proses berat selesai!\"},{\"type\":\"paragraf\",\"teks\":\"<p>Tulisan nomor 3 muncul duluan karena JavaScript nggak mau buang waktu nungguin <code>setTimeout<\\/code> beres. Hal yang sama berlaku waktu kita ngambil data dari server.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Promise\"},{\"type\":\"paragraf\",\"teks\":\"<p>Operasi asynchronous biasanya dibungkus dalam bentuk <strong>Promise<\\/strong>. Bayangkan kamu pesan makanan di kasir fast food: kamu dikasih struk pesanan (janji). Makananmu belum ada sekarang, tapi bakal datang nanti.<\\/p><p><strong>3 Status Promise:<\\/strong><\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Pending:<\\/strong> Masih nunggu proses kelar.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Fulfilled:<\\/strong> Janji ditepati (data berhasil didapat) $\\\\rightarrow$ ditangani lewat <code>.then()<\\/code>.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Rejected:<\\/strong> Janji gagal (misal server mati atau kuota habis) $\\\\rightarrow$ ditangani lewat <code>.catch()<\\/code>.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"prosesAmbilData()\\n    .then(data => {\\n        console.log(\\\"Berhasil dapat data:\\\", data);\\n    })\\n    .catch(error => {\\n        console.log(\\\"Ups, terjadi eror:\\\", error);\\n    });\"},{\"type\":\"subheading\",\"teks\":\"API & Format JSON\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/miro.medium.com\\/v2\\/resize:fit:1400\\/1*81khinFwqxmEtCRQ8wiv8w.jpeg\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>API (Application Programming Interface)<\\/strong> adalah jembatan komunikasi antar aplikasi. Frontend web kita minta data ke backend via URL yang disebut <strong>endpoint<\\/strong>.<\\/p><p>Misal kita panggil URL: <\\/p><p><code>[https:\\/\\/jsonplaceholder.typicode.com\\/users]<\\/code><\\/p><p>Server bakal ngirim balik data dalam format <strong>JSON<\\/strong> (<em>JavaScript Object Notation<\\/em>):<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"json\",\"kode\":\"Bentuknya mirip banget sama Array dan Object JavaScript biasa, jadi gampang banget diolah.\\n[\\n    {\\n        \\\"name\\\": \\\"Leanne Graham\\\",\\n        \\\"email\\\": \\\"Sincere@april.biz\\\",\\n        \\\"address\\\": { \\\"city\\\": \\\"Gwenborough\\\" }\\n    }\\n]\"},{\"type\":\"subheading\",\"teks\":\"Fetch API\"},{\"type\":\"paragraf\",\"teks\":\"<p>Browser punya fitur bawaan bernama <code>fetch()<\\/code> untuk ngambil data dari internet tanpa perlu reload halaman.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"fetch(\\\"https:\\/\\/jsonplaceholder.typicode.com\\/users\\\")\\n    .then(response => response.json()) \\/\\/ Ubah response mentah jadi format JSON\\n    .then(data => {\\n        console.log(\\\"Data diterima:\\\", data);\\n    })\\n    .catch(error => {\\n        console.log(\\\"Koneksi gagal:\\\", error);\\n    });\"},{\"type\":\"paragraf\",\"teks\":\"<p>Alur Kerjanya<\\/p><p>fetch(url) \\u2192 Kirim Request \\u2192 Response \\u2192 response.json() \\u2192 Data Siap Pakai<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Fetch + DOM\"},{\"type\":\"paragraf\",\"teks\":\"<p>Sekarang gabungin Fetch API sama manipulasi DOM. Data ribuan user dari server bisa kita cetak ke halaman web cuma pakai looping <code>forEach()<\\/code>.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<h1>Daftar Pengguna<\\/h1>\\n<div id=\\\"container\\\"><\\/div>\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"const container = document.querySelector(\\\"#container\\\");\\n\\nfetch(\\\"https:\\/\\/jsonplaceholder.typicode.com\\/users\\\")\\n    .then(response => response.json())\\n    .then(users => {\\n        \\/\\/ Cetak card untuk setiap user yang didapat dari server\\n        users.forEach(user => {\\n            container.innerHTML += `\\n                <div class=\\\"card\\\">\\n                    <h2>${user.name}<\\/h2>\\n                    <p>${user.email}<\\/p>\\n                    <p>${user.address.city}<\\/p>\\n                <\\/div>\\n            `;\\n        });\\n    });\"},{\"type\":\"subheading\",\"teks\":\"Loading & Error Handling\"},{\"type\":\"paragraf\",\"teks\":\"<p>Internet nggak selalu lancar. Kadang server lemot atau kuota user habis. Karena itu, UI wajib ngasih tahu statusnya ke user biar nggak bingung ngeliat layar kosong melompong.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<h1>Daftar Pengguna<\\/h1>\\n<p id=\\\"statusMsg\\\">Memuat data...<\\/p>\\n<div id=\\\"container\\\"><\\/div>\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"const container = document.querySelector(\\\"#container\\\");\\nconst statusMsg = document.querySelector(\\\"#statusMsg\\\");\\n\\nfetch(\\\"https:\\/\\/jsonplaceholder.typicode.com\\/users\\\")\\n    .then(response => {\\n        if (!response.ok) {\\n            throw new Error(\\\"Gagal mengambil data dari server\\\");\\n        }\\n        return response.json();\\n    })\\n    .then(users => {\\n        \\/\\/ Hapus teks loading setelah data sukses masuk\\n        statusMsg.textContent = \\\"\\\";\\n\\n        users.forEach(user => {\\n            container.innerHTML += `\\n                <div class=\\\"card\\\">\\n                    <h2>${user.name}<\\/h2>\\n                    <p>${user.email}<\\/p>\\n                    <p>${user.address.city}<\\/p>\\n                <\\/div>\\n            `;\\n        });\\n    })\\n    .catch(error => {\\n        \\/\\/ Tampilkan pesan eror jika ada masalah koneksi\\n        statusMsg.textContent = `${error.message}`;\\n        statusMsg.style.color = \\\"red\\\";\\n    });\"},{\"type\":\"subheading\",\"teks\":\"Modern Alternative: async \\/ await\"},{\"type\":\"paragraf\",\"teks\":\"<p>Penulisan <code>.then()<\\/code> berantai kadang bikin kode kelihatan berantakan kalau makin panjang. Di JavaScript modern, ada trik penulisan bernama <code>async\\/await<\\/code> biar kode asynchronous terbaca rapi mirip kode biasa.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"javascript\",\"kode\":\"async function getUsers() {\\n    try {\\n        statusMsg.textContent = \\\"Memuat data...\\\";\\n        \\n        \\/\\/ await bertugas menghentikan baris berikutnya sampai fetch selesai\\n        const response = await fetch(\\\"https:\\/\\/jsonplaceholder.typicode.com\\/users\\\");\\n        \\n        if (!response.ok) throw new Error(\\\"Gagal memuat data\\\");\\n\\n        const users = await response.json();\\n\\n        statusMsg.textContent = \\\"\\\";\\n        users.forEach(user => {\\n            container.innerHTML += `\\n                <div class=\\\"card\\\">\\n                    <h2>${user.name}<\\/h2>\\n                    <p>${user.email}<\\/p>\\n                    <p>${user.address.city}<\\/p>\\n                <\\/div>\\n            `;\\n        });\\n    } catch (error) {\\n        statusMsg.textContent = `Terjadi kesalahan: ${error.message}`;\\n    }\\n}\\n\\n\\/\\/ Jalankan fungsinya\\ngetUsers();\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>async<\\/code>: Menandai bahwa fungsi ini berjalan di latar belakang.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>await<\\/code>: Menghentikan langkah di baris itu sementara sampai datanya beres diambil.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>try...catch<\\/code>: Tempat buat nangkep eror kalau ada request yang gagal.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Pembeda\",\"Gaya Tradisional (.then \\/ .catch)\",\"Gaya Modern (async\\/await)\"],\"rows\":[[\"Gaya Penulisan\",\"Berantai (chaining callbacks)\",\"Mirip kode sekuensial biasa (synchronous)\"],[\"Error Handling\",\"Menggunakan method .catch() di akhir rantai\",\"Menggunakan blok standar try...catch\"],[\"Keterbacaan\",\"Masih mudah dipahami untuk proses sederhana, tetapi bisa lebih sulit dibaca jika rantainya panjang\",\"Umumnya lebih mudah dibaca karena alurnya terlihat linier\"],[\"Di Bawah Layar\",\"Berjalan di atas Promise\",\"Tetap menggunakan Promise; async\\/await adalah cara penulisan yang lebih nyaman di atas Promise\"],[\"Contoh\",\"fetch(url).then(...).catch(...)\",\"const response = await fetch(url)\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Jadi, biasanya pakai yang mana?<\\/strong><\\/p><p>Untuk project JavaScript modern, <code><strong>async\\/await<\\/strong><\\/code><strong> biasanya lebih sering digunakan<\\/strong>, terutama ketika terdapat beberapa proses asynchronous karena alurnya lebih mudah dibaca dan dipelihara.<\\/p><p>Namun, <code>.then()<\\/code> dan <code>.catch()<\\/code> <strong>bukan teknologi lama yang sudah tidak digunakan<\\/strong>. Keduanya tetap penting untuk dipahami karena banyak kode JavaScript dan library yang menggunakan Promise chaining.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subbab\",\"judul\":\"Tugas - Slicing Website HTML\\/CSS\\/JS\",\"judul_idn\":null},{\"type\":\"paragraf\",\"teks\":\"<p>Assalamu\'alaikum, temen-temen.<\\/p><p>Tugas : Slicing Website Bebas (Portfolio, Landing Page, Dashboard UI, Gojek dll.)<\\/p><p><br><\\/p><p><strong>\\ud83d\\udccc KETENTUAN PENTING:<\\/strong><\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Wajib responsive (mobile, tablet, desktop)<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Menerapkan HTML, CSS dan Javascript (DOM) <\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Menggunakan Plain CSS (jangan menggunakan Tailwind\\/Bootstrap)<\\/li><\\/ol><p>\\ud83d\\ude0b <strong>Yang Dikumpulkan: <\\/strong><\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Link repo GitHub (dengan Readme SS dan Penjelasan singkat)<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Link deployment bebas (Netlify\\/GitHub Pages\\/Vercel) <\\/li><\\/ol><p>*<strong>deadline menyesuaikan<\\/strong><\\/p><p>\\u2705 Deadline: Kamis, 24 September 23:59 WIB<\\/p><p>\\ud83d\\udd17 Form Pengumpulan : <\\/p>\",\"align\":\"kiri\"},{\"type\":\"link\",\"href\":\"https:\\/\\/forms.gle\\/TANnkVtgthrMWeG99\",\"label\":\"Form Pengumpulan Slicing\",\"desc\":\"\"},{\"type\":\"subbab\",\"judul\":\"Tailwind CSS\",\"judul_idn\":null},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1790224853\\/portfolio\\/courses\\/phphlp2ea2hag929c5JR81_yh6kur.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading\",\"teks\":\"Apa itu Tailwind Css\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Tailwind CSS adalah sebuah utility-first CSS framework. Berbeda dengan framework UI konvensional seperti Bootstrap atau Foundation yang menyediakan komponen siap pakai (seperti card, navbar, atau button), Tailwind menyediakan low-level utility classes (class fungsional tingkat rendah). Ini memungkinkan Anda untuk membangun desain antarmuka yang sangat kustom langsung dari dalam file HTML tanpa harus menulis satu baris kode CSS kustom pun.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Masalah pada Pendekatan CSS Biasa\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Sebelum membahas Lebih Lanjut Mengenai Tailwind, kita harus melihat masalah umum yang sering dihadapi engineer saat menggunakan CSS tradisional (vanilla CSS atau metodologi seperti BEM\\/OOCSS):<\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Context Switching yang Melelahkan : Anda harus terus berpindah-pindah tab antara file <code>index.html<\\/code> dan <code>style.css<\\/code> hanya untuk melihat efek perubahan yang Anda buat.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Mencari Nama Class yang Tepat (Naming Fatigue) : Memberi nama class seperti <code>.header-inner-wrapper-dark<\\/code> sangat subjektif dan memakan waktu. Seringkali nama ini membingungkan developer lain dalam satu tim.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ukuran File CSS yang Terus Membengkak : Dalam CSS tradisional, setiap kali Anda membuat fitur baru, Anda biasanya menambahkan kode CSS baru. Ukuran file akan tumbuh secara linear seiring bertambah besarnya proyek.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Specificity Wars : Konflik hierarki CSS yang memaksa Anda menggunakan selector yang panjang atau bahkan <code>!important<\\/code> hanya agar style bisa teraplikasi.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Apabila Memakai Tailwind \"},{\"type\":\"paragraf\",\"teks\":\"<p>Ketika Anda beralih ke Tailwind CSS, alur kerja dan penyelesaian masalah di atas berubah drastis:<\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Tidak Perlu Penamaan Class: Anda menggunakan class fungsional (utility) seperti <code>flex<\\/code>, <code>pt-4<\\/code>, <code>text-center<\\/code>, dan <code>rotate-90<\\/code>. Tidak ada lagi perdebatan tentang nama class.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Fokus 100% di HTML: Anda mendesain langsung di dalam file HTML (atau file komponen di React\\/Vue). Ini mempercepat development secara signifikan.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ukuran File Super Kecil di Production: Tailwind memiliki mesin kompilasi cerdas. Pada tahap rilis (build), Tailwind akan membuang semua class yang tidak Anda tulis di HTML, menghasilkan ukuran file CSS akhir yang seringkali di bawah 10kb.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Desain Sistem yang Konsisten: Anda dipaksa menggunakan skala ukuran, jarak, dan warna bawaan (yang dirancang secara matematis), sehingga UI terlihat konsisten tanpa banyak usaha.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Cara Menyambungkan Tailwind ke HTML\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Ada dua cara utama untuk mulai menggunakan Tailwind, tergantung pada kebutuhan Anda (prototyping cepat vs. lingkungan production).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"Metode A: Via CDN (Untuk Belajar & Prototyping)\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Cara ini sangat cepat karena hanya perlu menempelkan satu baris script. Namun, jangan gunakan ini untuk tahap production karena tidak dioptimasi dan ukurannya besar.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<!DOCTYPE html>\\n<html lang=\\\"id\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <title>Belajar Tailwind via CDN<\\/title>\\n    <!-- Script Tailwind v4 Browser CDN -->\\n    <script src=\\\"https:\\/\\/unpkg.com\\/@tailwindcss\\/browser@4\\\"><\\/script>\\n<\\/head>\\n<body class=\\\"bg-slate-100 flex justify-center items-center h-screen\\\">\\n    <h1 class=\\\"text-3xl font-bold text-blue-600\\\">Halo, Tailwind CDN!<\\/h1>\\n<\\/body>\\n<\\/html>\\n\"},{\"type\":\"subheading3\",\"teks\":\"Metode B: Via NPM (Standar Industri & Production)\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Ini adalah cara yang digunakan oleh software engineer profesional. Menggunakan standar Tailwind v4 terbaru, proses konfigurasinya telah disederhanakan tanpa memerlukan file JavaScript terpisah.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\"><strong>Langkah 1: Instalasi via Terminal<\\/strong><\\/p><p class=\\\"ql-align-justify\\\">Pastikan sudah menginstal Node.js, lalu jalankan perintah ini di direktori proyek:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"bash\",\"kode\":\"npm init -y\\nnpm install tailwindcss @tailwindcss\\/cli\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Langkah 2: Buat File Input CSS (src\\/input.css)<\\/strong><\\/p><p class=\\\"ql-align-justify\\\">Sesuai arsitektur Tailwind v4, seluruh konfigurasi kustomisasi sekarang diletakkan langsung di dalam file CSS utama, bukan di file konfigurasi eksternal.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"css\",\"kode\":\"\\/* src\\/input.css *\\/\\n@import \\\"tailwindcss\\\";\\n\\n\\/* Kustomisasi tema langsung diletakkan di dalam file CSS *\\/\\n@theme {\\n  --color-primary: #1d4ed8;\\n  --font-body: \\\"Inter\\\", sans-serif;\\n}\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Langkah 3: Siapkan File HTML (index.html)<\\/strong><\\/p><p class=\\\"ql-align-justify\\\">Hubungkan HTML Anda ke file CSS output yang akan dihasilkan (generate) oleh Tailwind.<\\/p><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<!DOCTYPE html>\\n<html lang=\\\"id\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <title>Tailwind via NPM<\\/title>\\n    <!-- Arahkan ke file hasil build -->\\n    <link href=\\\".\\/dist\\/output.css\\\" rel=\\\"stylesheet\\\">\\n<\\/head>\\n<body class=\\\"bg-primary text-white p-10 font-body\\\">\\n    <h1 class=\\\"text-4xl font-bold\\\">Instalasi NPM Berhasil<\\/h1>\\n<\\/body>\\n<\\/html>\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Langkah 4: Jalankan CLI Build Process<\\/strong><\\/p><p class=\\\"ql-align-justify\\\">Jalankan perintah ini di terminal agar Tailwind membaca HTML Anda dan mengompilasi CSS-nya ke dalam folder dist.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"bash\",\"kode\":\"npx @tailwindcss\\/cli -i .\\/src\\/input.css -o .\\/dist\\/output.css --watch\"},{\"type\":\"subheading\",\"teks\":\"Sizing & Spacing (Ukuran & Jarak)\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Tailwind menggunakan skala proporsional yang konsisten (biasanya 1 unit = 0.25rem atau 4px). Polanya sangat mudah diprediksi: tipe (margin\\/padding) + arah + nilai.<\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>p<\\/code> untuk padding (jarak ke dalam), <code>m<\\/code> untuk margin (jarak ke luar).<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Arah: <code>t<\\/code> (top), <code>b<\\/code> (bottom), <code>l<\\/code> (left), <code>r<\\/code> (right), <code>x<\\/code> (kiri-kanan), <code>y<\\/code> (atas-bawah). Jika arah dikosongkan, efeknya berlaku di semua sisi.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sizing (<code>w<\\/code> &amp; <code>h<\\/code>): Mengatur lebar (width) dan tinggi (height). Bisa menggunakan persentase (<code>w-1\\/2<\\/code>), ukuran layar (<code>h-screen<\\/code>), atau nilai absolut (<code>w-64<\\/code>).<\\/li><\\/ol><p><br><\\/p><p><strong>Contoh Implementasi:<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<!-- Sebuah kotak (card) dengan jarak margin luar, padding dalam, dan lebar spesifik -->\\n<div class=\\\"m-8 p-6 w-72 h-auto bg-white border border-gray-200\\\">\\n    Konten di dalam card ini memiliki jarak 1.5rem (24px) dari tepi border (karena p-6).\\n    Sedangkan card ini sendiri didorong sejauh 2rem (32px) dari elemen di sekitarnya (karena m-8).\\n<\\/div>\\n\"},{\"type\":\"subheading\",\"teks\":\"Colors & Typography (Warna & Tipografi)\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Tailwind menyediakan palet warna lengkap dari skala 50 (paling terang) hingga 950 (paling gelap). Tipografi juga ditangani lewat utilitas ringkas tanpa perlu menulis spesifikasi font-size atau line-height secara manual.<\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Warna Teks: <code>text-[warna]-[skala]<\\/code> (contoh: <code>text-blue-600<\\/code>).<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Warna Background: <code>bg-[warna]-[skala]<\\/code> (contoh: <code>bg-slate-100<\\/code>).<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ukuran Teks: <code>text-xs<\\/code>, <code>text-sm<\\/code>, <code>text-base<\\/code> (default), <code>text-lg<\\/code>, <code>text-xl<\\/code>, hingga <code>text-9xl<\\/code>.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ketebalan Font (Weight): <code>font-light<\\/code>, <code>font-normal<\\/code>, <code>font-semibold<\\/code>, <code>font-bold<\\/code>.<\\/li><\\/ol><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\"><strong>Contoh Implementasi:<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<div class=\\\"bg-slate-900 p-4\\\">\\n    <!-- Judul besar, tebal, dan berwarna putih -->\\n    <h1 class=\\\"text-2xl font-bold text-white\\\">Sistem Manajemen<\\/h1>\\n    \\n    <!-- Teks paragraf lebih kecil, warna abu-abu agar tidak terlalu kontras -->\\n    <p class=\\\"text-sm font-normal text-slate-400 mt-1\\\">\\n        Masuk ke dashboard untuk mengelola data anggota dan transaksi.\\n    <\\/p>\\n<\\/div>\\n\"},{\"type\":\"subheading\",\"teks\":\"Layouting (Flexbox & Grid)\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Membuat tata letak yang kompleks adalah keahlian utama Tailwind. Anda tidak perlu lagi menulis deklarasi <code>display: flex; justify-content: center;<\\/code> di CSS eksternal.<\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Flexbox: Gunakan flex untuk mengaktifkan flexbox. Kendalikan arah dengan <code>flex-row<\\/code> atau <code>flex-col<\\/code>. Atur perataan dengan <code>justify-between<\\/code>, <code>items-center<\\/code>, dll.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Grid: Gunakan grid untuk mengaktifkan CSS Grid. Definisikan jumlah kolom dengan <code>grid-cols-2<\\/code>, <code>grid-cols-3<\\/code>. Gunakan <code>gap-4<\\/code> untuk memberi jarak antar elemen.<\\/li><\\/ol><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\"><strong>Contoh Implementasi Flexbox (Navigasi):<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<nav class=\\\"flex justify-between items-center p-4 bg-white shadow\\\">\\n    <div class=\\\"font-bold text-lg\\\">LogoApp<\\/div>\\n    <ul class=\\\"flex gap-4\\\">\\n        <li>Beranda<\\/li>\\n        <li>Profil<\\/li>\\n    <\\/ul>\\n<\\/nav>\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Contoh Implementasi Grid (Daftar Produk\\/Layanan):<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<div class=\\\"grid grid-cols-2 gap-4 p-4\\\">\\n    <div class=\\\"bg-blue-100 p-4\\\">Item 1<\\/div>\\n    <div class=\\\"bg-green-100 p-4\\\">Item 2<\\/div>\\n    <div class=\\\"bg-yellow-100 p-4\\\">Item 3<\\/div>\\n    <div class=\\\"bg-red-100 p-4\\\">Item 4<\\/div>\\n<\\/div>\\n<!-- Hasilnya adalah kotak 2 baris x 2 kolom dengan jarak antar kotak seragam -->\\n\"},{\"type\":\"subheading\",\"teks\":\"Responsive Design (Desain Responsif)\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Tailwind menggunakan pendekatan Mobile-First. Artinya, class tanpa prefix (awalan) akan diaplikasikan dari ukuran layar paling kecil (HP) hingga tak terhingga. Untuk mengubah bentuk di layar yang lebih besar, gunakan breakpoint modifier seperti <code>sm:<\\/code>, <code>md:<\\/code>, <code>lg:<\\/code>, <code>xl:<\\/code>, <code>2xl:<\\/code>.<\\/p><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\"><strong>Contoh Implementasi:<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<!-- Di layar HP (default), elemen berjejer ke bawah (flex-col). -->\\n<!-- Ketika ukuran layar mencapai Medium (Tablet\\/Desktop), elemen berubah menyamping (md:flex-row). -->\\n<div class=\\\"flex flex-col md:flex-row gap-4 p-4\\\">\\n    <div class=\\\"w-full md:w-1\\/2 bg-gray-200 p-4\\\">Kolom Kiri<\\/div>\\n    <div class=\\\"w-full md:w-1\\/2 bg-gray-300 p-4\\\">Kolom Kanan<\\/div>\\n<\\/div>\\n\"},{\"type\":\"subheading\",\"teks\":\"States & Modifiers (Hover, Focus, Active)\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Untuk menangani interaksi pengguna, Tailwind menyediakan modifier pseudo-class. Anda cukup menambahkan awalan kondisi di depan class yang ingin diubah.<\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>hover:<\\/code> Saat kursor mouse berada di atas elemen.<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>focus:<\\/code> Saat elemen diklik\\/dipilih (berguna untuk input form atau tombol).<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>active:<\\/code> Saat tombol sedang ditekan.<\\/li><\\/ol><p class=\\\"ql-align-justify\\\"><br><\\/p><p class=\\\"ql-align-justify\\\"><strong>Contoh Implementasi (Tombol Interaktif):<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"html\",\"kode\":\"<!-- Tombol dasar berwarna biru. -->\\n<!-- Saat di-hover, warna berubah lebih gelap. -->\\n<!-- Saat diklik (focus), muncul cincin biru muda di luarnya. -->\\n<!-- transition-colors memberikan efek animasi transisi yang halus. -->\\n<button class=\\\"bg-blue-600 text-white font-semibold py-2 px-6 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-4 focus:ring-blue-300 transition-colors\\\">\\n    Simpan Data\\n<\\/button>\\n\"},{\"type\":\"subbab\",\"judul\":\"PHP (Hypertext Preprocessor)\",\"judul_idn\":null},{\"type\":\"paragraf\",\"teks\":\"<p>PHP merujuk pada bahasa pemrograman yang dijalankan dari sisi server (server side) dalam pembuatan dan pengembangan web.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Persiapan Tools\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Install XAMPP\\/Laragon (ada Apache + PHP + MySQL).<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Jika menggunakan XAMPP buka folder <code>htdocs\\/.<\\/code> didalam XAMPP dan buat file dengan ekstensi <code>.php<\\/code> di folder <code>htdocs\\/.<\\/code><\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Jika menggunakan laragon maka akses lewat folder laragon dan masuk folder <code>www<\\/code> dan bisa membuat file langsung misal <code>xample.php<\\/code><\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Akses via browser <code>http:\\/\\/localhost\\/namafile.php.<\\/code><\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"1. Struktur Dasar PHP\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\necho \\\"Hello World!\\\";\\n?>\"},{\"type\":\"paragraf\",\"teks\":\"<p>Semua kode PHP ditulis di dalam tag <code>&lt;?php ... ?&gt;<\\/code>. <code>echo<\\/code> digunakan untuk menampilkan teks.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"2. Variabel & Tipe Data\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n$nama = \\\"Andi\\\";     \\/\\/ string\\n$umur = 20;         \\/\\/ integer\\n$tinggi = 170.5;    \\/\\/ float\\n$isActive = true;   \\/\\/ boolean\\n\\necho \\\"Nama: $nama, Umur: $umur tahun\\\";\\n?>\"},{\"type\":\"paragraf\",\"teks\":\"<p>Di PHP variabel selalu diawali dengan tanda dolar <code>$<\\/code> yang menandai bahwa ini adalah variabel<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"3. Operator Aritmatika\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n$a = 10;\\n$b = 3;\\n\\necho $a + $b; \\/\\/ 13\\necho $a - $b; \\/\\/ 7\\necho $a * $b; \\/\\/ 30\\necho $a \\/ $b; \\/\\/ 3.333...\\necho $a % $b; \\/\\/ 1\\n?>\"},{\"type\":\"subheading\",\"teks\":\"4. Perkondisian (If  - Else)\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n$nilai = 80;\\n\\nif ($nilai >= 75) {\\n    echo \\\"Lulus\\\";\\n} else {\\n    echo \\\"Tidak Lulus\\\";\\n}\\n?>\"},{\"type\":\"subheading\",\"teks\":\"5.Perulangan (Looping)\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n\\/\\/ For\\nfor ($i = 1; $i <= 5; $i++) {\\n    echo \\\"Angka: $i <br>\\\";\\n}\\n\\n\\/\\/ While\\n$j = 1;\\nwhile ($j <= 5) {\\n    echo \\\"Hitung: $j <br>\\\";\\n    $j++;\\n}\\n?>\"},{\"type\":\"subheading\",\"teks\":\"6. Array\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n$buah = [\\\"Apel\\\", \\\"Jeruk\\\", \\\"Mangga\\\"];\\n\\nforeach ($buah as $b) {\\n    echo $b . \\\"<br>\\\";\\n}\\n?>\"},{\"type\":\"subheading\",\"teks\":\"7. Fungsi\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\nfunction salam($nama) {\\n    return \\\"Halo, $nama!\\\";\\n}\\n\\necho salam(\\\"Tunggul\\\");\\n?>\"},{\"type\":\"subheading\",\"teks\":\"8. Form Input (GET & POST)\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<h2>Form POST<\\/h2>\\n<form method=\\\"POST\\\">\\n  Nama: <input type=\\\"text\\\" name=\\\"nama_post\\\">\\n  <button type=\\\"submit\\\">Kirim (POST)<\\/button>\\n<\\/form>\\n\\n<h2>Form GET<\\/h2>\\n<form method=\\\"GET\\\">\\n  Nama: <input type=\\\"text\\\" name=\\\"nama_get\\\">\\n  <button type=\\\"submit\\\">Kirim (GET)<\\/button>\\n<\\/form>\\n\\n<?php\\n\\/\\/ Cek POST\\nif ($_SERVER[\\\"REQUEST_METHOD\\\"] == \\\"POST\\\" && isset($_POST[\'nama_post\'])) {\\n    $nama = htmlspecialchars($_POST[\'nama_post\']);\\n    echo \\\"<p>Halo (POST), $nama!<\\/p>\\\";\\n}\\n\\n\\/\\/ Cek GET\\nif ($_SERVER[\\\"REQUEST_METHOD\\\"] == \\\"GET\\\" && isset($_GET[\'nama_get\'])) {\\n    $nama = htmlspecialchars($_GET[\'nama_get\']);\\n    echo \\\"<p>Halo (GET), $nama!<\\/p>\\\";\\n}\\n?>\"},{\"type\":\"subheading\",\"teks\":\"9. Koneksi Database MySQL\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n$host = \\\"localhost\\\";\\n$user = \\\"root\\\";\\n$pass = \\\"\\\";\\n$db   = \\\"belajar_php\\\";\\n\\n$conn = new mysqli($host, $user, $pass, $db);\\n\\nif ($conn->connect_error) {\\n    die(\\\"Koneksi gagal: \\\" . $conn->connect_error);\\n} else {\\n    echo \\\"Koneksi berhasil!\\\";\\n}\\n?>\"},{\"type\":\"subheading\",\"teks\":\"Variabel Khusus & Method Penting di PHP\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Superglobals (Variabel Khusus di PHP)<\\/strong><\\/p><p>Superglobals adalah variabel array bawaan PHP yang bisa diakses di mana saja (global scope).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"1. $_GET\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ Menangkap data dari URL (query string)\\n<?php\\n\\/\\/ URL: http:\\/\\/localhost\\/test.php?nama=Andi\\necho $_GET[\'nama\']; \\/\\/ Output: Andi\\n?>\"},{\"type\":\"subheading\",\"teks\":\"2. $_POST\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ Menangkap data dari form dengan method POST\\n\\n<?php\\nif ($_SERVER[\\\"REQUEST_METHOD\\\"] == \\\"POST\\\") {\\n    echo $_POST[\'nama\'];\\n}\\n?>\\n<form method=\\\"POST\\\">\\n  <input type=\\\"text\\\" name=\\\"nama\\\">\\n  <button type=\\\"submit\\\">Kirim<\\/button>\\n<\\/form>\"},{\"type\":\"subheading\",\"teks\":\"3. $_REQUEST\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ Gabungan dari $_GET, $_POST, dan $_COOKIE.\\n\\n<?php\\necho $_REQUEST[\'nama\'];\\n?>\"},{\"type\":\"subheading\",\"teks\":\"4. $_SESSION\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ Menyimpan data sementara selama sesi user aktif.\\n\\n<?php\\nsession_start();\\n$_SESSION[\'username\'] = \\\"Andi\\\";\\necho $_SESSION[\'username\'];\\n?>\"},{\"type\":\"subheading\",\"teks\":\"5. $_COOKIE\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ Menyimpan data kecil di browser user.\\n\\n<?php\\nsetcookie(\\\"user\\\", \\\"Andi\\\", time() + 3600);\\necho $_COOKIE[\'user\'];\\n?>\"},{\"type\":\"subheading\",\"teks\":\"6. $_FILES\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ Menangani upload file.\\n\\nif (isset($_FILES[\'file\'])) {\\n    move_uploaded_file($_FILES[\'file\'][\'tmp_name\'], \\\"uploads\\/\\\" . $_FILES[\'file\'][\'name\']);\\n}\\n?>\\n<form method=\\\"POST\\\" enctype=\\\"multipart\\/form-data\\\">\\n  <input type=\\\"file\\\" name=\\\"file\\\">\\n  <button type=\\\"submit\\\">Upload<\\/button>\\n<\\/form>\"},{\"type\":\"subheading\",\"teks\":\"7. $_SERVER\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ Informasi tentang server & request.\\n\\n<?php\\necho $_SERVER[\'PHP_SELF\'];   \\/\\/ Nama file yang sedang dijalankan\\necho $_SERVER[\'SERVER_NAME\']; \\/\\/ Nama server\\necho $_SERVER[\'HTTP_HOST\'];   \\/\\/ Host\\necho $_SERVER[\'REQUEST_METHOD\']; \\/\\/ GET\\/POST\\n?>\"},{\"type\":\"subheading\",\"teks\":\"8. $_ENV\"},{\"type\":\"paragraf\",\"teks\":\"<p>Variabel environment (jarang dipakai langsung, biasanya untuk konfigurasi).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Fungsi \\/ Method Bawaan Penting di PHP\"},{\"type\":\"subheading\",\"teks\":\"String\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"strlen(\\\"Halo\\\");          \\/\\/ Hitung panjang string\\nstrtoupper(\\\"halo\\\");      \\/\\/ HALO\\nstrtolower(\\\"HALO\\\");      \\/\\/ halo\\nsubstr(\\\"BelajarPHP\\\", 0, 7); \\/\\/ Belajar\\nstr_replace(\\\"PHP\\\", \\\"Web\\\", \\\"Belajar PHP\\\"); \\/\\/ Belajar Web\"},{\"type\":\"subheading\",\"teks\":\"Array\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"$buah = [\\\"Apel\\\", \\\"Jeruk\\\", \\\"Mangga\\\"];\\ncount($buah);            \\/\\/ 3\\narray_push($buah, \\\"Durian\\\");\\narray_pop($buah);\\nin_array(\\\"Apel\\\", $buah); \\/\\/ true\"},{\"type\":\"subheading\",\"teks\":\"Date & Time\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"echo date(\\\"Y-m-d H:i:s\\\"); \\/\\/ 2025-10-03 10:00:00\\necho time();              \\/\\/ Timestamp saat ini\"},{\"type\":\"subheading\",\"teks\":\"Validasi & Keamanan\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"htmlspecialchars(\\\"<b>Halo<\\/b>\\\"); \\/\\/ &lt;b&gt;Halo&lt;\\/b&gt;\\npassword_hash(\\\"123456\\\", PASSWORD_DEFAULT);\\npassword_verify(\\\"123456\\\", $hash);\"},{\"type\":\"subheading\",\"teks\":\"File\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"file_put_contents(\\\"data.txt\\\", \\\"Hello PHP\\\");\\necho file_get_contents(\\\"data.txt\\\");\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Ringkasan<\\/strong><\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Superglobals : <code>$_GET<\\/code>, <code>$_POST<\\/code>, <code>$_REQUEST<\\/code>, <code>$_SESSION<\\/code>, <code>$_COOKIE<\\/code>, <code>$_FILES<\\/code>, <code>$_SERVER<\\/code>, <code>$_ENV<\\/code>.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Method penting: manipulasi string, array, tanggal\\/waktu, keamanan (hash, htmlspecialchars), file handling.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"CRUD Shortlink App dengan PHP & TailwindCSS\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Tujuan Pembelajaran<\\/strong><\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Memahami konsep CRUD (Create, Read, Update, Delete).<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Membuat aplikasi Shortlink sederhana dengan PHP Native.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Menggunakan TailwindCSS untuk tampilan modern &amp; responsif.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Menghubungkan PHP dengan database MySQL.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<p>Persiapan<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Install XAMPP\\/Laragon atau server lokal lain.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buat folder project di htdocs\\/shortlink-app\\/. (XAMPP)<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buat folder project di www\\/shortlink-app\\/. (laragon)<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buat database MySQL:<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"CREATE DATABASE shortlink_db;\\nUSE shortlink_db;\\n\\nCREATE TABLE links (\\n    id INT AUTO_INCREMENT PRIMARY KEY,\\n    short_code VARCHAR(50) UNIQUE,\\n    original_url TEXT,\\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\\n);\"},{\"type\":\"subheading\",\"teks\":\"Struktur Project\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"shortlink-app\\/\\n\\u2502\\u2500\\u2500 index.php        (Tampilan daftar link + tambah link)\\n\\u2502\\u2500\\u2500 edit.php         (Edit link)\\n\\u2502\\u2500\\u2500 delete.php       (Hapus link)\\n\\u2502\\u2500\\u2500 redirect.php     (Redirect ke original URL)\\n\\u2502\\u2500\\u2500 db.php           (Koneksi database)\\n\\u2502\\u2500\\u2500 assets\\/\\n    \\u2514\\u2500\\u2500 tailwind.css (CDN atau file Tailwind)\"},{\"type\":\"subheading\",\"teks\":\"db.php (Koneksi Database)\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n$host = \\\"localhost\\\";\\n$user = \\\"root\\\";\\n$pass = \\\"\\\";\\n$db   = \\\"shortlink_db\\\";\\n\\n$conn = new mysqli($host, $user, $pass, $db);\\n\\nif ($conn->connect_error) {\\n    die(\\\"Koneksi gagal: \\\" . $conn->connect_error);\\n}\\n?>\"},{\"type\":\"subheading\",\"teks\":\"index.php (Read + Create)\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php include \'db.php\'; ?>\\n\\n<?php\\n\\/\\/ Tambah Data\\nif (isset($_POST[\'add\'])) {\\n    $original = $_POST[\'original_url\'];\\n    $short = substr(md5(time()), 0, 6); \\/\\/ generate random short code\\n\\n    $sql = \\\"INSERT INTO links (short_code, original_url) VALUES (\'$short\', \'$original\')\\\";\\n    $conn->query($sql);\\n    header(\\\"Location: index.php\\\");\\n}\\n?>\\n\\n<!DOCTYPE html>\\n<html lang=\\\"en\\\">\\n<head>\\n  <meta charset=\\\"UTF-8\\\">\\n  <script src=\\\"https:\\/\\/cdn.tailwindcss.com\\\"><\\/script>\\n  <title>Shortlink App<\\/title>\\n<\\/head>\\n<body class=\\\"bg-gray-100 p-10\\\">\\n  <div class=\\\"max-w-2xl mx-auto bg-white p-6 rounded-xl shadow-md\\\">\\n    <h1 class=\\\"text-2xl font-bold mb-4\\\">\\ud83d\\udccc Shortlink Generator<\\/h1>\\n\\n    <!-- Form Tambah -->\\n    <form method=\\\"POST\\\" class=\\\"flex gap-2 mb-6\\\">\\n      <input type=\\\"url\\\" name=\\\"original_url\\\" placeholder=\\\"Masukkan URL asli\\\"\\n        class=\\\"w-full p-2 border rounded-lg\\\" required>\\n      <button type=\\\"submit\\\" name=\\\"add\\\" class=\\\"px-4 py-2 bg-blue-500 text-white rounded-lg\\\">Tambah<\\/button>\\n    <\\/form>\\n\\n    <!-- Daftar Link -->\\n    <table class=\\\"w-full border text-left\\\">\\n      <thead class=\\\"bg-gray-200\\\">\\n        <tr>\\n          <th class=\\\"p-2\\\">Short<\\/th>\\n          <th class=\\\"p-2\\\">Original<\\/th>\\n          <th class=\\\"p-2\\\">Aksi<\\/th>\\n        <\\/tr>\\n      <\\/thead>\\n      <tbody>\\n        <?php\\n        $result = $conn->query(\\\"SELECT * FROM links ORDER BY id DESC\\\");\\n        while ($row = $result->fetch_assoc()) {\\n          echo \\\"<tr class=\'border-t\'>\\n                  <td class=\'p-2\'>\\n                    <a class=\'text-blue-600 underline\' target=\'_blank\' href=\'redirect.php?c={$row[\'short_code\']}\'>\\n                      {$row[\'short_code\']}\\n                    <\\/a>\\n                  <\\/td>\\n                  <td class=\'p-2\'>{$row[\'original_url\']}<\\/td>\\n                  <td class=\'p-2\'>\\n                    <a href=\'edit.php?id={$row[\'id\']}\' class=\'px-2 py-1 bg-yellow-400 rounded\'>Edit<\\/a>\\n                    <a href=\'delete.php?id={$row[\'id\']}\' class=\'px-2 py-1 bg-red-500 text-white rounded\'>Delete<\\/a>\\n                  <\\/td>\\n                <\\/tr>\\\";\\n        }\\n        ?>\\n      <\\/tbody>\\n    <\\/table>\\n  <\\/div>\\n<\\/body>\\n<\\/html>\"},{\"type\":\"subheading\",\"teks\":\"edit.php (Update)\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php include \'db.php\'; ?>\\n\\n<?php\\n$id = $_GET[\'id\'];\\n$result = $conn->query(\\\"SELECT * FROM links WHERE id=$id\\\");\\n$data = $result->fetch_assoc();\\n\\nif (isset($_POST[\'update\'])) {\\n    $original = $_POST[\'original_url\'];\\n    $sql = \\\"UPDATE links SET original_url=\'$original\' WHERE id=$id\\\";\\n    $conn->query($sql);\\n    header(\\\"Location: index.php\\\");\\n}\\n?>\\n\\n<!DOCTYPE html>\\n<html lang=\\\"en\\\">\\n<head>\\n  <meta charset=\\\"UTF-8\\\">\\n  <script src=\\\"https:\\/\\/cdn.tailwindcss.com\\\"><\\/script>\\n  <title>Edit Link<\\/title>\\n<\\/head>\\n<body class=\\\"bg-gray-100 p-10\\\">\\n  <div class=\\\"max-w-lg mx-auto bg-white p-6 rounded-xl shadow-md\\\">\\n    <h1 class=\\\"text-xl font-bold mb-4\\\">\\u270f\\ufe0f Edit Link<\\/h1>\\n    <form method=\\\"POST\\\" class=\\\"flex gap-2\\\">\\n      <input type=\\\"url\\\" name=\\\"original_url\\\" value=\\\"<?= $data[\'original_url\']; ?>\\\"\\n        class=\\\"w-full p-2 border rounded-lg\\\" required>\\n      <button type=\\\"submit\\\" name=\\\"update\\\" class=\\\"px-4 py-2 bg-green-500 text-white rounded-lg\\\">Update<\\/button>\\n    <\\/form>\\n  <\\/div>\\n<\\/body>\\n<\\/html>\"},{\"type\":\"subheading\",\"teks\":\"delete.php (Delete)\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\ninclude \'db.php\';\\n$id = $_GET[\'id\'];\\n$conn->query(\\\"DELETE FROM links WHERE id=$id\\\");\\nheader(\\\"Location: index.php\\\");\"},{\"type\":\"subheading\",\"teks\":\"redirect.php (Redirect ke URL asli)\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\ninclude \'db.php\';\\n\\n$code = $_GET[\'c\'];\\n$result = $conn->query(\\\"SELECT * FROM links WHERE short_code=\'$code\'\\\");\\n\\nif ($row = $result->fetch_assoc()) {\\n    header(\\\"Location: \\\" . $row[\'original_url\']);\\n    exit;\\n} else {\\n    echo \\\"Shortlink tidak ditemukan.\\\";\\n}\\n?>\"},{\"type\":\"subbab\",\"judul\":\"LARAVEL 13 :3\",\"judul_idn\":null},{\"type\":\"paragraf\",\"teks\":\"<p>Hari ini kita maw ngapain aja sih ?<\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Paham isi folder Laravel (mana yang perlu disentuh, mana yang jangan diutak-atik).<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Paham cara kerja <strong>MVC<\\/strong> dan alur perjalanan URL sampai jadi halaman web.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Berhasil membuat aplikasi <strong>Katalog Buku<\\/strong> sederhana (Tampil Data + Tambah Data).<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Part 1: Peta Folder Laravel 13\"},{\"type\":\"paragraf\",\"teks\":\"<p>Untuk 80% pekerjaanmu semester ini, ntar bakal bolak-balik di 4 folder yang diberi tanda bintang (\\u2b50) ini :<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"laravel-project\\/\\n\\u251c\\u2500\\u2500 \\u2b50 app\\/\\n\\u2502   \\u251c\\u2500\\u2500 Http\\/Controllers\\/   <-- Otak pengatur logika (Controller)\\n\\u2502   \\u2514\\u2500\\u2500 Models\\/             <-- Jembatan ke tabel database (Model)\\n\\u251c\\u2500\\u2500 bootstrap\\/\\n\\u2502   \\u2514\\u2500\\u2500 app.php             <-- Pusat pengaturan rute & keamanan (Middleware)\\n\\u251c\\u2500\\u2500 config\\/                 <-- Pengaturan aplikasi\\n\\u251c\\u2500\\u2500 \\u2b50 database\\/\\n\\u2502   \\u251c\\u2500\\u2500 migrations\\/         <-- Cetakan tabel database\\n\\u2502   \\u2514\\u2500\\u2500 database.sqlite     <-- File database bawaan (praktis, tanpa XAMPP!)\\n\\u251c\\u2500\\u2500 public\\/                 <-- Pintu masuk utama (index.php) & file gambar\\/CSS publik\\n\\u251c\\u2500\\u2500 \\u2b50 resources\\/\\n\\u2502   \\u2514\\u2500\\u2500 views\\/              <-- Tempat menaruh file HTML\\/Blade (View)\\n\\u251c\\u2500\\u2500 \\u2b50 routes\\/\\n\\u2502   \\u2514\\u2500\\u2500 web.php             <-- Daftar alamat URL web kamu\\n\\u2514\\u2500\\u2500 .env                    <-- Kunci rahasia & pengaturan database\\n\"},{\"type\":\"subheading\",\"teks\":\"Part 2 : Konsep MVC & Alur Request\"},{\"type\":\"paragraf\",\"teks\":\"<p>Laravel bekerja dengan pola MVC (Model - View - Controller). Bayangkan kamu sedang makan di restoran:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/1o872djuge.ufs.sh\\/f\\/hL4tjTnv9CWbpjJIT0M4fDAHm7k5Yj6SUr9wuChs2gQ3RbJa\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792048575\\/portfolio\\/courses\\/phpn7skf6mn5qpc0xhpANR_nqimqg.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Route (<\\/strong><code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\"><strong>routes\\/web.php<\\/strong><\\/code><strong>) = Buku Menu.<\\/strong> Daftar URL yang bisa dipesan pengunjung (misal: <code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\">\\/books<\\/code>).<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Controller (<\\/strong><code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\"><strong>app\\/Http\\/Controllers<\\/strong><\\/code><strong>) = Pelayan.<\\/strong> Menerima pesanan dari pengunjung, lalu menyuruh koki menyiapkan bahan.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Model (<\\/strong><code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\"><strong>app\\/Models<\\/strong><\\/code><strong>) = Koki &amp; Gudang Bahan.<\\/strong> Mengambil atau menyimpan data ke database (<code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\">books<\\/code>).<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>View (<\\/strong><code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\"><strong>resources\\/views<\\/strong><\\/code><strong>) = Piring Saji.<\\/strong> Menampilkan data yang sudah matang menjadi halaman HTML yang rapi ke layar pengunjung.<\\/li><\\/ol><p>Urutan Perjalanannya: Pengunjung buka URL \\u2794 Cek di <code>routes\\/web.php <\\/code>\\u2794 Panggil <code>Controller<\\/code> \\u2794 Ambil data lewat <code>Model<\\/code> \\u2794 Tampilkan ke <code>View<\\/code>.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Part 3: Praktikum Bikin Aplikasi Katalog Buku\"},{\"type\":\"paragraf\",\"teks\":\"<p>Sekarang buka terminal dan VS Code kalian. Kita akan membuat daftar buku dan form tambah buku<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"Langkah 1: Buat Proyek & Nyalakan Server\"},{\"type\":\"paragraf\",\"teks\":\"<p>Jalankan perintah ini di terminal :<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"# Buat proyek baru\\ncomposer create-project laravel\\/laravel:^13.0 katalog-buku\\ncd katalog-buku\"},{\"type\":\"subheading3\",\"teks\":\"Langkah 2: Buat Model & Tabel Database\"},{\"type\":\"paragraf\",\"teks\":\"<p>Kita butuh tabel <code>books<\\/code> di database dan model <code>Book<\\/code> untuk mengelolanya.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"php artisan make:model Book -m\"},{\"type\":\"paragraf\",\"teks\":\"<p><em>Flag <\\/em><code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\"><em>-m<\\/em><\\/code><em> artinya: \\\"Tolong sekalian buatin file Migration\\/cetakan tabelnya\\\").<\\/em><\\/p><p><br><\\/p><p>Buka file migration yang baru muncul di <code>database\\/migrations\\/xxxx_create_books_table.php.<\\/code><\\/p><p>Ubah bagian <code>up()<\\/code> menjadi seperti ini:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"public function up(): void\\n{\\n    Schema::create(\'books\', function (Blueprint $table) {\\n        $table->id();\\n        $table->string(\'title\');   \\/\\/ Judul buku\\n        $table->string(\'author\');  \\/\\/ Nama penulis\\n        $table->timestamps();      \\/\\/ Otomatis bikin kolom created_at & updated_at\\n    });\\n}\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p>Sekarang cetak tabel tersebut ke database dengan perintah :<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"php artisan migrate\"},{\"type\":\"paragraf\",\"teks\":\"<p>Terakhir, <code>buka app\\/Models\\/Book.php<\\/code>. Beri izin agar kolom <code>title<\\/code> dan <code>author<\\/code> boleh diisi lewat form:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n\\nnamespace App\\\\Models;\\n\\nuse Illuminate\\\\Database\\\\Eloquent\\\\Model;\\n\\nclass Book extends Model\\n{\\n    \\/\\/ Daftar kolom yang diizinkan untuk diisi pengguna\\n    protected $fillable = [\'title\', \'author\'];\\n}\"},{\"type\":\"subheading3\",\"teks\":\"Langkah 3: Buat Controller\"},{\"type\":\"paragraf\",\"teks\":\"<p>Sekarang kita buat \\\"Pelayan\\\"-nya. Jalankan di terminal:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"php artisan make:controller BookController\"},{\"type\":\"paragraf\",\"teks\":\"<p>Buka <code style=\\\"background-color: rgb(22, 27, 34); color: rgb(201, 209, 217);\\\">app\\/Http\\/Controllers\\/BookController.php<\\/code>, lalu isi dengan 2 fungsi: <code style=\\\"background-color: rgb(22, 27, 34); color: rgb(201, 209, 217);\\\"><strong>index<\\/strong><\\/code> (untuk menampilkan daftar buku) dan <code style=\\\"background-color: rgb(22, 27, 34); color: rgb(201, 209, 217);\\\"><strong>store<\\/strong><\\/code>(untuk menyimpan buku baru).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n\\nnamespace App\\\\Http\\\\Controllers;\\n\\nuse App\\\\Models\\\\Book;\\nuse Illuminate\\\\Http\\\\Request;\\n\\nclass BookController extends Controller\\n{\\n    \\/\\/ 1. Menampilkan halaman daftar buku\\n    public function index()\\n    {\\n        \\/\\/ Ambil data buku terbaru dari database\\n        $books = Book::latest()->get();\\n\\n        \\/\\/ Kirim data $books ke tampilan resources\\/views\\/books\\/index.blade.php\\n        return view(\'books.index\', [\'books\' => $books]);\\n    }\\n\\n    \\/\\/ 2. Menyimpan buku baru dari form\\n    public function store(Request $request)\\n    {\\n        \\/\\/ Cek dulu: judul & penulis wajib diisi!\\n        $validated = $request->validate([\\n            \'title\'  => \'required|string|max:255\',\\n            \'author\' => \'required|string|max:255\',\\n        ]);\\n\\n        \\/\\/ Simpan ke database\\n        Book::create($validated);\\n\\n        \\/\\/ Kembalikan ke halaman daftar buku dengan pesan sukses\\n        return to_route(\'books.index\')->with(\'success\', \'Buku berhasil ditambahkan!\');\\n    }\\n}\"},{\"type\":\"subheading3\",\"teks\":\"Langkah 4: Buat Tampilan \\/ View Blade\"},{\"type\":\"paragraf\",\"teks\":\"<p>Buat folder baru bernama <code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\">books<\\/code> di dalam <code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\">resources\\/views\\/<\\/code>, lalu buat file <code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\">index.blade.php<\\/code> (atau jalankan <code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\">php artisan make:view books.index<\\/code>). Isi <code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\">resources\\/views\\/books\\/index.blade.php<\\/code><span style=\\\"color: rgb(201, 209, 217);\\\"> <\\/span>dengan kode berikut :<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<!DOCTYPE html>\\n<html lang=\\\"id\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <title>Katalog Buku<\\/title>\\n    <style>\\n        body { font-family: sans-serif; max-width: 600px; margin: 40px auto; padding: 0 20px; }\\n        .alert { background: #d1fae5; color: #065f46; padding: 10px; border-radius: 6px; margin-bottom: 16px; }\\n        .error { color: #dc2626; font-size: 14px; }\\n        form { background: #f8fafc; padding: 16px; border-radius: 8px; border: 1px solid #e2e8f0; }\\n        input { width: 100%; padding: 8px; margin: 6px 0 12px; box-sizing: border-box; }\\n        button { background: #2563eb; color: white; border: none; padding: 10px 16px; border-radius: 4px; cursor: pointer; }\\n    <\\/style>\\n<\\/head>\\n<body>\\n\\n    <h1Katalog Buku<\\/h1>\\n\\n    {{-- Munculkan pesan sukses jika ada --}}\\n    @session(\'success\')\\n        <div class=\\\"alert\\\">{{ $value }}<\\/div>\\n    @endsession\\n\\n    {{-- Form Tambah Buku --}}\\n    <form method=\\\"POST\\\" action=\\\"{{ route(\'books.store\') }}\\\">\\n        @csrf {{-- WAJIB ADA: Token keamanan Laravel agar form tidak dibajak --}}\\n\\n        <label>Judul Buku:<\\/label>\\n        <input type=\\\"text\\\" name=\\\"title\\\" value=\\\"{{ old(\'title\') }}\\\" placeholder=\\\"Contoh: Filosofi Teras\\\">\\n        @error(\'title\') <div class=\\\"error\\\">{{ $message }}<\\/div> @enderror\\n\\n        <label>Penulis:<\\/label>\\n        <input type=\\\"text\\\" name=\\\"author\\\" value=\\\"{{ old(\'author\') }}\\\" placeholder=\\\"Contoh: Henry Manampiring\\\">\\n        @error(\'author\') <div class=\\\"error\\\">{{ $message }}<\\/div> @enderror\\n\\n        <button type=\\\"submit\\\">+ Tambah Buku<\\/button>\\n    <\\/form>\\n\\n    <hr style=\\\"margin: 24px 0;\\\">\\n\\n    {{-- Daftar Buku --}}\\n    <h3>Koleksi Saat Ini:<\\/h3>\\n    <ul>\\n        @forelse ($books as $book)\\n            <li><strong>{{ $book->title }}<\\/strong> oleh {{ $book->author }}<\\/li>\\n        @empty\\n            <li>Belum ada buku. Yuk tambahkan buku pertamamu!<\\/li>\\n        @endforelse\\n    <\\/ul>\\n\\n<\\/body>\\n<\\/html>\"},{\"type\":\"paragraf\",\"teks\":\"<p>Kenapa pakai <code>@forelse <\\/code>bukan @foreach? Dengan @forelse, kalau databasenya masih kosong, Laravel otomatis menampilkan bagian @empty (\\\"Belum ada buku\\\"). Kita tidak perlu repot bikin if-else manual!<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"Langkah 5: Daftarkan Alamat URL di Route\"},{\"type\":\"paragraf\",\"teks\":\"<p>Buka <code>routes\\/web.php<\\/code>, lalu daftarkan 2 rute kita: satu untuk melihat halaman (<code>GET<\\/code>), satu untuk mengirim form (<code>POST<\\/code>).<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"<?php\\n\\nuse App\\\\Http\\\\Controllers\\\\BookController;\\nuse Illuminate\\\\Support\\\\Facades\\\\Route;\\n\\n\\/\\/ Kalau buka halaman utama, langsung arahkan ke \\/books\\nRoute::redirect(\'\\/\', \'\\/books\');\\n\\nRoute::get(\'\\/books\', [BookController::class, \'index\'])->name(\'books.index\');\\nRoute::post(\'\\/books\', [BookController::class, \'store\'])->name(\'books.store\');\"},{\"type\":\"subheading3\",\"teks\":\"Langkah 6: Jalankan & Uji Coba! (5 Menit)\"},{\"type\":\"paragraf\",\"teks\":\"<p>Nyalakan server lokal di terminal :<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"php artisan serve\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buka browser dan kunjungi <code style=\\\"color: rgb(201, 209, 217); background-color: rgb(22, 27, 34);\\\">http:\\/\\/localhost:8000\\/books<\\/code>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Coba klik tombol <strong>+ Tambah Buku<\\/strong><\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sekarang isi Judul dan Penulis, lalu klik tambah.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<p>Percobaan mandiri :p<\\/p><p>Sudah berhasil? Sebelum keluar kelas, coba selesaikan percobaan kecil ini:<\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Tantangan Level 1: Tambahkan kolom year (tahun terbit, tipe integer) di file migration, lalu jalankan php artisan migrate:fresh (perintah ini akan mereset tabel dan membuat ulang dengan kolom baru).<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Tantangan Level 2: Perbarui $fillable di Model Book, tambahkan input Tahun Terbit di form Blade, dan tambahkan validasi \'year\' =&gt; \'required|numeric\' di BookController. <\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Tantangan Level 3: Tampilkan tahun terbit di samping nama penulis, contoh: Filosofi Teras oleh Henry Manampiring (2018).<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Cheat Sheet Praktikum Hari Ini<\\/strong><\\/p><p>Perintah Terminal Kegunaan<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Header 1\",\"Header 3\"],\"rows\":[[\"`php artisan serve`\",\"Menyalakan server web di `localhost:8000`\"],[\"`php artisan make:model NamaModel -m`\",\"Membuat Model sekaligus file Migration\"],[\"`php artisan make:controller NamaController`\",\"Membuat file Controller baru\"],[\"`php artisan make:view folder.nama`\",\"Membuat file tampilan Blade baru\"],[\"`php artisan migrate`\",\"Mengeksekusi pembuatan tabel ke database\"],[\"`php artisan migrate:fresh`\",\"Menghapus semua tabel dan membuat ulang dari awal\"]],\"caption\":\"\"}]');
INSERT INTO `courses` (`id`, `slug`, `nama`, `nama_idn`, `desk`, `desk_idn`, `gambar`, `sort_order`, `created_at`, `updated_at`, `konten`) VALUES
(2, 'pemrograman-berbasis-objek', 'Pemrograman Berbasis Objek', NULL, 'Belajar pemrograman dengan C#', NULL, 'https://res.cloudinary.com/droanqrew/image/upload/v1787128424/portfolio/courses/php1isvm0rkpukva8CMnFC_nco0o0.webp', 3, '2026-08-19 01:33:45', '2026-10-15 08:52:36', '[{\"type\":\"subbab\",\"judul\":\"Pengenalan Dasar C#\"},{\"type\":\"subheading\",\"teks\":\"Struktur Program C#\"},{\"type\":\"paragraf\",\"teks\":\"Setiap aplikasi C# berbasis console memiliki struktur standar yang menjamin kode dapat dieksekusi oleh runtime .NET. C# bersifat case-sensitive, sehingga penggunaan huruf besar dan kecil sangat berpengaruh.\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using System;\\n\\nnamespace Praktikum1\\n{\\n    class Program\\n    {\\n        static void Main()\\n        {\\n            Console.WriteLine(\\\"Hello World!\\\");\\n        }\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"Penjelasan Komponen:\\n- using System: Instruksi untuk menggunakan namespace System yang berisi kelas-kelas dasar seperti Console.\\n- namespace: Digunakan untuk mengorganisir kode secara logis dan mencegah konflik penamaan kelas dalam proyek yang besar.\\n- class Program: Blueprint utama tempat kode aplikasi berada. Di C#, setiap baris kode harus berada di dalam sebuah kelas.\\n- static void Main: Entry point atau titik awal eksekusi program. Program akan mencari metode ini pertama kali saat dijalankan. \\n\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Variabel dan Tipe Data\"},{\"type\":\"paragraf\",\"teks\":\"Variabel adalah tempat penyimpanan value di memori dengan tipe data tertentu. Sebagai bahasa strongly typed, C# mewajibkan setiap variabel dideklarasikan tipenya secara eksplisit.\\n\\n1. Tipe Data Primitif (Value Types)\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1787159134\\/portfolio\\/courses\\/phpbn2rsvk3cekb4o2bfsb_vytk7y.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"2. Tipe Data Koleksi (Reference Types)\\nDigunakan untuk menyimpan sekumpulan data di bawah satu nama variabel.\\n- Array: Koleksi data bertipe sama dengan ukuran tetap (fixed-size) yang ditentukan saat inisialisasi.Apa itu T?: Simbol T dalam kurung sudut < > disebut sebagai Type Parameter. Ini adalah fitur Generics dalam C#. T bertindak sebagai placeholder (penampung sementara) untuk tipe data yang sebenarnya.\\n- Type Safety: Saat Anda mendeklarasikan List<int>, maka T digantikan oleh int. Hal ini menjamin keamanan tipe, di mana program hanya akan mengizinkan data bertipe integer untuk masuk ke list tersebut, sehingga menghindari kesalahan data di kemudian hari.\\n- Namespace: Memerlukan instruksi using System.Collections.Generic;.\\n\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"List<string> keranjang = new List<string>(); \\/\\/ T diisi dengan string\\nkeranjang.Add(\\\"Laptop\\\"); \\/\\/ Menambah data\\nkeranjang.Add(\\\"Mouse\\\");\\nConsole.WriteLine(keranjang.Count); \\/\\/ Mengambil jumlah item saat ini\"},{\"type\":\"subheading\",\"teks\":\"Operator Utama\"},{\"type\":\"paragraf\",\"teks\":\"- Aritmatika: +, -, *, \\/, % (sisa bagi).\\n- Perbandingan: == (sama dengan), != (tidak sama dengan), >, <, >=, <=.\\n- Logika: && (AND), || (OR), ! (NOT\\/Negasi).\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Percabangan (Branching)\"},{\"type\":\"paragraf\",\"teks\":\"- If-Else Statement\\n\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"\\/\\/Digunakan untuk evaluasi kondisi yang bersifat dinamis atau rentang nilai.\\n\\nif (ipk >= 3.5) \\n{\\n    Console.WriteLine(\\\"Predikat: Cum Laude\\\");\\n}\\nelse if (ipk >= 3.0)\\n{\\n    Console.WriteLine(\\\"Predikat: Sangat Memuaskan\\\");\\n}\\nelse \\n{\\n    Console.WriteLine(\\\"Predikat: Memuaskan\\\");\\n}\"},{\"type\":\"paragraf\",\"teks\":\"- Switch Statement\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"\\/\\/Digunakan untuk membandingkan satu variabel dengan beberapa nilai konstanta \\n\\/\\/(lebih efisien secara performa untuk banyak pilihan tetap).\\n\\nint hari = 1;\\nswitch (hari)\\n{\\n    case 1:\\n        Console.WriteLine(\\\"Senin\\\");\\n        break;\\n    case 2:\\n        Console.WriteLine(\\\"Selasa\\\");\\n        break;\\n    default:\\n        Console.WriteLine(\\\"Hari tidak valid\\\");\\n        break;\\n}\"},{\"type\":\"subheading\",\"teks\":\"Perulangan (Looping)\"},{\"type\":\"paragraf\",\"teks\":\"- For Loop\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"\\/\\/Digunakan saat jumlah iterasi sudah diketahui secara pasti.\\n\\nfor (int i = 1; i <= 5; i++)\\n{\\n    Console.WriteLine($\\\"Iterasi ke-{i}\\\");\\n}\"},{\"type\":\"paragraf\",\"teks\":\"- While Loop & Do-While Loop\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/while: Mengecek kondisi di awal sebelum menjalankan kode. \\n\\/\\/Jika kondisi sejak awal salah, kode di dalamnya tidak akan pernah dijalankan.\\n\\n\\/\\/do-while: Menjalankan kode minimal satu kali, baru kemudian mengecek kondisi di akhir.\\n\\nint j = 0;\\nwhile (j < 3)\\n{\\n    Console.WriteLine(\\\"Iterasi While ke-\\\" + j);\\n    j++;\\n}\\n\\n\\/\\/ Contoh Do-While\\nint k = 0;\\ndo\\n{\\n    Console.WriteLine(\\\"Iterasi Do-While ke-\\\" + k);\\n    k++;\\n} while (k < 3);\"},{\"type\":\"paragraf\",\"teks\":\"- Foreach Loop\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/Digunakan khusus untuk melakukan iterasi pada setiap elemen dalam array atau \\n\\/\\/koleksi data seperti List tanpa perlu menggunakan indeks manual.\\n\\nstring[] hobi = { \\\"Coding\\\", \\\"Gaming\\\", \\\"Reading\\\" };\\n\\nforeach (string item in hobi)\\n{\\n    Console.WriteLine(\\\"Hobi: \\\" + item);\\n}\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"List<string> products = [\\\"Laptop\\\", \\\"Keyboard\\\", \\\"Kamera\\\"]\\n\\nforeach (string product in products)\\n{\\n    Console.WriteLine(\\\"Produk: \\\" + product);\\n}\"},{\"type\":\"subbab\",\"judul\":\"Class, Object, Atribute, Method, Namespace\",\"judul_idn\":null},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<p>Bab ini akan memperkenalkan konsep fundamental OOP di C#. Fokus utama kita adalah memahami bagaimana merepresentasikan entitas dunia nyata ke dalam struktur kode yang terorganisir dan modular.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"1. Konsep Class dan Object\"},{\"type\":\"paragraf\",\"teks\":\"<p>Dalam OOP, kita memandang program sebagai kumpulan objek yang saling berinteraksi.<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Class<\\/strong>: Adalah cetak biru (<em>blueprint<\\/em>) atau template yang mendefinisikan karakteristik dan perilaku dari suatu entitas. Class tidak memakan ruang memori sebelum diinstansiasi.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Object<\\/strong>: Adalah perwujudan nyata (<em>instance<\\/em>) dari sebuah Class. Objek memiliki identitas unik dan menyimpan data nyata di dalam memori.<\\/li><\\/ol><p><strong>Analogi:<\\/strong> Class adalah gambar arsitektur rumah, sedangkan Object adalah rumah fisik yang dibangun berdasarkan gambar tersebut.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/www.tutorialrepublic.com\\/lib\\/images\\/class-object-relationship-illustration.png\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<p>Untuk membuat sebuah objek hampir serupa dengan membuat variabel yaitu dengan syntax<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"NamaClass namaObjek = new NamaClass();\"},{\"type\":\"pembatas\",\"style\":\"spasi\"},{\"type\":\"subheading\",\"teks\":\"2. Atribut (Fields) dan Method\"},{\"type\":\"paragraf\",\"teks\":\"<p>Sebuah Class terdiri dari dua elemen utama:<\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Atribut (Fields)<\\/strong>: Variabel yang dideklarasikan di dalam class untuk menyimpan data, keadaan (<em>state<\\/em>) dari objek, atau informasi tentang objek. Atribut ini menentukan keadaan atau karakteristik dari objek tersebut. Dalam OOP, atribut sering disebut juga sebagai properti atau data member.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Method (Behaviors)<\\/strong>:<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Fungsi yang dideklarasikan di dalam class untuk mendefinisikan tindakan atau perilaku yang dapat dilakukan oleh objek.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Method merupakan sekumpulan perintah yang melekat pada objek<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sebuah method perlu didefinisikan tipe data apa yang akan dikembalikan \\/ di return nantinya. Apabila tidak ada yang dikembalikan dapat menggunakan keyword <code>void<\\/code><\\/li><\\/ol><h3>Contoh Implementasi<\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using System;\\n\\nnamespace Praktikum2\\n{\\n    \\/\\/ Definisi Class\\n    class Rumah\\n    {\\n        \\/\\/ Atribut (Fields)\\n        public string warna;\\n        public int jumlahKamar;\\n\\n        \\/\\/ Method\\n        public void TampilkanInformasi()\\n        {\\n            Console.WriteLine($\\\"Rumah ini berwarna {warna} dan memiliki {jumlahKamar} kamar.\\\");\\n        }\\n    }\\n\\n    class Program\\n    {\\n        static void Main(string[] args)\\n        {\\n            \\/\\/ Instansiasi Objek (Membuat object dari class)\\n            Rumah rumahSaya = new Rumah();\\n            \\n            \\/\\/ Memberikan nilai ke atribut\\n            rumahSaya.warna = \\\"Putih\\\";\\n            rumahSaya.jumlahKamar = 3;\\n\\n            \\/\\/ Memanggil method\\n            rumahSaya.TampilkanInformasi();\\n        }\\n    }\\n}\"},{\"type\":\"pembatas\",\"style\":\"spasi\"},{\"type\":\"subheading\",\"teks\":\"3. Constructor (Konstruktor)\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Constructor adalah method spesial yang akan dijalankan pertama kali ketika objek dibuat.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sebuah constructor tidak akan mereturn apapun sehingga dalam membuatnya tidak perlu mendefiniskan tipe data return.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Nama method constructor sama dengan nama class nya.<\\/li><\\/ol><p>Contoh:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"class Rumah {\\n    \\/\\/ Properties \\/ Attributes\\n    string warna = \\\"Putih\\\";  \\n    int jumlahKamar;\\n    int jumlahLantai;\\n\\n    \\/\\/ Konstruktor \\n    public Rumah(int jumlahKamarInput, int jumlahLantaiInput)\\n    {\\n        jumlahKamar = jumlahKamarInput;\\n        jumlahLantai = jumlahLantaiInput;\\n    }\\n}\"},{\"type\":\"pembatas\",\"style\":\"spasi\"},{\"type\":\"subheading\",\"teks\":\"4. Namespace\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Namespace<\\/strong> adalah cara C# untuk mengelompokkan kelas-kelas yang berkaitan dalam satu lingkup penamaan.<\\/p><p><strong>Analogi Sederhana: Folder Komputer<\\/strong><\\/p><p>Bayangkan Anda memiliki file bernama <code>tugas.docx<\\/code>. Anda tidak bisa menyimpan dua file dengan nama yang sama persis di dalam satu folder. Namun, Anda bisa memiliki <code>tugas.docx<\\/code> di folder <strong>Kuliah<\\/strong> dan <code>tugas.docx<\\/code> lainnya di folder <strong>Pribadi<\\/strong>.<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong style=\\\"color: inherit; background-color: rgb(255, 187, 51);\\\">Folder<\\/strong><span style=\\\"color: rgb(0, 0, 0);\\\"> <\\/span>adalah Namespace.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong style=\\\"color: inherit; background-color: rgb(255, 187, 51);\\\">File<\\/strong><span style=\\\"color: rgb(0, 0, 0);\\\"> <\\/span>adalah Class.<\\/li><\\/ol><p><strong>Tujuan Utama:<\\/strong> Mencegah konflik penamaan (<em>naming collision<\\/em>). Dengan namespace, dua tim developer bisa membuat kelas dengan nama yang sama tanpa menyebabkan error, asalkan diletakkan di namespace yang berbeda.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"namespace Folder.Kuliah {\\n    public class Tugas{ \\/* Tugas Mata Kuliah*\\/ }\\n}\\n\\nnamespace Folder.Pribadi {\\n    public class Tugas{ \\/* Tugas Pribadi*\\/ }\\n}\"},{\"type\":\"pembatas\",\"style\":\"spasi\"},{\"type\":\"subheading\",\"teks\":\"5. Keyword \'this\'\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keyword <code>this<\\/code> merujuk pada objek. Selain itu juga dapat untuk mengakses method pada objek dengan <code>this.NamaMethod()<\\/code>. Tujuannya apa bang Messi keyword <code>this<\\/code> ? Simple untuk mengurangi ambiguitas antara variable lokal (parameter) dengan variable dalam class (field)<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"class Rumah {\\n    \\/\\/ Properties \\/ Attributes\\n    string warna = \\\"Putih\\\";  \\n    int jumlahKamar;\\n    int jumlahLantai;\\n\\n    \\/\\/ Konstruktor dengan keyword this\\n    public Rumah(int jumlahKamar, int jumlahLantai)\\n    {\\n        this.jumlahKamar = jumlahKamar;\\n        this.jumlahLantai = jumlahLantai;\\n    }\\n}\"},{\"type\":\"pembatas\",\"style\":\"spasi\"},{\"type\":\"subheading\",\"teks\":\"6. Keyword \'static\'\"},{\"type\":\"paragraf\",\"teks\":\"<p>Atribut dan method dapat bersifat static, artinya atribut dan method melekat pada class bukan pada objek. Sehingga apabila hendak mengakses tidak perlu membuat objek terlebih dahulu. Caranya cukup menambahkan keyword static sebelum tipe data atribut \\/ method.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"\\/\\/ STATIC PADA ATRIBUT\\n\\nclass Rumah {\\n    \\/\\/ Properti static (berlaku untuk semua objek Rumah)\\n    public static string warna = \\\"Putih\\\";  \\n\\n    \\/\\/ Properti non-static (berbeda untuk setiap objek)\\n    int jumlahKamar;\\n    int jumlahLantai;\\n\\n    \\/\\/ Konstruktor\\n    public Rumah(int jumlahKamar, int jumlahLantai)\\n    {\\n        this.jumlahKamar = jumlahKamar;\\n        this.jumlahLantai = jumlahLantai;\\n    }\\n}\\n\\n\\nclass Program\\n{\\n    static void Main()\\n    {\\n        \\/\\/ Mengakses atribut static tanpa membuat objek\\n        Console.WriteLine(\\\"Warna awal: \\\" + Rumah.warna); \\/\\/ Output: Warna awal: Putih\\n\\n        \\/\\/ Mengubah warna, semua rumah ikut berubah\\n        Rumah.warna = \\\"Biru\\\";\\n        Console.WriteLine(\\\"Warna setelah diubah: \\\" + Rumah.warna); \\/\\/ Output: Warna setelah diubah: Biru\\n\\n        \\/\\/ Membuat objek Rumah\\n        Rumah rumah1 = new Rumah(3, 2);\\n        Rumah rumah2 = new Rumah(4, 1);\\n\\n        \\/\\/ Warna tetap sama untuk semua rumah karena static\\n        Console.WriteLine(\\\"Warna rumah1: \\\" + Rumah.warna); \\/\\/ Output: Warna rumah1: Biru\\n        Console.WriteLine(\\\"Warna rumah2: \\\" + Rumah.warna); \\/\\/ Output: Warna rumah2: Biru\\n    }\\n}\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"\\/\\/ STATIC PADA METHOD\\nclass Kalkulator\\n{\\n    \\/\\/ Method static (tidak perlu objek)\\n    public static int Tambah(int a, int b)\\n    {\\n        return a + b;\\n    }\\n}\\n\\nclass Program\\n{\\n    static void Main()\\n    {\\n        \\/\\/ Memanggil method static tanpa membuat objek\\n        int hasil = Kalkulator.Tambah(5, 3);\\n        Console.WriteLine(\\\"Hasil penjumlahan: \\\" + hasil); \\/\\/ Output: Hasil penjumlahan: 8\\n    }\\n}\"},{\"type\":\"subbab\",\"judul\":\"Inheritance dan Class Diagram\",\"judul_idn\":null},{\"type\":\"subheading\",\"teks\":\"1. Konsep Inheritance (Pewarisan)\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Inheritance (pewarisan)<\\/strong> adalah mekanisme OOP yang memungkinkan sebuah <em>Child Class<\\/em> mewarisi atribut dan method dari <em>Parent Class<\\/em>. Child Class juga dapat menambahkan fitur baru atau mengubah perilaku yang diwarisinya.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1788443794\\/portfolio\\/courses\\/php8qja042l5u11fuwtrnj_wnjnjy.webp\",\"caption\":\"visualisasi inheritance pada pegawai restoran\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Terminologi Utama:<\\/strong><\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Parent Class (Base Class):<\\/strong> class yang menyediakan atribut dan method umum untuk diwariskan.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Child Class (Derived Class):<\\/strong> class yang mewarisi atribut dan method dari Parent Class serta dapat menambahkan fitur yang lebih spesifik.<\\/li><\\/ol><p><br><\\/p><p><strong>Mengapa Menggunakan Inheritance?<\\/strong><\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Reusability<\\/strong>: Kita tidak perlu menulis ulang kode yang sama di banyak class.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span> <strong>Lebih terorganisasi<\\/strong>: Mempermudah pengelompokan class yang memiliki hubungan \\\"is-a\\\" (contoh: Chef adalah Pegawai Restoran).<\\/li><\\/ol><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"2. Implementasi\"},{\"type\":\"paragraf\",\"teks\":\"<p>Di C#, <em>inheritance<\\/em> diterapkan menggunakan tanda titik dua (<code>:<\\/code>) pada deklarasi <em>class<\\/em>. <em>Child Class<\\/em> dapat menggunakan atribut dan method yang diwariskan dari <em>Parent Class<\\/em>, serta menambahkan fitur yang lebih spesifik sesuai kebutuhannya.<\\/p><p><br><\\/p><p><strong>Keyword Penting:<\\/strong><\\/p><p><code>base<\\/code>: digunakan dalam <em>Child Class<\\/em> untuk mengakses anggota atau memanggil <strong>constructor milik Parent Class<\\/strong>. Salah satu penggunaannya adalah meneruskan nilai dari <em>constructor Child<\\/em> ke <em>constructor Parent<\\/em> saat objek dibuat.<\\/p><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using System;\\n\\nnamespace Praktikum3\\n{\\n    \\/\\/ Parent Class (Base Class)\\n    public class PegawaiRestoran\\n    {\\n        public string Nama;\\n        public string IDPegawai;\\n\\n        \\/\\/ Constructor\\n        public PegawaiRestoran() { }\\n\\n        \\/\\/ Constructor dengan parameter\\n        public PegawaiRestoran(string nama, string idPegawai)\\n        {\\n            this.Nama = nama;\\n            this.IDPegawai = idPegawai;\\n        }\\n\\n        public void Bekerja()\\n        {\\n            Console.WriteLine($\\\"{Nama} sedang bekerja.\\\");\\n        }\\n    }\\n\\n    \\/\\/ 1. Child Class - Tanpa Constructor\\n    public class Chef : PegawaiRestoran\\n    {\\n        public void Memasak()\\n        {\\n            Console.WriteLine($\\\"{Nama} sedang memasak.\\\");\\n        }\\n    }\\n\\n    \\/\\/ 2. Child Class - Dengan Constructor\\n    public class Kasir : PegawaiRestoran\\n    {\\n        \\/\\/ Memanggil constructor Parent menggunakan \'base\'\\n        public Kasir(string nama, string idPegawai) : base(nama, idPegawai)\\n        {\\n        }\\n\\n        public void MemprosesPembayaran()\\n        {\\n            Console.WriteLine($\\\"{Nama} sedang memproses pembayaran.\\\");\\n        }\\n    }\\n\\n    \\/\\/ 3. Child Class - Dengan Constructor dan Atribut Tambahan\\n    public class Pelayan : PegawaiRestoran\\n    {\\n        public string AreaTugas;\\n\\n        \\/\\/ Memanggil constructor Parent dan mengisi atribut Child\\n        public Pelayan(string nama, string idPegawai, string areaTugas)\\n            : base(nama, idPegawai)\\n        {\\n            this.AreaTugas = areaTugas;\\n        }\\n\\n        public void MelayaniPelanggan()\\n        {\\n            Console.WriteLine($\\\"{Nama} sedang melayani pelanggan di area {AreaTugas}.\\\");\\n        }\\n    }\\n\\n    class Program\\n    {\\n        static void Main()\\n        {\\n            \\/\\/ Child Class tanpa constructor\\n            Chef chef1 = new Chef();\\n            chef1.Nama = \\\"Budi\\\";\\n            chef1.IDPegawai = \\\"PG001\\\";\\n\\n            Console.WriteLine(\\\"--- Data Chef ---\\\");\\n            Console.WriteLine($\\\"Nama: {chef1.Nama}\\\");\\n            Console.WriteLine($\\\"ID Pegawai: {chef1.IDPegawai}\\\");\\n            chef1.Bekerja();\\n            chef1.Memasak();\\n            Console.WriteLine();\\n\\n            \\/\\/ Child Class dengan constructor\\n            Kasir kasir1 = new Kasir(\\\"Andi\\\", \\\"PG002\\\");\\n\\n            Console.WriteLine(\\\"--- Data Kasir ---\\\");\\n            Console.WriteLine($\\\"Nama: {kasir1.Nama}\\\");\\n            Console.WriteLine($\\\"ID Pegawai: {kasir1.IDPegawai}\\\");\\n            kasir1.Bekerja();\\n            kasir1.MemprosesPembayaran();\\n            Console.WriteLine();\\n\\n            \\/\\/ Child Class dengan constructor dan atribut tambahan\\n            Pelayan pelayan1 = new Pelayan(\\\"Siti\\\", \\\"PG003\\\", \\\"Lantai 2\\\");\\n\\n            Console.WriteLine(\\\"--- Data Pelayan ---\\\");\\n            Console.WriteLine($\\\"Nama: {pelayan1.Nama}\\\");\\n            Console.WriteLine($\\\"ID Pegawai: {pelayan1.IDPegawai}\\\");\\n            Console.WriteLine($\\\"Area Tugas: {pelayan1.AreaTugas}\\\");\\n            pelayan1.Bekerja();\\n            pelayan1.MelayaniPelanggan();\\n        }\\n    }\\n}\"},{\"type\":\"subheading\",\"teks\":\"3. Class Diagram (UML)\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Class Diagram<\\/strong> adalah bagian dari <em>Unified Modeling Language<\\/em> (UML) yang menggambarkan struktur sistem dengan menunjukkan kelas, atribut, metode, dan hubungan antar kelas.<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Aturan pembuatan class diagram<\\/li><\\/ol><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/ik.imagekit.io\\/ekstorage\\/portfolio\\/image_LTyjKaG4V.png\",\"caption\":\"class diagram\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Penulisan Access Modifier dalam Class Diagram<\\/strong><\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>) <code>+<\\/code> ==&gt; public<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>) <code>-<\\/code> ==&gt; private<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>) <code>#<\\/code> ==&gt; protected<\\/li><\\/ol><p><br><\\/p><p><strong>Simbol Hubungan Inheritance:<\\/strong><\\/p><p>Dalam diagram, pewarisan digambarkan dengan <strong>garis lurus dengan ujung panah berbentuk segitiga kosong<\\/strong> yang mengarah dari Child Class ke Parent Class.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1788484944\\/portfolio\\/courses\\/phpjg98m4km42gt2g6uj0g_cjtoo2.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subbab\",\"judul\":\"Polymorphism\",\"judul_idn\":null},{\"type\":\"subheading\",\"teks\":\"Pengertian\"},{\"type\":\"paragraf\",\"teks\":\"<p>Polimorfisme adalah salah satu pilar utama dalam Pemrograman Berorientasi Objek (OOP). Secara etimologi, polimorfisme berasal dari bahasa Yunani: poly (banyak) dan morph (bentuk). Dalam dunia pemrograman, ini berarti satu antarmuka atau metode dapat memiliki banyak implementasi yang berbeda.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<p><br><\\/p><p><strong>ANALOGI<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1789041580\\/portfolio\\/courses\\/php5tiq4428rgvq6DyplFm_kz1v7l.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<p>Bayangkan beberapa hewan sama-sama diminta untuk <strong>bersuara<\\/strong>.<\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Kucing akan merespons dengan <strong>\\u201cMeong\\u201d<\\/strong>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Anjing akan merespons dengan <strong>\\u201cGuk guk\\u201d<\\/strong>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Burung akan merespons dengan <strong>\\u201cCuit cuit\\u201d<\\/strong>.<\\/li><\\/ol><p>Perintahnya sama, tetapi setiap hewan memberikan respons yang berbeda sesuai jenisnya.<\\/p><p>Inilah konsep <strong>polymorphism<\\/strong>: satu aksi yang sama dapat menghasilkan perilaku berbeda pada objek yang berbeda.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"Jenis-jenis Polymorphism dalam C#\"},{\"type\":\"paragraf\",\"teks\":\"<p>Dalam C#, polimorfisme dibagi menjadi dua kategori utama:<\\/p><h2>1. Overloading (Polimorfisme Statis)<\\/h2><p><strong>Overloading <\\/strong>ibarat satu orang yang punya banyak skill. Namanya tetap sama, tapi inputnya beda. Hal ini terjadi di dalam <em>satu kelas yang sama<\\/em>.<\\/p><p>Contoh sederhana:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Metode <code>Tambah(int a, int b)<\\/code><\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Metode <code>Tambah(double a, double b)<\\/code><\\/li><\\/ol><p><em>Contoh: Method Bayar<\\/em><\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><em>Kamu bayar pakai <\\/em>Uang Pas* (1 parameter).<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><em>Kamu bayar pakai <\\/em>Uang Pecahan* (2 parameter atau lebih).<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><em> Kamu bayar pakai <\\/em>Kartu Kredit* (tipe datanya beda, pakai string nomor kartu).<\\/li><\\/ol><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public class Kasir {\\n    \\/\\/ Bayar pakai cash (angka bulat)\\n    public void Bayar(int jumlah) {\\n        Console.WriteLine(\\\"Bayar tunai sebesar: \\\" + jumlah);\\n    }\\n\\n    \\/\\/ Bayar pakai kartu (teks)\\n    public void Bayar(string nomorKartu) {\\n        Console.WriteLine(\\\"Bayar pakai kartu: \\\" + nomorKartu);\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<h2>2.Overriding (Polimorfisme Dinamis)<\\/h2><p>Ini terjadi saat program sedang berjalan. Ini melibatkan penggunaan Inheritance (pewarisan) dan Method Overriding. Di sini, kelas turunan memberikan implementasi spesifik untuk metode yang sudah didefinisikan di kelas induk.<\\/p><p>Implementasi Kode C#<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"\\/\\/ Kelas Induk (Base Class)\\n\\npublic class Hewan\\n{\\n    \\/\\/ Keyword \'virtual\' mengizinkan metode ini diubah oleh kelas turunan\\n\\n    public virtual void Suara()\\n    {\\n        Console.WriteLine(\\\"Hewan mengeluarkan suara\\\");\\n\\n    }\\n}\\n\\n\\/\\/ Kelas Turunan (Derived Class)\\n\\npublic class Anjing : Hewan\\n{\\n    \\/\\/ Keyword \'override\' digunakan untuk mengganti perilaku metode induk\\n\\n    public override void Suara()\\n    {\\n        Console.WriteLine(\\\"Anjing menggonggong: Guk Guk!\\\");\\n    }\\n\\n}\\n\\npublic class Kucing : Hewan\\n{\\n\\n    public override void Suara()\\n    {\\n        Console.WriteLine(\\\"Kucing mengeong: Meong!\\\");\\n    }\\n\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Cara Penggunaannya:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public class Program\\n{\\n    public static void Main()\\n    {\\n        \\/\\/ Polimorfisme: Tipe data Hewan, tetapi instansiasi spesifik\\n        Hewan peliharaan1 = new Anjing();\\n\\n        Hewan peliharaan2 = new Kucing();\\n\\n        peliharaan1.Suara(); \\/\\/ Output: Anjing menggonggong\\n\\n        peliharaan2.Suara(); \\/\\/ Output: Kucing mengeong\\n\\n    }\\n\\n}\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"Perbedaan Overloading dan Overriding\"},{\"type\":\"tabel\",\"headers\":[\"Aspek\",\"Overloading\",\"Overriding\"],\"rows\":[[\"Parameter\",\"Harus berbeda (tipe data \\/ jumlah parameter)\",\"Harus sama\"],[\"Return Type\",\"Boleh sama atau berbeda\",\"Harus sama\"],[\"Fleksibiltas\",\"Menangani input yang berbeda dalam satu Method\",\"Mengubah perilaku bawaan dari superclass\"]],\"caption\":\"\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"Manfaat Polymorphism\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Fleksibilitas:<\\/strong><\\/li><\\/ol><p>Polimorfisme memungkinkan objek berperilaku seolah-olah termasuk dalam kelas yang berbeda, sehingga kode menjadi lebih mudah beradaptasi. Hal ini sangat bermanfaat dalam sistem yang besar dan kompleks, di mana transisi yang mulus antara berbagai tipe objek meningkatkan fleksibilitas sistem secara keseluruhan.<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Kemampuan penggunaan kembali:<\\/strong><\\/li><\\/ol><p><strong>Polimorfisme<\\/strong> memfasilitasi penggunaan kembali kode dengan memungkinkan satu antarmuka atau metode superkelas untuk diimplementasikan dalam berbagai cara oleh berbagai subkelas. Hal ini meningkatkan kemampuan penggunaan kembali kode di berbagai skenario.<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Kemudahan Pemeliharaan dan Skalabilitas:<\\/strong><\\/li><\\/ol><p>Sistem yang menggunakan polimorfisme membutuhkan lebih sedikit perubahan kode ketika kelas baru ditambahkan atau kelas yang sudah ada dimodifikasi. Hal ini menyederhanakan pemeliharaan perangkat lunak dan mempermudah perluasan di masa mendatang.<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>Kemudahan pemahaman:<\\/strong><\\/li><\\/ol><p>Dengan memungkinkan pengembangan modular, polimorfisme membuat kode lebih mudah dipahami. Metode yang melakukan tugas yang sama dapat diimplementasikan secara berbeda di berbagai kelas, memastikan setiap kelas tetap mandiri dan mudah dikelola.<\\/p><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"subbab\",\"judul\":\"Enkapsulasi (Encapsulation)\",\"judul_idn\":null},{\"type\":\"paragraf\",\"teks\":\"<p>Belajar memahami mengapa data perlu dilindungi, bagaimana menerapkan enkapsulasi menggunakan properties, dan kapan menggunakannya dalam proyek nyata.<\\/p><h2>Tujuan pembelajaran<\\/h2><p>Setelah mempelajari materi ini, kamu diharapkan mampu:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Memahami konsep enkapsulasi melalui analogi sehari-hari.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Menjelaskan masalah ketika field dapat diubah secara bebas.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Menggunakan <code>private<\\/code>, <code>public<\\/code>, dan properties di C#.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Membuat validasi data menggunakan <code>set<\\/code>.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Menerapkan enkapsulasi pada studi kasus sederhana.<\\/li><\\/ol><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"1. Analogi dunia nyata\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Mesin ATM: saldo tidak boleh diubah sembarangan<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/imgs.search.brave.com\\/W-i7WE_UO5NyF0jm-m1yjm226GFyi69zLMPT696uOII\\/rs:fit:500:0:1:0\\/g:ce\\/aHR0cHM6Ly9tZWRp\\/YS5pc3RvY2twaG90\\/by5jb20vaWQvMTc3\\/NDM2MTY5MS9waG90\\/by9hdG0tY2VudHJl\\/LWF0bXMtJUQxJTgx\\/YXNoLW1hY2hpbmVz\\/LmpwZz9zPTYxMng2\\/MTImdz0wJms9MjAm\\/Yz1rUjl4LVVlZURp\\/bUh1ZmhyMDNkY1pN\\/UkpGN1Uxa2NvdEZw\\/cmxVWFRPRlJjPQ\",\"caption\":\"gambar atm\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<p>Bayangkan kamu memiliki rekening bank dengan saldo Rp500.000.<\\/p><p>Ketika ingin mengambil uang, kamu menggunakan ATM. Kamu memasukkan PIN, memilih jumlah uang, lalu ATM memproses transaksi.<\\/p><p>Kamu tidak bisa langsung membuka sistem internal ATM dan mengganti saldo menjadi Rp10.000.000 hanya dengan mengetik angka.<\\/p><p>Mengapa?<\\/p><p>Karena sistem ATM memiliki aturan:<\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Saldo disimpan di dalam sistem dan tidak bisa diakses sembarangan.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pengguna hanya bisa melakukan operasi yang disediakan, seperti setor uang atau tarik uang.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sistem memeriksa apakah saldo mencukupi sebelum uang ditarik.<\\/li><\\/ol><p><strong>Hubungannya dengan OOP<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Dunia nyata\",\"C#\"],\"rows\":[[\"Saldo rekening\",\"Field atau data dalam class\"],[\"Sistem internal ATM\",\"Data yang disembunyikan (private)\"],[\"Tombol tarik\\/setor tunai\",\"Method atau property yang dapat diakses\"],[\"Validasi saldo\",\"Logika bisnis di dalam class\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<p>Inti enkapsulasi:<\\/p><blockquote>Enkapsulasi adalah prinsip OOP yang menggabungkan data dan perilaku dalam sebuah class, sekaligus membatasi akses langsung terhadap data tersebut agar hanya dapat digunakan melalui aturan yang ditentukan.<\\/blockquote><p>Jadi, enkapsulasi bukan sekadar membuat field menjadi <code>private<\\/code>. Tujuan utamanya adalah menjaga agar data tetap valid dan perubahan terhadapnya dapat dikontrol.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"2. Masalah tanpa enkapsulasi (Kode Sebelum)\"},{\"type\":\"paragraf\",\"teks\":\"<p>Mari kita buat simulasi rekening bank sederhana.<\\/p><h2>Contoh kode C# tanpa enkapsulasi<\\/h2>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using System;\\n\\nclass RekeningBank\\n{\\n    public string NamaPemilik;\\n    public decimal Saldo;\\n}\\n\\nclass Program\\n{\\n    static void Main()\\n    {\\n        RekeningBank rekening = new RekeningBank();\\n\\n        rekening.NamaPemilik = \\\"Budi\\\";\\n        rekening.Saldo = 500000;\\n\\n        Console.WriteLine($\\\"Saldo awal: {rekening.Saldo}\\\");\\n\\n        \\/\\/ Class lain dapat mengubah saldo secara bebas\\n        rekening.Saldo = -1000000;\\n\\n        Console.WriteLine($\\\"Saldo akhir: {rekening.Saldo}\\\");\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Output<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"Saldo awal: 500000\\nSaldo akhir: -1000000\"},{\"type\":\"paragraf\",\"teks\":\"<p>Secara teknis, program tersebut dapat berjalan. Namun, secara logika bisnis, saldo rekening menjadi tidak masuk akal.<\\/p><h2>Apa masalahnya?<\\/h2><h3>1. Data dapat diubah sembarangan<\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"rekening.Saldo = -1000000;\"},{\"type\":\"paragraf\",\"teks\":\"<p>Class <code>Program<\\/code> dapat langsung mengganti nilai saldo tanpa meminta izin atau mengikuti aturan tertentu.<\\/p><h3>2. Tidak ada validasi<\\/h3><p>Saldo seharusnya tidak boleh negatif dalam simulasi rekening sederhana ini. Namun, class <code>RekeningBank<\\/code> tidak memiliki mekanisme untuk mencegahnya.<\\/p><h3>3. Class lain terlalu mengetahui detail internal<\\/h3><p>Class lain dapat memanipulasi data rekening secara langsung. Jika aturan saldo berubah, kita harus mencari semua bagian kode yang mungkin mengubah field tersebut.<\\/p><h3>Gambaran masalah<\\/h3>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1789578962\\/portfolio\\/courses\\/php72gsu7pak4e55UQqdp7_sb4bda.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<p>Catatan: <code>public<\\/code> bukan berarti selalu buruk. Field atau property <code>public<\\/code> berguna ketika data memang boleh diakses. Masalahnya adalah ketika data penting dapat diubah tanpa kontrol.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"subheading\",\"teks\":\"3. Solusi dengan enkapsulasi (Kode Sesudah)\"},{\"type\":\"paragraf\",\"teks\":\"<p>Sekarang kita perbaiki class <code>RekeningBank<\\/code> agar saldo tidak bisa diubah secara langsung oleh class lain.<\\/p><h2>Langkah 1 \\u2014 Gunakan access modifiers<\\/h2><p>Access modifier menentukan siapa yang dapat mengakses anggota sebuah class.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Modifier\",\"Akses\"],\"rows\":[[\"public\\n\",\"Dapat diakses dari luar class\\n\"],[\"private\",\"Hanya dapat diakses di dalam class itu sendiri\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<p>Contoh<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"class RekeningBank\\n{\\n    private decimal saldo;\\n\\n    public void TampilkanSaldo()\\n    {\\n        Console.WriteLine(saldo);\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Di sini:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>saldo<\\/code> bersifat <code>private<\\/code>.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Class <code>Program<\\/code> tidak bisa mengubah <code>saldo<\\/code> secara langsung.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Method <code>TampilkanSaldo()<\\/code> dapat digunakan untuk membaca saldo.<\\/li><\\/ol><p>Jika kita menulis:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"rekening.saldo = -1000000;\"},{\"type\":\"paragraf\",\"teks\":\"<p>Maka akan muncul error karena <code>saldo<\\/code> bersifat <code>private<\\/code>.<\\/p><p><br><\\/p><p><img src=\\\"data:image\\/png;base64,iVBORw0KGgoAAAANSUhEUgAAA1kAAACECAYAAABiSeFfAAAAAXNSR0IArs4c6QAAAARnQU1BAACxjwv8YQUAAAAJcEhZcwAADsMAAA7DAcdvqGQAADA\\/SURBVHhe7d0HmFxV3YDxk0oKCaGH3rsU6V1AsVKlfQRRVESkKFUEpQooTZpgRRFEqgqoFJEuSO9IL6GGDgkpJIR8vGfnbG7GO7NT7szuJu\\/veebZ2Zk7M3fuPfec8z9t+oQQpn18kyRJkiQVoG\\/pryRJkiSpAAZZkiRJklSgpoYLDho0KAwcODAMGDAg9OvXL\\/Tta8wmSZIkqff56KOPwtSpU8OUKVPC5MmTw6RJk0rP1K\\/uIKtPnz5h6NChYciQIQZVkiRJkmZKBF0TJkwI48ePD9Om1dcvVVeQNX