W3iiGBlAUshEIAySqvLIBBuczCJeo58uZk8SMFR3XcnY7uSEmzth122CGuisXysSzNrmKxEhmFJpUAVo9iBTXG2dNCycpQLJvOaniaeVH5s4LfPQywZj4EVaxeyAqNNFgRpLByNauo0jvEIkK9AY1ulAuUCdm\\/BFcMH2clRVZEVc9CmV7OnixJkrpR6tFK99U6KagywJJUpLyeLIMsSZIkSWqQS7hLkiRJUosZZEmSJElSgQyyJEmSJKlABlmSJEmSVCCDLEmSJEkqkEGWJEmSJBXIIEuSJEmSCmSQJUmSJEkFyg2y0i\\/PS5IkSZLyVYqbcoOsqVOnlu5JkiRJkvJUiptyg6wpU6aU7kmSJEmS8lSKm3KDrMmTJ5fuSZIkSZLyVIqbcoOsSZMmOS9LkiRJkiogXiJuypMbZGHChAmle5IkSZKkrGrxUsUga\\/z48fZmSZIkSVIZ4iTipUoqBlnTpk0L48aNK\\/0nSZIkSQJxEvFSJRWDLEycONFhg5IkSZJUQnxEnFRN1SALY8eOrTihS5IkSZJmFcRFxEdd6fPxrXI\\/V8bw4cPDkCFDSv9JkiRJ0qyDHqxaAizUHGRh8ODBYdiwYaFv3y47wCRJkiSp12ORC+ZgdTVEMKuuIAt9+vQJQ4cOjb1aBluSJEmSZkYEV\\/ResYpgtUUu8tQdZGUNGjQoDBw4MAwYMCD069fPoEuSJElSr0RQNXXq1DBlypQwefLkptalaCrIkiRJkiTNyK4nSZIkSSqQQZYkSZIkFcggS5IkSZIKZJAlSZIkSQUyyJIkSZKkAhlkSZIkSVJhQvh\\/9xMk1v+lWB0AAAAASUVORK5CYII=\\\"><\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Langkah 2 \\u2014 Gunakan Properties C#<\\/strong><\\/p><p>Di C#, cara modern untuk mengontrol akses data adalah menggunakan property.<\\/p><p>Property terlihat seperti variabel ketika digunakan, tetapi dapat memiliki logika saat data dibaca atau diubah.<\\/p><h3>Struktur property<\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public decimal Saldo\\n{\\n    get { return saldo; }\\n    set { saldo = value; }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Penjelasan:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Bagian  \",\"Fungsi\"],\"rows\":[[\"public\",\"Property bisa diakses dari luar class\"],[\"decimal\",\"Tipe data saldo\"],[\"Saldo\",\"Nama property\"],[\"get\",\"Mengambil nilai\"],[\"set\",\"Mengubah nilai\"],[\"value\",\"Nilai baru yang dikirim ke property\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<h3>Versi modern C#<\\/h3><p>C# juga mendukung sintaks yang lebih ringkas:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public decimal Saldo\\n{\\n    get;\\n    set;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Namun, jika kita ingin melakukan validasi, kita perlu menambahkan logika di dalam <code>set<\\/code>.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<h2>Langkah 3 \\u2014 Enkapsulasi dengan validasi saldo<\\/h2><p>Berikut contoh class rekening yang sudah diperbaiki.<\\/p><h3>Kode C# lengkap<\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using System;\\n\\nclass RekeningBank\\n{\\n    \\/\\/ Field private: tidak bisa diakses langsung dari luar\\n    private decimal saldo;\\n\\n    public string NamaPemilik { get; set; }\\n\\n    public decimal Saldo\\n    {\\n        get\\n        {\\n            return saldo;\\n        }\\n        private set\\n        {\\n            if (value >= 0)\\n            {\\n                saldo = value;\\n            }\\n            else\\n            {\\n                Console.WriteLine(\\\"Saldo tidak boleh negatif!\\\");\\n            }\\n        }\\n    }\\n\\n    public RekeningBank(string namaPemilik, decimal saldoAwal)\\n    {\\n        NamaPemilik = namaPemilik;\\n\\n        if (saldoAwal >= 0)\\n        {\\n            saldo = saldoAwal;\\n        }\\n        else\\n        {\\n            throw new ArgumentException(\\n                \\\"Saldo awal tidak boleh negatif.\\\"\\n            );\\n        }\\n    }\\n\\n    public void Setor(decimal jumlah)\\n    {\\n        if (jumlah > 0)\\n        {\\n            Saldo += jumlah;\\n            Console.WriteLine(\\n                $\\\"Setor berhasil: {jumlah}\\\"\\n            );\\n        }\\n        else\\n        {\\n            Console.WriteLine(\\n                \\\"Jumlah setor harus lebih dari 0.\\\"\\n            );\\n        }\\n    }\\n\\n    public void Tarik(decimal jumlah)\\n    {\\n        if (jumlah <= 0)\\n        {\\n            Console.WriteLine(\\n                \\\"Jumlah tarik harus lebih dari 0.\\\"\\n            );\\n        }\\n        else if (jumlah > Saldo)\\n        {\\n            Console.WriteLine(\\n                \\\"Saldo tidak mencukupi.\\\"\\n            );\\n        }\\n        else\\n        {\\n            Saldo -= jumlah;\\n            Console.WriteLine(\\n                $\\\"Tarik berhasil: {jumlah}\\\"\\n            );\\n        }\\n    }\\n}\\n\\nclass Program\\n{\\n    static void Main()\\n    {\\n        RekeningBank rekening =\\n            new RekeningBank(\\\"Budi\\\", 500000);\\n\\n        Console.WriteLine(\\n            $\\\"Pemilik: {rekening.NamaPemilik}\\\"\\n        );\\n\\n        Console.WriteLine(\\n            $\\\"Saldo awal: {rekening.Saldo}\\\"\\n        );\\n\\n        rekening.Setor(200000);\\n\\n        rekening.Tarik(100000);\\n\\n        Console.WriteLine(\\n            $\\\"Saldo akhir: {rekening.Saldo}\\\"\\n        );\\n\\n        \\/\\/ Tidak diperbolehkan:\\n        \\/\\/ rekening.Saldo = -1000000;\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Output<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"plaintext\",\"kode\":\"Pemilik: Budi\\nSaldo awal: 500000\\nSetor berhasil: 200000\\nTarik berhasil: 100000\\nSaldo akhir: 600000\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<h2>Bedah kode: bagian penting<\\/h2><h3>A. Field <code>private<\\/code><\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"private decimal saldo;\"},{\"type\":\"paragraf\",\"teks\":\"<p>Field saldo hanya bisa diakses langsung dari dalam class <code>RekeningBank<\\/code>.<\\/p><p>Class <code>Program<\\/code> tidak dapat melakukan:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"rekening.saldo = -1000000;\"},{\"type\":\"paragraf\",\"teks\":\"<p>Ini adalah pembatasan akses terhadap data internal.<\\/p><h3>B. Property dengan <code>private set<\\/code><\\/h3><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public decimal Saldo\\n{\\n    get;\\n    private set;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Dalam contoh lengkap, property ditulis dengan validasi:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public decimal Saldo\\n{\\n    get\\n    {\\n        return saldo;\\n    }\\n    private set\\n    {\\n        if (value >= 0)\\n        {\\n            saldo = value;\\n        }\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Artinya:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>public get<\\/code> \\u2192 saldo dapat dibaca dari luar class.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><code>private set<\\/code> \\u2192 saldo hanya dapat diubah melalui kode di dalam class.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Validasi <code>value &gt;= 0<\\/code> \\u2192 nilai negatif ditolak.<\\/li><\\/ol><h3>C. Method <code>Setor()<\\/code> dan <code>Tarik()<\\/code><\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public void Setor(decimal jumlah)\\n{\\n    if (jumlah > 0)\\n    {\\n        Saldo += jumlah;\\n    }\\n}\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public void Tarik(decimal jumlah)\\n{\\n    if (jumlah > 0 && jumlah <= Saldo)\\n    {\\n        Saldo -= jumlah;\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Class dari luar tidak mengubah saldo secara langsung. Mereka meminta class rekening melakukan operasi melalui method yang disediakan.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Visualisasi alur enkapsulasi<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1789579156\\/portfolio\\/courses\\/phpe7blhmvge6k977RNXOg_jdkz8z.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<p>Perbandingan kode sebelum dan sesudah<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Sebelum  \",\"Sesudah\"],\"rows\":[[\"public decimal Saldo;\\n\",\"private decimal saldo;\"],[\"Bisa diubah bebas\",\"Tidak bisa diubah langsung\"],[\"Tidak ada validasi\",\"Ada validasi\"],[\"Class lain memanipulasi data\",\"Class mengatur perubahan melalui method\"],[\"Risiko data tidak valid\",\"Data lebih terkontrol\"]],\"caption\":\"\"},{\"type\":\"subheading\",\"teks\":\"4. Kesimpulan\"},{\"type\":\"paragraf\",\"teks\":\"<h2>Tiga manfaat utama enkapsulasi<\\/h2><h3>1. Melindungi data<\\/h3><p>Dengan <code>private<\\/code>, data penting tidak dapat diubah sembarangan dari luar class.<\\/p><p>Contoh: saldo rekening tidak dapat langsung diisi angka negatif.<\\/p><h3>2. Menjaga validitas data<\\/h3><p>Dengan property atau method yang memiliki validasi, class dapat memastikan data sesuai aturan.<\\/p><p>Contoh:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"if (value >= 0)\\n{\\n    saldo = value;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<h3>3. Mempermudah pemeliharaan kode<\\/h3><p>Aturan perubahan data berada di dalam class yang bertanggung jawab.<\\/p><p>Jika aturan saldo berubah, kita dapat memperbaiki logika di <code>RekeningBank<\\/code> tanpa harus mengubah semua class yang menggunakan rekening.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subbab\",\"judul\":\"Association, Composition, dan Aggregation\",\"judul_idn\":null},{\"type\":\"paragraf\",\"teks\":\"<p>Dalam <strong>Object-Oriented Programming (OOP)<\\/strong>, sebuah sistem umumnya terdiri dari beberapa <strong>class<\\/strong> yang saling berinteraksi untuk menjalankan fungsi tertentu. Hubungan antar-class tersebut disebut <strong>relationship<\\/strong>.<\\/p><p>Terdapat beberapa bentuk relationship, di antaranya <strong>Association, Aggregation, <\\/strong>dan <strong>Composition<\\/strong>. Ketiganya sama-sama menggambarkan hubungan antar-object, tetapi memiliki tingkat keterikatan dan kepemilikan yang berbeda.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/miro.medium.com\\/1*yu9X0kIyCve3lBdbbhsx2Q.png\",\"caption\":\"Contoh penerapan Association, Aggregation, dan Composition dalam kehidupan nyata\",\"ukuran\":\"penuh\"},{\"type\":\"subheading\",\"teks\":\"1. Association\"},{\"type\":\"paragraf\",\"teks\":\"<h3><strong>Pengertian<\\/strong><\\/h3><p>Association adalah hubungan antar-class ketika suatu object dapat menggunakan atau berinteraksi dengan object dari class lain, <strong>tanpa adanya hubungan kepemilikan<\\/strong> (ownership) di antara keduanya.<\\/p><h3><strong>Contoh Kasus: Student dan Course<\\/strong><\\/h3><p>Pada kasus <strong>Student dan Course<\\/strong>, <code>Student<\\/code> berhubungan dengan <code>course<\\/code> karena student dapat mengikuti suatu course. Namun, <code>Student<\\/code> tidak memiliki <code>course<\\/code>, dan <code>course<\\/code> tidak menjadi bagian dari <code>Student<\\/code>.<\\/p><h3><span class=\\\"ql-cursor\\\">\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff<\\/span><strong>Ciri Utama<\\/strong><\\/h3><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><span class=\\\"ql-cursor\\\">\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff\\ufeff<\\/span>Tidak terdapat ownership.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Kedua object dapat berdiri secara independen.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Hubungan terbentuk karena adanya interaksi atau penggunaan object lain.<\\/li><\\/ol><h3><strong>Implementasi<\\/strong><\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"class Student\\n{\\n    public string Name{ get; set; }\\n\\n    public void Enroll(Course course)\\n    {\\n        Console.WriteLine($\\\"{Name} mengikuti {course.Name}\\\");\\n    }\\n}\\n\\nclass Course\\n{\\n    public string Name{ get; set; }\\n\\n    public Course(string name)\\n    {\\n        Name= name;\\n    }\\n}\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"Student student = new Student\\n{\\n    Name = \\\"Andi\\\"\\n};\\n\\nCourse course = new Course(\\\"Pemrograman C#\\\");\\n\\nstudent.Enroll(course);\"},{\"type\":\"subheading\",\"teks\":\"2. Aggregation\"},{\"type\":\"paragraf\",\"teks\":\"<h3><strong>Pengertian<\\/strong><\\/h3><p><strong>Aggregation adalah hubungan has-a<\\/strong> ketika suatu object memiliki object dari class lain, tetapi object yang dimiliki <strong>dapat berdiri sendiri<\\/strong> tanpa object pemiliknya.<\\/p><h3><strong>Contoh Kasus: <\\/strong>Car dan Wheel<\\/h3><p>Pada kasus <strong>Car dan Wheel<\\/strong>, sebuah <code>Car<\\/code> memiliki beberapa <code>Wheel<\\/code>. Namun, <code>Wheel<\\/code> bukan bagian yang sepenuhnya bergantung pada <code>Car<\\/code>. Sebuah <code>Wheel<\\/code> dapat dibuat, digunakan, atau dipindahkan ke <code>Car<\\/code> lain secara independen.<\\/p><h3><strong>Ciri Utama<\\/strong><\\/h3><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Terdapat ownership, yaitu Car memiliki Wheel.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Object Wheel dapat dibuat dan dikelola secara independen.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Wheel dapat digunakan oleh object Car lain.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Hubungan memiliki sifat weak ownership.<\\/li><\\/ol><h3><strong>Implementasi<\\/strong><\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"class Wheel\\n{\\n    public string Brand { get; set; }\\n\\n    public Wheel(string brand)\\n    {\\n        Brand = brand;\\n    }\\n}\\n\\nclass Car\\n{\\n    public string Model { get; set; }\\n    public List<Wheel> Wheels { get; set; }\\n\\n    public Car(string model, List<Wheel> wheels)\\n    {\\n        Model = model;\\n        Wheels = wheels;\\n    }\\n}\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"Wheel wheel1 = new Wheel(\\\"Michelin\\\");\\nWheel wheel2 = new Wheel(\\\"Bridgestone\\\");\\n\\nList<Wheel> wheels = new List<Wheel>\\n{\\n    wheel1,\\n    wheel2\\n};\\n\\nCar car = new Car(\\\"Toyota\\\", wheels);\"},{\"type\":\"subheading\",\"teks\":\"3. Composition\"},{\"type\":\"paragraf\",\"teks\":\"<h3><strong>Pengertian<\\/strong><\\/h3><p><strong>Composition adalah hubungan has-a<\\/strong> ketika suatu object memiliki object dari class lain sebagai bagian integralnya, sehingga object yang dimiliki <strong>bergantung pada object pemiliknya<\\/strong>.<\\/p><h3><strong>Contoh Kasus: House dan Room<\\/strong><\\/h3><p>Pada kasus <strong>House dan Room<\\/strong>, sebuah <code>House<\\/code> memiliki beberapa <code>Room<\\/code>. <code>Room<\\/code> dianggap sebagai bagian dari <code>House<\\/code>, sehingga keberadaannya dikelola oleh <code>House<\\/code>.<\\/p><h3><strong>Ciri utama<\\/strong><\\/h3><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Terdapat <strong>strong ownership<\\/strong>.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Object bagian dibuat dan dikelola oleh object pemilik.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Object bagian merupakan bagian integral dari object pemilik.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Lifecycle object bagian bergantung pada object pemilik.<\\/li><\\/ol><h3><strong>Implementasi<\\/strong><\\/h3>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"class Room\\n{\\n    public string Name { get; set; }\\n\\n    public Room(string name)\\n    {\\n        Name = name;\\n    }\\n}\\n\\nclass House\\n{\\n    public string Address { get; set; }\\n    public List<Room> Rooms { get; set; }\\n\\n    public House(string address)\\n    {\\n        Address = address;\\n\\n        Rooms = new List<Room>\\n        {\\n            new Room(\\\"Living Room\\\"),\\n            new Room(\\\"Bedroom\\\")\\n        };\\n    }\\n}\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"House house = new House(\\\"Jl. Mawar No. 10\\\");\"},{\"type\":\"subheading\",\"teks\":\"Perbedaan\"},{\"type\":\"tabel\",\"headers\":[\"Aspek\",\"Association\",\"Association\",\"Composition\"],\"rows\":[[\"Hubungan\",\"Berinteraksi dengan object lain\",\"Has-a\",\"Has-a\"],[\"Ownership\",\"Tidak ada\",\"Weak ownership\",\"Strong ownership\"],[\"Ketergantungan\",\"Object independen\",\"Object bagian dapat berdiri sendiri\",\"Object bagian bergantung pada pemilik\"],[\"Contoh\",\"Student \\u2192 Course\",\"Car \\u2192 Wheel\",\"House \\u2192 Room\"]],\"caption\":\"\"},{\"type\":\"subbab\",\"judul\":\"Abstract Class, Interface, dan Class Library\",\"judul_idn\":null},{\"type\":\"paragraf\",\"teks\":\"<h1>Abstraction<\\/h1><p><strong>Abstraction <\\/strong>(abstraksi) adalah salah satu konsep dalam OOP yang digunakan untuk menyembunyikan detail proses dan hanya menampilkan bagian yang memang perlu digunakan.<\\/p><blockquote><strong>Sederhananya: <\\/strong>menampilkan yang penting saja dan menyembunyikan detail yang tidak perlu diketahui pengguna.<\\/blockquote><p>Contohnya saat login ke sebuah aplikasi. Pengguna cukup memasukkan email dan password lalu menekan tombol login. Proses pengecekan database, validasi password, dan autentikasi tidak perlu diketahui oleh pengguna.<\\/p><p>Dalam C#, abstraction biasanya diterapkan menggunakan:<\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Abstract Class<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Interface<\\/li><\\/ol><p>Abstraction juga berkaitan dengan konsep OOP lain seperti encapsulation, inheritance, dan polymorphism.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<h1>1. Abstract Class<\\/h1><h2>1.1 Pengertian<\\/h2><p><strong>Abstract Class <\\/strong>adalah class yang digunakan sebagai dasar untuk class turunannya. Abstract class tidak bisa dibuat menjadi object secara langsung dan biasanya digunakan ketika beberapa class memiliki karakteristik atau proses dasar yang sama.<\\/p><p>Abstract class dapat memiliki:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Method biasa yang sudah memiliki isi.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Abstract method yang belum memiliki isi.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Property, field, dan constructor.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Abstract method yang harus diimplementasikan class turunan menggunakan override.<\\/li><\\/ol><p>Contohnya, Kendaraan dapat dijadikan abstract class karena Mobil dan Motor sama-sama termasuk kendaraan, tetapi cara setiap kendaraan berjalan bisa berbeda.<\\/p><h2>1.2 Contoh Abstract Class<\\/h2>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using System;\\n\\nabstract class Kendaraan\\n{\\n    public abstract void Jalan();\\n\\n    public void Info()\\n    {\\n        Console.WriteLine(\\\"Ini adalah kendaraan\\\");\\n    }\\n}\\n\\nclass Mobil : Kendaraan\\n{\\n    public override void Jalan()\\n    {\\n        Console.WriteLine(\\\"Mobil berjalan dengan roda\\\");\\n    }\\n}\\n\\nclass Program\\n{\\n    static void Main()\\n    {\\n        Mobil mobil = new Mobil();\\n        mobil.Info();\\n        mobil.Jalan();\\n    }\\n}\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p>Pada contoh tersebut, <code>Kendaraan<\\/code> adalah abstract class. Method <code>Jalan()<\\/code> belum memiliki implementasi di class Kendaraan, sehingga class <code>Mobil<\\/code> harus mengimplementasikannya menggunakan override. Sementara itu, <code>Info()<\\/code> adalah method biasa yang langsung dapat digunakan oleh class turunannya.<\\/p><h2>1.3 Contoh pada Sistem Pembayaran<\\/h2><p>Pada sistem pembayaran, bagian yang sama dapat ditempatkan di abstract class Pembayaran, sedangkan proses pembayarannya dibuat abstract karena setiap metode pembayaran mempunyai proses yang berbeda.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"abstract class Pembayaran\\n{\\n    public string NamaMetode { get; set; }\\n\\n    public Pembayaran(string nama)\\n    {\\n        NamaMetode = nama;\\n    }\\n\\n    public abstract void ProsesPembayaran(decimal jumlah);\\n}\\n\\nclass TransferBank : Pembayaran\\n{\\n    public TransferBank() : base(\\\"Transfer Bank\\\") { }\\n\\n    public override void ProsesPembayaran(decimal jumlah)\\n    {\\n        Console.WriteLine($\\\"Transfer {jumlah} melalui bank\\\");\\n    }\\n}\\n\\nclass EWallet : Pembayaran\\n{\\n    public EWallet() : base(\\\"E-Wallet\\\") { }\\n\\n    public override void ProsesPembayaran(decimal jumlah)\\n    {\\n        Console.WriteLine($\\\"Bayar {jumlah} menggunakan E-Wallet\\\");\\n    }\\n}\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p><code>TransferBank<\\/code> dan <code>EWallet<\\/code> sama-sama merupakan jenis Pembayaran, tetapi isi <code>ProsesPembayaran()<\\/code> dibuat berbeda sesuai kebutuhan masing-masing.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<h1>2. Interface<\\/h1><h2>2.1 Pengertian<\\/h2><p><strong>Interface <\\/strong>adalah aturan atau kontrak yang menentukan kemampuan yang harus dimiliki sebuah class. Jika sebuah class mengimplementasikan interface, class tersebut harus menyediakan implementasi dari anggota yang dibutuhkan interface tersebut.<\\/p><blockquote><strong>Sederhananya: <\\/strong>interface menentukan apa yang harus tersedia, sedangkan class menentukan bagaimana cara menjalankannya.<\\/blockquote><p>Interface cocok digunakan ketika beberapa class memiliki kemampuan yang sama meskipun tidak harus memiliki hubungan parent-child. Satu class juga dapat mengimplementasikan lebih dari satu interface.<\\/p><h2>2.2 Contoh Interface<\\/h2>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using System;\\n\\ninterface IHewan\\n{\\n    void Suara();\\n}\\n\\nclass Kucing : IHewan\\n{\\n    public void Suara()\\n    {\\n        Console.WriteLine(\\\"Meong\\\");\\n    }\\n}\\n\\nclass Anjing : IHewan\\n{\\n    public void Suara()\\n    {\\n        Console.WriteLine(\\\"Guk guk\\\");\\n    }\\n}\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p><code>IHewan<\\/code> menentukan bahwa class yang menggunakannya harus memiliki <code>Suara()<\\/code>. <code>Kucing<\\/code> dan <code>Anjing<\\/code> sama-sama memenuhi kontrak tersebut, tetapi implementasinya berbeda.<\\/p><h2>2.3 Interface dalam Sistem Pembayaran<\\/h2><p>Pada sistem pembayaran, interface IPembayaran dapat digunakan sebagai kontrak agar setiap metode pembayaran memiliki proses pembayaran.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"interface IPembayaran\\n{\\n    void ProsesPembayaran(decimal jumlah);\\n}\\n\\nclass TransferBank : IPembayaran\\n{\\n    public void ProsesPembayaran(decimal jumlah)\\n    {\\n        Console.WriteLine($\\\"Transfer {jumlah} melalui bank\\\");\\n    }\\n}\\n\\nclass EWallet : IPembayaran\\n{\\n    public void ProsesPembayaran(decimal jumlah)\\n    {\\n        Console.WriteLine($\\\"Bayar {jumlah} menggunakan E-Wallet\\\");\\n    }\\n}\\n\\nclass PaymentService\\n{\\n    public void Bayar(IPembayaran metode, decimal jumlah)\\n    {\\n        metode.ProsesPembayaran(jumlah);\\n    }\\n}\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p><code>PaymentService<\\/code> cukup menerima object bertipe <code>IPembayaran<\\/code>. Selama sebuah class memenuhi kontrak <code>IPembayaran<\\/code>, class tersebut dapat digunakan oleh service tanpa harus mengetahui detail prosesnya.<\\/p><h1>Perbedaan Abstract Class dan Interface<\\/h1><p>Keduanya sama-sama dapat digunakan untuk abstraction, tetapi tujuan penggunaannya berbeda.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Abstract Class\",\"Interface\"],\"rows\":[[\"Digunakan sebagai dasar class turunan\",\"Digunakan sebagai aturan atau kontrak\"],[\"Bisa memiliki method biasa dan abstract method\",\"Berfokus pada kemampuan\\/perilaku yang harus tersedia\"],[\"Bisa memiliki property, field, dan constructor\",\"Tidak digunakan sebagai class dasar yang menyimpan state dengan cara yang sama\"],[\"Class hanya dapat mewarisi satu class\",\"Class dapat mengimplementasikan beberapa interface\"],[\"Cocok untuk hubungan parent-child\",\"Cocok untuk kemampuan yang sama pada beberapa class\"]],\"caption\":\"\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<p>Contoh Abstract Class: Mobil, Motor, dan Bus dapat diturunkan dari Kendaraan karena memiliki hubungan yang jelas sebagai jenis kendaraan.<\\/p><p>Contoh Interface: TransferBank, EWallet, dan KartuKredit dapat menggunakan IPembayaran karena semuanya memiliki kemampuan melakukan pembayaran.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<h1>3. Class Library<\\/h1><h2>3.1 Pengertian<\\/h2><p><strong>Class Library <\\/strong>adalah project yang berisi kumpulan kode yang dibuat agar dapat digunakan kembali oleh project lain. Isinya dapat berupa class, abstract class, interface, enum, utility, atau service.<\\/p><p>Class Library biasanya tidak memiliki <code>Main()<\\/code> karena bukan aplikasi yang dijalankan secara langsung. Pada .NET, hasil build Class Library biasanya berupa file .dll.<\\/p><p>Kegunaan Class Library antara lain:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Menghindari penulisan kode yang sama berulang kali.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Memisahkan logic program dari aplikasi utama.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Membuat struktur project lebih rapi dan modular.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Mempermudah maintenance dan penggunaan kembali kode.<\\/li><\\/ol><p>Contohnya, PaymentLibrary dapat menyimpan kode pembayaran dan kemudian digunakan oleh Console App, Desktop App, atau project lain.<\\/p><h2>3.2 Contoh Isi Class Library<\\/h2><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"namespace PaymentLibrary\\n{\\n    public interface IPembayaran\\n    {\\n        void Bayar(decimal jumlah);\\n    }\\n\\n    public class TransferBank : IPembayaran\\n    {\\n        public void Bayar(decimal jumlah)\\n        {\\n            Console.WriteLine($\\\"Transfer {jumlah} melalui bank\\\");\\n        }\\n    }\\n}\\n\"},{\"type\":\"paragraf\",\"teks\":\"<p>Project lain yang sudah mereferensikan <code>PaymentLibrary<\\/code> cukup memanggil namespace dan class yang tersedia di dalam library tersebut.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using PaymentLibrary;\\n\\nclass Program\\n{\\n    static void Main()\\n    {\\n        TransferBank transfer = new TransferBank();\\n        transfer.Bayar(100000);\\n    }\\n}\\n\"},{\"type\":\"paragraf\",\"teks\":\"<h1>Membuat Class Library di Visual Studio<\\/h1><p>Contoh sederhana: PaymentLibrary sebagai Class Library dan PaymentConsole sebagai project yang menggunakannya.<\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buka Visual Studio, pilih Create a new project, lalu pilih Class Library (.NET).<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Beri nama project, misalnya PaymentLibrary.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Tambahkan class atau interface yang dibutuhkan, misalnya IPembayaran.cs dan TransferBank.cs.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik kanan PaymentLibrary \\u2192 build \\u2192 cek directory hasil.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pada Navigasi di atas, pilih File\\u2192 New \\u2192 Procect\\/Solution \\u2192 Console App, lalu beri nama PaymentConsole.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik kanan PaymentConsole \\u2192 Add \\u2192 Project Reference \\u2192 browse file .dll hasil build \\u2192 centang PaymentLibrary \\u2192 OK.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Di Program.cs, tambahkan using PaymentLibrary; lalu gunakan class dari library.<\\/li><\\/ol><p>Setelah Project Reference ditambahkan, PaymentConsole dapat menggunakan class public yang berada di PaymentLibrary. Ketika dibuild, Class Library akan menghasilkan file .dll.`<\\/p>\",\"align\":\"kiri\"},{\"type\":\"pembatas\",\"style\":\"garis\"},{\"type\":\"paragraf\",\"teks\":\"<h1>Ringkasan<\\/h1><table><tbody><tr><td data-row=\\\"1\\\" class=\\\"ql-align-center\\\">Konsep<\\/td><td data-row=\\\"1\\\" class=\\\"ql-align-center\\\">Fungsi<\\/td><\\/tr><tr><td data-row=\\\"2\\\" class=\\\"ql-align-center\\\">Abstraction<\\/td><td data-row=\\\"2\\\" class=\\\"ql-align-center\\\">Menyembunyikan detail implementasi dan menampilkan bagian penting.<\\/td><\\/tr><tr><td data-row=\\\"3\\\" class=\\\"ql-align-center\\\">Abstract Class<\\/td><td data-row=\\\"3\\\" class=\\\"ql-align-center\\\">Menjadi dasar untuk class turunannya.<\\/td><\\/tr><tr><td data-row=\\\"4\\\" class=\\\"ql-align-center\\\">Interface<\\/td><td data-row=\\\"4\\\" class=\\\"ql-align-center\\\">Memberikan aturan atau kontrak yang harus dipenuhi.<\\/td><\\/tr><tr><td data-row=\\\"5\\\" class=\\\"ql-align-center\\\">Class Library<\\/td><td data-row=\\\"5\\\" class=\\\"ql-align-center\\\">Menyimpan dan mengorganisasi kode agar dapat digunakan kembali.<\\/td><\\/tr><\\/tbody><\\/table><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"subbab\",\"judul\":\"Koneksi Database Berbasis OOP dengan C# dan PostgreSQL\",\"judul_idn\":null},{\"type\":\"subheading\",\"teks\":\"1. Persiapan\"},{\"type\":\"subheading3\",\"teks\":\"1.1 Buat Database dan Tabel\"},{\"type\":\"paragraf\",\"teks\":\"<p>Jalankan di pgAdmin (Query Tool) atau psql:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"sql\",\"kode\":\"CREATE DATABASE praktikum_db;\"},{\"type\":\"paragraf\",\"teks\":\"<p>Pilih database praktikum_db, lalu jalankan:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"sql\",\"kode\":\"CREATE TABLE mahasiswa (\\n    id SERIAL PRIMARY KEY,\\n    nim VARCHAR(10) NOT NULL UNIQUE,\\n    nama VARCHAR(100) NOT NULL,\\n    jurusan VARCHAR(50) NOT NULL\\n);\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>SERIAL membuat kolom id terisi otomatis.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>UNIQUE pada nim mencegah NIM yang sama masuk dua kali.<\\/li><\\/ol><p><br><\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"1.2 Buat Project di Visual Studio\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buka Visual Studio, pilih <strong>Create a new project<\\/strong>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pilih template <strong>Console App (C#)<\\/strong>, lalu klik <strong>Next<\\/strong>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Isi nama project <strong>PraktikumDb<\\/strong>, lalu klik <strong>Next<\\/strong>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pilih framework .NET yang terpasang (misalnya .NET 8), lalu klik <strong>Create<\\/strong>.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"1.3 Install Npgsql dengan NuGet\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Di Solution Explorer, klik kanan project <strong>PraktikumDb<\\/strong>, pilih <strong>Manage NuGet Packages....<\\/strong><\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buka tab <strong>Browse<\\/strong>, lalu ketik <strong>Npgsql <\\/strong>pada kolom pencarian.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pilih paket <strong>Npgsql<\\/strong>, lalu klik <strong>Install<\\/strong>.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik <strong>OK <\\/strong>pada jendela <strong>Preview Changes<\\/strong> dan <strong>I Accept pada License Acceptance<\\/strong>.<\\/li><\\/ol><p>Cara alternatif lewat <strong>Tools &gt; NuGet Package Manager &gt; Package Manager Console<\\/strong>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"bash\",\"kode\":\"Install-Package Npgsql\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Npgsql adalah driver agar C# dapat berkomunikasi dengan PostgreSQL.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pastikan Npgsql muncul di <strong>Dependencies &gt; Packages pada Solution Explorer<\\/strong>. Jika sudah muncul, instalasi berhasil.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"2. Class DatabaseConnection\"},{\"type\":\"paragraf\",\"teks\":\"<p>Komponen Npgsql yang dipakai:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Class\",\"Fungsi\"],\"rows\":[[\"NpgsqlConnection\\n\\n\",\"Membuka koneksi ke database\\n\"],[\"NpgsqlCommand\",\"Menjalankan perintah SQL\\n\"],[\"NpgsqlDataReader\",\"Membaca hasil SELECT baris per baris\"]],\"caption\":\"\"},{\"type\":\"paragraf\",\"teks\":\"<p>Tambahkan class baru: klik kanan project, pilih <strong>Add &gt; Class...<\\/strong>, beri nama <strong>DatabaseConnection.cs.<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using Npgsql;\\n\\npublic class DatabaseConnection\\n{\\n    private readonly string _connectionString;\\n\\n    public DatabaseConnection(string host, int port, string database, string username, string password)\\n    {\\n        _connectionString = $\\\"Host={host};Port={port};Database={database};Username={username};Password={password}\\\";\\n    }\\n\\n    public NpgsqlConnection CreateConnection()\\n    {\\n        return new NpgsqlConnection(_connectionString);\\n    }\\n\\n    public bool TestConnection()\\n    {\\n        try\\n        {\\n            using var conn = CreateConnection();\\n            conn.Open();\\n            return true;\\n        }\\n        catch (NpgsqlException ex)\\n        {\\n            Console.WriteLine($\\\"Gagal terhubung: {ex.Message}\\\");\\n            return false;\\n        }\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>_connectionString <\\/strong>bersifat <strong>private <\\/strong>(encapsulation), sehingga data koneksi tidak bisa diakses langsung dari luar class.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Port bawaan PostgreSQL adalah <strong>5432<\\/strong>. <strong>Sesuaikan <\\/strong>jika instalasi Anda berbeda.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>CreateConnection()<\\/strong> membuat objek koneksi baru setiap dipanggil.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span><strong>TestConnection()<\\/strong> mencoba membuka koneksi, lalu mengembalikan true jika berhasil dan false jika gagal.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>using var menutup koneksi otomatis setelah selesai dipakai.<\\/li><\\/ol><p>Uji koneksi di<strong> Program.cs<\\/strong>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"var db = new DatabaseConnection(\\\"localhost\\\", 5432, \\\"praktikum_db\\\", \\\"postgres\\\", \\\"password_anda\\\");\\n\\nif (db.TestConnection())\\n{\\n    Console.WriteLine(\\\"Koneksi berhasil!\\\");\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ganti <strong>password_anda <\\/strong>dengan password PostgreSQL masing-masing.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Jalankan dengan <strong>Ctrl + F5<\\/strong>. Jika tampil \\\"Koneksi berhasil!\\\", lanjut ke langkah berikutnya.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"3. Uji Query Dasar\"},{\"type\":\"paragraf\",\"teks\":\"<p>Buat class baru <strong>MahasiswaQuery.cs<\\/strong> untuk menampung query. Class ini menerima <strong>DatabaseConnection <\\/strong>lewat constructor.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"using Npgsql;\\n\\npublic class MahasiswaQuery\\n{\\n    private readonly DatabaseConnection _db;\\n\\n    public MahasiswaQuery(DatabaseConnection db)\\n    {\\n        _db = db;\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Koneksi dibuat di luar lalu dikirim ke class ini, sehingga satu <strong>DatabaseConnection <\\/strong>bisa dipakai oleh banyak class.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Method pada langkah 3.1 sampai 3.5 ditambahkan <strong>di dalam <\\/strong>class <strong>MahasiswaQuery<\\/strong>.<\\/li><\\/ol><p>Pola setiap query:<\\/p><p><strong>Buka koneksi, buat command, isi parameter, jalankan.<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"3.1 INSERT\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public void Insert(string nim, string nama, string jurusan)\\n{\\n    using var conn = _db.CreateConnection();\\n    conn.Open();\\n\\n    string sql = \\\"INSERT INTO mahasiswa (nim, nama, jurusan) VALUES (@nim, @nama, @jurusan)\\\";\\n    using var cmd = new NpgsqlCommand(sql, conn);\\n    cmd.Parameters.AddWithValue(\\\"nim\\\", nim);\\n    cmd.Parameters.AddWithValue(\\\"nama\\\", nama);\\n    cmd.Parameters.AddWithValue(\\\"jurusan\\\", jurusan);\\n\\n    int rows = cmd.ExecuteNonQuery();\\n    Console.WriteLine($\\\"{rows} data ditambahkan.\\\");\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>@nim, @nama, @jurusan adalah parameter. Nilainya diisi lewat Parameters.AddWithValue().<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Parameter wajib dipakai agar aman dari SQL Injection. Jangan menggabungkan input langsung ke string SQL.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>ExecuteNonQuery() dipakai untuk INSERT, UPDATE, dan DELETE. Nilai kembaliannya adalah jumlah baris yang terpengaruh.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"3.2 SELECT\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public void SelectAll()\\n{\\n    using var conn = _db.CreateConnection();\\n    conn.Open();\\n\\n    string sql = \\\"SELECT id, nim, nama, jurusan FROM mahasiswa ORDER BY id\\\";\\n    using var cmd = new NpgsqlCommand(sql, conn);\\n    using var reader = cmd.ExecuteReader();\\n\\n    while (reader.Read())\\n    {\\n        Console.WriteLine($\\\"{reader.GetInt32(0)} | {reader.GetString(1)} | {reader.GetString(2)} | {reader.GetString(3)}\\\");\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>ExecuteReader() dipakai untuk SELECT.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>reader.Read() maju ke baris berikutnya dan bernilai false jika data habis.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Angka pada GetString(1) adalah urutan kolom pada query SELECT (dimulai dari 0).<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"3.3 UPDATE\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public void Update(string nim, string namaBaru)\\n{\\n    using var conn = _db.CreateConnection();\\n    conn.Open();\\n\\n    string sql = \\\"UPDATE mahasiswa SET nama = @nama WHERE nim = @nim\\\";\\n    using var cmd = new NpgsqlCommand(sql, conn);\\n    cmd.Parameters.AddWithValue(\\\"nama\\\", namaBaru);\\n    cmd.Parameters.AddWithValue(\\\"nim\\\", nim);\\n\\n    int rows = cmd.ExecuteNonQuery();\\n    Console.WriteLine($\\\"{rows} data diubah.\\\");\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klausa WHERE menentukan data mana yang diubah. Tanpa WHERE, semua baris ikut berubah.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Jika NIM tidak ditemukan, hasilnya 0 data diubah.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"3.4 DELETE\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public void Delete(string nim)\\n{\\n    using var conn = _db.CreateConnection();\\n    conn.Open();\\n\\n    string sql = \\\"DELETE FROM mahasiswa WHERE nim = @nim\\\";\\n    using var cmd = new NpgsqlCommand(sql, conn);\\n    cmd.Parameters.AddWithValue(\\\"nim\\\", nim);\\n\\n    int rows = cmd.ExecuteNonQuery();\\n    Console.WriteLine($\\\"{rows} data dihapus.\\\");\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sama seperti UPDATE, selalu sertakan WHERE agar tidak menghapus seluruh data.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"3.5 COUNT (Satu Nilai)\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"public long Count()\\n{\\n    using var conn = _db.CreateConnection();\\n    conn.Open();\\n\\n    using var cmd = new NpgsqlCommand(\\\"SELECT COUNT(*) FROM mahasiswa\\\", conn);\\n    return (long)cmd.ExecuteScalar()!;\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>ExecuteScalar() dipakai jika hasil query hanya satu nilai, misalnya COUNT.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>COUNT(*) di PostgreSQL bertipe bigint, sehingga dikonversi ke long.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"4. Menjalankan Program\"},{\"type\":\"paragraf\",\"teks\":\"<p>Edit <strong>Program.cs<\\/strong>:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"csharp\",\"kode\":\"var db = new DatabaseConnection(\\\"localhost\\\", 5432, \\\"praktikum_db\\\", \\\"postgres\\\", \\\"password_anda\\\");\\n\\nif (!db.TestConnection())\\n{\\n    return;\\n}\\n\\nConsole.WriteLine(\\\"Koneksi berhasil!\\\");\\n\\nvar query = new MahasiswaQuery(db);\\n\\nquery.Insert(\\\"2024001\\\", \\\"Budi\\\", \\\"Informatika\\\");\\nquery.Insert(\\\"2024002\\\", \\\"Sari\\\", \\\"Sistem Informasi\\\");\\nquery.SelectAll();\\n\\nquery.Update(\\\"2024001\\\", \\\"Budi Santoso\\\");\\nquery.SelectAll();\\n\\nquery.Delete(\\\"2024002\\\");\\nquery.SelectAll();\\n\\nConsole.WriteLine($\\\"Jumlah data: {query.Count()}\\\");\"},{\"type\":\"paragraf\",\"teks\":\"<p>Keterangan:<\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Program berhenti jika koneksi gagal, dan hanya lanjut jika koneksi berhasil.<\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Jalankan dengan <strong>Ctrl + F5<\\/strong>, lalu cocokkan hasilnya dengan tabel mahasiswa di pgAdmin.<\\/li><\\/ol><p>Contoh output:<\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"bash\",\"kode\":\"Koneksi berhasil!\\n1 data ditambahkan.\\n1 data ditambahkan.\\n1 | 2024001 | Budi | Informatika\\n2 | 2024002 | Sari | Sistem Informasi\\n1 data diubah.\\n1 | 2024001 | Budi Santoso | Informatika\\n2 | 2024002 | Sari | Sistem Informasi\\n1 data dihapus.\\n1 | 2024001 | Budi Santoso | Informatika\\nJumlah data: 1\"},{\"type\":\"paragraf\",\"teks\":\"<p><em>Jika program dijalankan dua kali, Insert gagal karena NIM 2024001 sudah ada. Kosongkan tabel dulu dengan DELETE FROM mahasiswa; di pgAdmin.<\\/em><\\/p><p><strong>Error Umum<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"tabel\",\"headers\":[\"Pesan error\",\"Penyebab\",\"Solusi\"],\"rows\":[[\"password authentication failed\",\"Password salah\",\"Periksa password user postgres\"],[\"Failed to connect \\/ connection refused\",\"Service PostgreSQL mati atau port salah\",\"Jalankan service PostgreSQL, cek port\"],[\"relation \\\"mahasiswa\\\" does not exist\",\"Tabel belum dibuat di database tersebut\",\"Jalankan CREATE TABLE di praktikum_db\"],[\"duplicate key value violates unique constraint\",\"NIM sudah ada\",\"Ganti NIM atau hapus data lama\"],[\"database \\\"...\\\" does not exist\",\"Nama database salah\",\"Samakan dengan nama di pgAdmin\"]],\"caption\":\"\"},{\"type\":\"subbab\",\"judul\":\"Winform GUI, OOP, dan Event\",\"judul_idn\":null},{\"type\":\"subheading\",\"teks\":\"Definisi Windows Forms\"},{\"type\":\"paragraf\",\"teks\":\"<p>Windows Forms (WinForms) merupakan kerangka kerja (framework) berbasis GUI (Graphical User Interface) yang menjadi bagian dari .NET dan digunakan untuk membangun aplikasi desktop pada sistem operasi Windows. WinForms menyediakan berbagai komponen antarmuka yang dapat digunakan untuk membuat aplikasi dengan lebih mudah, seperti tombol, label, kotak input, tabel, dan komponen lainnya.<\\/p><p>Dalam pengembangannya, WinForms memungkinkan programmer merancang tampilan aplikasi menggunakan metode drag-and-drop melalui Visual Studio. Programmer dapat menempatkan komponen pada Form, mengatur tampilannya melalui jendela Properties, kemudian menambahkan kode C# untuk mengatur perilaku aplikasi.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Keunggulan dan Kelemahan Winforms\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Keunggulan Winform<\\/strong><\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Memungkinkan pembuatan prototipe dan aplikasi sederhana secara cepat melalui fitur drag-and-drop di Visual Studio.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Relatif mudah dipelajari oleh pemula karena antarmuka dapat dirancang secara visual tanpa harus menulis seluruh kode UI secara manual.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Telah digunakan sejak lama sehingga memiliki dokumentasi yang melimpah, banyak contoh program, dan referensi penyelesaian masalah.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Cocok untuk aplikasi perkantoran sederhana dan pengelolaan data yang tidak membutuhkan pemrosesan grafis intensif.<\\/li><\\/ol><p><strong>Kelemahan WinForms<\\/strong><\\/p><ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Membutuhkan usaha tambahan untuk membuat tampilan modern, transparansi, dan animasi kompleks seperti pada aplikasi modern.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Membutuhkan konfigurasi yang tepat agar ukuran dan posisi komponen tetap sesuai pada layar dengan resolusi serta skala DPI yang berbeda.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>WinForms menggunakan sistem gambar dan kontrol Windows yang secara tradisional banyak mengandalkan GDI\\/GDI+. Oleh karena itu, WinForms kurang ideal untuk aplikasi yang membutuhkan animasi atau pemrosesan grafis kompleks.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Komponen Penting Dalam WinForms\"},{\"type\":\"tabel\",\"headers\":[\"Komponen\",\"Keterangan\"],\"rows\":[[\"Form\",\"Jendela utama aplikasi. Semua komponen lain diletakkan di sini.\"],[\"Label\",\"Digunakan untuk menampilkan teks keterangan (instruksi) yang tidak bisa diubah oleh user.\"],[\"TextBox\",\"Digunakan sebagai tempat bagi pengguna untuk memasukkan teks, seperti nama, email, atau kata sandi.\"],[\"Button\",\"Digunakan untuk memicu suatu aksi ketika diklik, seperti menyimpan data atau menjalankan proses login.\"],[\"ComboBox\",\"Digunakan untuk menampilkan daftar pilihan dalam bentuk menu drop-down, sehingga pengguna dapat memilih salah satu opsi yang tersedia.\"],[\"DataGridView\",\"Digunakan untuk menampilkan data dalam bentuk tabel yang terdiri atas baris dan kolom, misalnya data yang berasal dari database.\"],[\"CheckBox\",\"Digunakan untuk memilih satu atau beberapa opsi sekaligus, seperti memilih hobi atau fitur tertentu.\"],[\"RadioButton\",\"Digunakan untuk memilih satu opsi dari beberapa pilihan yang tersedia dalam satu kelompok, seperti memilih jenis kelamin.\"],[\"PictureBox\",\"Digunakan untuk menampilkan gambar, seperti foto, logo, atau ilustrasi, dalam aplikasi.\"],[\"Panel\",\"Digunakan sebagai wadah (container) untuk mengelompokkan komponen-komponen antarmuka agar tata letak aplikasi lebih rapi dan terstruktur.\"]],\"caption\":\"\"},{\"type\":\"subheading\",\"teks\":\"Waktunya Praktik Wak !!!\"},{\"type\":\"paragraf\",\"teks\":\"<p>Disini kita akan mencoba untuk membuat tampilan halaman login dari awal sampai akhir. Lets goo!!!<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"A. Membuat Project Baru\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buka Visual Studio.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pilih Create a new project.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pilih template Windows Forms App (.NET Framework).<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik Next, beri nama project misalnya LoginFormApp.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pilih lokasi penyimpanan, lalu klik Create.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792048864\\/portfolio\\/courses\\/phpbbvibpc3gka2eTmVSAW_r4j7j1.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading3\",\"teks\":\"B. Mengubah Background Form Utama\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik form utama di designer.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik kanan pada form, Buka Properties \\u2192 cari BackgroundImage.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik, pilih gambar background (jika belum ada, import dulu). <\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Set BackgroundImageLayout menjadi Stretch agar memenuhi form. <\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792049370\\/portfolio\\/courses\\/phpe9ha4f2te1538YTqh2O_imvf7c.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792049864\\/portfolio\\/courses\\/phpq77c3s1jpvoh9SdI661_yvybwc.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792049993\\/portfolio\\/courses\\/php4ljefjl77sfoaGqCsir_eukjbb.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792050156\\/portfolio\\/courses\\/phpuhgmgefrvcg994F0umO_wbm5wu.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading3\",\"teks\":\"C. Menambahkan Panel untuk Login Form\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Buka menu Toolbox, lalu pilih Panel. <\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Drag ke form, letakkan kira-kira di tengah.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Atur ukuran panel sesuai kebutuhan (misalnya 300x400 px).<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sesuaikan posisi agar di tengah form (Anda bisa atur properti Location).<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792050355\\/portfolio\\/courses\\/phprc1e7dbdv0rh4IBWFoQ_pqhdm0.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792050579\\/portfolio\\/courses\\/phpnb2le87pjso75p3gI5v_tf3544.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading3\",\"teks\":\"D. Menambahkan Gambar Logo di Panel\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Dari Toolbox, pilih PictureBox.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Letakkan di dalam panel, letakkan di bagian atas tengah.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Di Properties \\u2192 klik BackgroundImage \\u2192 pilih logo (import jika belum ada).<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Atur BackgroundImageLayout menjadi Zoom agar gambar pas.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792050919\\/portfolio\\/courses\\/php8pmju5o9pfrt6TviSVY_x1ke0y.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792051040\\/portfolio\\/courses\\/php4fk0k943kugtazPUn5V_phedkr.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading3\",\"teks\":\"E. Menambahkan Label Judul \\\"FORM LOGIN\\\"\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Dari Toolbox, pilih Label.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Letakkan di bawah PictureBox dalam panel.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Di Properties, ubah Text menjadi \\\"FORM LOGIN\\\".<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sesuaikan font, misalnya ukuran 14, style bold.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Set alignment menjadi center (opsional).<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792063747\\/portfolio\\/courses\\/php0vp1pgs88dhs4IAs8gu_din7ys.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792063759\\/portfolio\\/courses\\/php7fi4h2b7mpgl7BsJaj1_vkjwx9.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792063773\\/portfolio\\/courses\\/phpahn1id1dp4ar9idOB50_btknrg.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading3\",\"teks\":\"F. Menambahkan Label dan TextBox untuk Username\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Cari Toolbox, pilih Label, letakkan di panel tepat di bawah judul.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ubah text menjadi \\\"Username\\\".<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pilih TextBox dari toolbox, letakkan di bawah label Username.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Set nama properti TextBox menjadi TbUsername.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792064187\\/portfolio\\/courses\\/php36tc1141117d6lPxz2K_xptjlu.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792064198\\/portfolio\\/courses\\/phpa2ucuv1j4efi3nFFZ9G_pzrxiz.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading3\",\"teks\":\"G. Menambahkan Label dan TextBox untuk Password\"},{\"type\":\"paragraf\",\"teks\":\"\",\"align\":\"kiri\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ulangi langkah seperti untuk Username:<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Label dengan text \\\"Password\\\".<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>TextBox, di properti beri nama TbPassword.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Di properti TextBox, ubah UseSystemPasswordChar menjadi True agar teks tersamarkan.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792064399\\/portfolio\\/courses\\/phplgf18grj4horeM8dO9w_pp20ji.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792064410\\/portfolio\\/courses\\/php37e8bi1j1jvncHxHsL7_i4rdpr.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading3\",\"teks\":\"H. Menambahkan Button Login\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Dari Toolbox, pilih Button.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Letakkan di bawah textbox Password.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ubah properti:<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Name menjadi BtnLogin<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Text menjadi \\\"Login\\\"<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>BackColor menjadi hijau (misalnya Color.Green)<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>ForeColor menjadi putih agar tulisan terlihat.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792064689\\/portfolio\\/courses\\/php1fti2ef7ki3b337YlY8_nd2obd.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792064698\\/portfolio\\/courses\\/phpliqje06k1f0r3CpXWEr_i1pcj3.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792064710\\/portfolio\\/courses\\/phph9mugcd96ltr81ueswe_jw0yo0.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792064725\\/portfolio\\/courses\\/phptde1e7um4t020PNNWdp_ohcxv7.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading3\",\"teks\":\"I. Membuat Form Setelah Login\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik Kanan pada Project C# Windows Forms<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pilih Add -&gt; Form (Windows Forms)<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Beri nama \\\"FormDashboard\\\"<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Sesuaikan tampilan seperti pada Form Login<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Beri label dengan nama LabelDashboard dan text nya menjadi Selamat Datang.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792065720\\/portfolio\\/courses\\/phpcquug4ar5ha5f2vRqBz_slpdpo.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792065739\\/portfolio\\/courses\\/phpcfg9633rvghe3ne5bwO_f7jhai.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading\",\"teks\":\"Menyusun Halaman Login\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Klik 2 kali pada button login untuk otomatis membuat sebuah event handler click.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1792078281\\/portfolio\\/courses\\/phpeskv7g41nd609f5xyd0_kt0mbm.webp\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Pada Function tersebut, kita akan mengambil value yang diinputkan oleh user dari masing masing textbox dan menyimpannya ke dalam variabel. Sebelum itu kita juga akan menentukan username dan juga password terlebih dahulu.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"public partial class Form1 : Form\\n{\\n    private string username;\\n    private string password;\\n    public Form1()\\n    {\\n        InitializeComponent();\\n        username = \\\"ahmad\\\";\\n        password = \\\"ahmad123\\\";\\n    }\\n\\n    private void Form1_Load(object sender, EventArgs e)\\n    {\\n        pictureBox1.BackColor = Color.Transparent;\\n        \\n    }\\n\\n\\n    private void BtnLogin_Click(object sender, EventArgs e)\\n    {\\n        string usernameInput = TbUsername.Text;\\n        string passwordInput = TbPassword.Text;\\n\\n    }\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Kemudian kita akan menggunakan percabangan untuk menyamakan username dan password yang di inputkan user terhadap username dan password yang telah dibuat. dan kita beri messagebox untuk penanda berhasil atau tidaknya.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"string usernameInput = TbUsername.Text;\\nstring passwordInput = TbPassword.Text;\\n\\nif (usernameInput == username && passwordInput == password)\\n{\\n    MessageBox.Show(\\\"Login Berhasil\\\", \\\"success\\\", MessageBoxButtons.OK, MessageBoxIcon.Information );\\n} \\nelse\\n{\\n    MessageBox.Show(\\\"Username Atau Password Salah\\\", \\\"Gagal\\\", MessageBoxButtons.OK, MessageBoxIcon.Error);\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Arahkan Ke FormDashboard ketika login Berhasil<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"if (usernameInput == username && passwordInput == password)\\n{\\n    MessageBox.Show(\\\"Login Berhasil\\\", \\\"success\\\", MessageBoxButtons.OK, MessageBoxIcon.Information );\\n\\n     \\/\\/ ini penambahan\\n FormDashboard formDashboard = new FormDashboard();\\n formDashboard.Show();\\n this.Hide();\\n} \\nelse\\n{\\n    MessageBox.Show(\\\"Username Atau Password Salah\\\", \\\"Gagal\\\", MessageBoxButtons.OK, MessageBoxIcon.Error);\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Tambahkan attribut username pada FormDashboard sehingga kita bisa memberikan value username dari FormLogin ke FormDashboard melalui Constructor. Dan username tersebut akan kita tampilkan pada labelDashboard.<\\/li><\\/ol><p><strong>FormDashboard.cs<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"public partial class FormDashboard : Form\\n{\\n     private string username;\\n     public FormDashboard(string username)\\n     {\\n          InitializeComponent();\\n          this.username = username;\\n          LabelDashboard.Text += this.username;\\n     }\\n\\n\\n}\"},{\"type\":\"paragraf\",\"teks\":\"<p><strong>Form1.cs<\\/strong><\\/p>\",\"align\":\"kiri\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\\/\\/ ini penambahan\\nFormDashboard formDashboard = new FormDashboard(usernameInput);\\nformDashboard.Show();\\nthis.Hide();\"},{\"type\":\"subheading\",\"teks\":\"Percobaan Menampilkan Data Dalam DataGridView \"},{\"type\":\"subheading3\",\"teks\":\"A. Menambahkan DataGridView\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Dari Toolbox, pilih DataGridView.<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Letakkan pada FormDashboard<\\/li><li data-list=\\\"ordered\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Ubah nama pada properti menjadi DgUser<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading3\",\"teks\":\"B. Buat Class User dalam file Baru yaitu User.Cs\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"public class User\\n{\\n    public string nama { get; set; }\\n    public int umur{ get; set; }\\n    public string asal { get; set; }\\n\\n    public User(string nama, int umur, string asal)\\n    {\\n        this.nama = nama;\\n        this.umur = umur;\\n        this.asal = asal;\\n    }\\n}\"},{\"type\":\"subheading3\",\"teks\":\"C. Buat Sebuah List bertipe User, dan buat Sebuah Method Untuk Mengenerate Value dari list tersebut di dalam form dashboard\"},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\" public partial class FormDashboard : Form\\n {\\n     private string username;\\n     private List<User> listUser;\\n     public FormDashboard(string username)\\n     {\\n         InitializeComponent();\\n         this.username = username;\\n         LabelDashboard.Text += $\\\" {this.username}\\\";\\n         this.listUser = generateData();\\n         DgUser.DataSource = listUser;\\n     }\\n\\n     public List<User> generateData()\\n     {\\n         List<User> listUser = new List<User>();\\n         for (int i = 0; i  < 5; i++)\\n         {\\n             User user = new User($\\\"Ahmad {i}\\\", 20, \\\"Bwi\\\");\\n             listUser.Add(user);\\n         }\\n         return listUser;\\n     }\\n }\"}]');
INSERT INTO `courses` (`id`, `slug`, `nama`, `nama_idn`, `desk`, `desk_idn`, `gambar`, `sort_order`, `created_at`, `updated_at`, `konten`) VALUES
(3, 'algoritma-pemrograman', 'Algoritma & Pemrograman', NULL, 'Pemahaman Dasar algoritma dan pemrograman menggunakan bahasa Python', NULL, 'https://res.cloudinary.com/droanqrew/image/upload/v1787413271/portfolio/courses/phpfhsca3a90l2hevmRjUW_y2sthj.webp', 3, '2026-08-22 08:41:11', '2026-10-01 04:48:11', '[{\"type\":\"subbab\",\"judul\":\"Pengenalan Bahasa Pemrograman\",\"judul_idn\":null},{\"type\":\"subheading\",\"teks\":\"Pengertian\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\"><strong>Bahasa pemrograman <\\/strong>adalah sistem formal yang digunakan untuk menulis program komputer. Program ini berisi instruksi yang memberi tahu komputer apa yang harus dilakukan. Bahasa pemrograman memungkinkan pengembang perangkat lunak untuk mengontrol perangkat keras komputer dan membuat aplikasi yang menjalankan berbagai fungsi.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Jenis\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Compiler adalah program yang mengubah seluruh kode sumber (source code) kamu jadi file program baru (biasanya file .exe atau .class) sebelum aplikasi dijalankan. Jadi, kode yang ditulis, dicompile, lalu jalankan hasilnya. Contohnya: C, C++, dan Java (walau Java juga pakai interpreter di tahap selanjutnya).<\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Interpreter adalah membaca dan menjalankan kode langsung baris demi baris tanpa membuat file program baru. Jadi, setiap kali menjalankan program, interpreter akan \\u201cmenerjemahkan\\u201d kode secara langsung. Contohnya: Python.<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"gambar\",\"url\":\"https:\\/\\/res.cloudinary.com\\/droanqrew\\/image\\/upload\\/v1787430375\\/portfolio\\/courses\\/gslbu7uxvvrla8aahg5g.svg\",\"caption\":\"\",\"ukuran\":\"penuh\"},{\"type\":\"subheading\",\"teks\":\"Sejarah Python\"},{\"type\":\"paragraf\",\"teks\":\"<p class=\\\"ql-align-justify\\\">Bahasa pemrograman Python diciptakan oleh Guido van Rossum pada akhir tahun 1980-an di pusat penelitian CWI, Belanda. Dirilis pertama kali pada tahun 1991, nama \\\"Python\\\" diambil dari acara komedi favorit pembuatnya yaitu Monty Python\'s Flying Circus, bukan dari nama ular.<\\/p>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Alasan Menggunakan Python\"},{\"type\":\"paragraf\",\"teks\":\"<ol><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Syntax yang mudah dipelajari<\\/li><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Kemampuan untuk Prototyping Cepat<\\/li><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Fleksibilitas dan Versatilitas<\\/li><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Kemudahan Integrasi<\\/li><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Kinerja yang Baik untuk Banyak Tugas<\\/li><li data-list=\\\"ordered\\\" class=\\\"ql-align-justify\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\/span>Library yang Luas<\\/li><\\/ol>\",\"align\":\"kiri\"},{\"type\":\"subheading\",\"teks\":\"Persiapan Awal\"},{\"type\":\"link\",\"href\":\"https:\\/\\/code.visualstudio.com\\/\",\"label\":\"Visual Studio Code\",\"desc\":\"Text Editor\"},{\"type\":\"link\",\"href\":\"https:\\/\\/www.python.org\\/downloads\\/\",\"label\":\"Python\",\"desc\":\"Program Python\"},{\"type\":\"subbab\",\"judul\":\"Subbab 2\",\"judul_idn\":null},{\"type\":\"kode\",\"bahasa\":\"php\",\"kode\":\"\"},{\"type\":\"subheading\",\"teks\":\"\"}]');

