INSERT INTO `experiences` (`id`, `slug`, `role`, `role_idn`, `company`, `duration`, `location`, `desk`, `desk_idn`, `practicum_desc`, `practicum_desc_idn`, `gambar`, `konten`, `responsibilities`, `responsibilities_idn`, `skills`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'external-relations-staff', 'External Relations Staff', 'Staf Eksternal', 'BEM FASILKOM UNEJ', 'Dec 2025 - Present', 'Faculty of Computer Science, University of Jember', 'Joined as a member of the External Affairs Division (External Subdivision) in the Student Executive Board (BEM). Focused on managing external relations, inter-organizational collaboration, and building strategic communication with both internal and external campus stakeholders. Actively contributed to strengthening the organization\\u2019s public image, expanding student networks, and supporting the development of sustainable partnerships to enhance the implementation of BEM FASILKOM UNEJ programs.', 'Bergabung sebagai anggota Divisi Hubungan Eksternal (Subdivisi Eksternal) di Badan Eksekutif Mahasiswa (BEM). Berfokus pada pengelolaan hubungan eksternal, kolaborasi antar organisasi, dan membangun komunikasi strategis dengan pemangku kepentingan internal dan eksternal kampus. Secara aktif berkontribusi dalam memperkuat citra publik organisasi, memperluas jaringan mahasiswa, dan mendukung pengembangan kemitraan berkelanjutan untuk meningkatkan implementasi program BEM FASILKOM UNEJ.', NULL, NULL, 'https://res.cloudinary.com/droanqrew/image/upload/v1786954821/portfolio/experiences/phpe39ghee8rv5h5t7Y9qC_adlkcf.webp', NULL, '[]', '[]', '[\"Public Relations\",\"Teamwork\",\"Strategic Communication\",\"Collaboration\"]', 1, '2026-08-11 23:34:02', '2026-08-25 10:13:48'),
(2, 'laboratory-teaching-assistant', 'Laboratory Teaching Assistant', 'Asisten Praktikum Laboratorium', 'Software Engineering Laboratory (Ryper Lab)', 'May 2025 - Present', 'Faculty of Computer Science, University of Jember', 'Ryper Lab is a research laboratory under the Faculty of Computer Science, University of Jember, focusing on the analysis, design, development, and implementation of software solutions. The laboratory supports innovation and technology-driven research to deliver efficient and sustainable software products.', 'Ryper Lab adalah laboratorium riset di bawah Fakultas Ilmu Komputer, Universitas Jember, yang berfokus pada analisis, desain, pengembangan, dan implementasi solusi perangkat lunak. Laboratorium ini mendukung inovasi dan riset berbasis teknologi untuk menghasilkan produk perangkat lunak yang efisien dan berkelanjutan.', 'I am involved as a Teaching Assistant (Practicum) under Ryper Lab, responsible for supporting practicum sessions for courses managed by the lab, specifically Algorithms & Programming and Database Systems. In this role, I guide students during practicum sessions, explain core concepts related to algorithms, programming logic, and database concepts, assist with programming exercises and database implementation, and ensure that all practicum activities run effectively in accordance with the curriculum.', 'Saya terlibat sebagai Asisten Pengajar (Praktikum) di bawah Ryper Lab, bertanggung jawab untuk mendukung sesi praktikum untuk mata kuliah yang dikelola oleh lab, khususnya Algoritma & Pemrograman dan Sistem Basis Data. Dalam peran ini, saya membimbing mahasiswa selama sesi praktikum, menjelaskan konsep inti yang berkaitan dengan algoritma, logika pemrograman, dan konsep basis data, membantu dengan latihan pemrograman dan implementasi basis data, serta memastikan bahwa semua kegiatan praktikum berjalan efektif sesuai dengan kurikulum.', 'https://res.cloudinary.com/droanqrew/image/upload/v1791694144/portfolio/experiences/phpnjl28acrra178fOxPQo_muxn1c.webp', NULL, '[]', '[]', '[\"Python\",\"Algorithms & Programming\",\"Database Systems\",\"Leadership\",\"Mentoring\"]', 2, '2026-08-11 23:34:02', '2026-10-10 21:49:04'),
(3, 'division-programming-staff', 'Division Programming Staff', 'Staf Pemrograman', 'UKM Linux and Open Source (UKM LAOS)', 'Dec 2024 - Dec 2025', 'Faculty of Computer Science, University of Jember', 'As a member of the Programming Division at UKM LAOS, I actively contributed to learning and development activities focused on open-source technologies, software development, and collaborative programming. This role enhanced my technical skills, problem-solving abilities, and experience working in a collaborative, team-oriented environment.', 'Sebagai anggota Divisi Pemrograman di UKM LAOS, saya secara aktif berkontribusi pada kegiatan pembelajaran dan pengembangan yang berfokus pada teknologi sumber terbuka, pengembangan perangkat lunak, dan pemrograman kolaboratif. Peran ini meningkatkan keterampilan teknis, kemampuan pemecahan masalah, dan pengalaman saya dalam bekerja di lingkungan yang kolaboratif dan berorientasi tim.', NULL, NULL, 'https://res.cloudinary.com/droanqrew/image/upload/v1786954848/portfolio/experiences/phpfsve35h09elq3xWtCmD_wrfeu4.webp', NULL, '[\"Participated in internal training sessions and workshops related to programming, open-source tools, and Linux-based development.\",\"Collaborated with team members to develop small- to medium-scale projects applying open-source principles and clean coding practices.\",\"Assisted in mentoring junior members by sharing knowledge on programming fundamentals and the use of open-source software.\",\"Took part in technical discussions, code reviews, and problem-solving activities within the division.\",\"Supported organizational activities such as coding classes, software installfests, and technical seminars.\"]', '[\"Berpartisipasi dalam sesi pelatihan internal dan lokakarya terkait pemrograman, alat sumber terbuka, dan pengembangan berbasis Linux.\",\"Berkolaborasi dengan anggota tim untuk mengembangkan proyek skala kecil hingga menengah yang menerapkan prinsip-prinsip sumber terbuka dan praktik pengkodean yang bersih.\",\"Membantu membimbing anggota junior dengan berbagi pengetahuan tentang dasar-dasar pemrograman dan penggunaan perangkat lunak sumber terbuka.\",\"Berpartisipasi dalam diskusi teknis, tinjauan kode, dan aktivitas pemecahan masalah di dalam divisi.\",\"Mendukung kegiatan organisasi seperti kelas pengkodean, instalasi perangkat lunak, dan seminar teknis.\"]', '[\"Python\",\"JavaScript\",\"Tailwind CSS\",\"Bootstrap\",\"React JS\",\"Git & Version Control\",\"Teamwork\",\"Collaboration\"]', 3, '2026-08-11 23:34:02', '2026-08-25 10:11:02'),
(4, 'technical-staff', 'Technical Staff', 'Staf Teknis', 'SMAGI TV', 'Jan 2022 - Jan 2023', 'SMAN 1 Giri, Banyuwangi', 'As an IT Staff member at SMAGI TV, I supported the school\\u2019s media and technology activities, particularly in digital content management and official website maintenance. Over the course of one year, I managed the content publication workflow and ensured that the website remained functional, up to date, and easily accessible.', 'Sebagai anggota Staf TI di SMAGI TV, saya mendukung kegiatan media dan teknologi sekolah, khususnya dalam manajemen konten digital dan pemeliharaan situs web resmi. Selama satu tahun, saya mengelola alur kerja publikasi konten dan memastikan bahwa situs web tetap berfungsi, mutakhir, dan mudah diakses.', NULL, NULL, 'https://res.cloudinary.com/droanqrew/image/upload/v1791694187/portfolio/experiences/phph08qjs2le1ttco2TKSZ_ra38fx.webp', NULL, '[\"Managed the uploading and publishing process of video content on the SMAGI TV channel, including quality checks, scheduling, and metadata optimization.\",\"Performed website maintenance through regular content updates for the SMAGI TV website.\",\"Handled and resolved technical issues related to content uploads and website functionality.\",\"Collaborated with creative and multimedia teams in preparing and publishing content according to release standards.\",\"Created documentation and helped streamline the content publication workflow.\"]', '[\"Mengelola proses pengunggahan dan penerbitan konten video di saluran TV SMAGI, termasuk pengecekan kualitas, penjadwalan, dan optimasi metadata.\",\"Melakukan pemeliharaan situs web melalui pembaruan konten secara berkala untuk situs web TV SMAGI.\",\"Menangani dan menyelesaikan masalah teknis terkait pengunggahan konten dan fungsionalitas situs web.\",\"Berkolaborasi dengan tim kreatif dan multimedia dalam mempersiapkan dan menerbitkan konten sesuai dengan standar rilis.\",\"Membuat dokumentasi dan membantu menyederhanakan alur kerja penerbitan konten.\"]', '[\"Communication\",\"Web Development\",\"Website Maintenance\",\"Digital Content Management\",\"Troubleshooting\"]', 4, '2026-08-11 23:34:02', '2026-10-10 21:49:47');

