INSERT INTO `projects` (`id`, `slug`, `nama`, `desk`, `desk_idn`, `full_desk`, `full_desk_idn`, `link`, `link_live`, `tools`, `fitur`, `fitur_idn`, `category_id`, `gambar`, `konten`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'agris', 'Agris', 'E-commerce and partnership platform for agriculture built with Laravel 13 and Tailwind CSS v4 partner project of PT Surya Agrifarm Kencana Patrang.', 'Platform e-commerce dan kemitraan untuk pertanian yang dibangun dengan Laravel 13 dan Tailwind CSS v4 proyek mitra PT Surya Agrifarm Kencana Patrang.', 'AGRIS is a modern agroindustrial e-commerce and partnership platform connecting agricultural producers with distribution partners (agents). Built with Laravel 13 and Tailwind CSS v4, it integrates Midtrans, Biteship, Wilayah.id, and Google OAuth to deliver a secure, automated, and real-time shopping, logistics, and digital payment experience.', 'AGRIS adalah platform e-commerce dan kemitraan agroindustri modern yang menghubungkan produsen pertanian dengan mitra distribusi (agen). Dibangun dengan Laravel 13 dan Tailwind CSS v4, platform ini mengintegrasikan Midtrans, Biteship, Wilayah.id, dan Google OAuth untuk memberikan pengalaman belanja, logistik, dan pembayaran digital yang aman, otomatis, dan real-time.', 'https://github.com/Adya30/Agris', 'https://agris.up.railway.app/', '[\"5\",\"14\",\"22\",\"15\",\"16\"]', '[\"Admin & Agent Partnerships\",\"Midtrans Payment Gateway\",\"Biteship Logistics Integration\",\"Google OAuth & OTP Verification\",\"Wilayah.id Administrative Subdivisions\"]', '[\"Kemitraan Admin & Agen\",\"Gerbang Pembayaran Midtrans\",\"Integrasi Logistik Biteship\",\"Verifikasi Google OAuth & OTP\",\"Subdivisi Administratif Wilayah.id\"]', 4, 'https://res.cloudinary.com/droanqrew/image/upload/v1787533402/portfolio/projects/phpirgdr4oaa0it0b9oznR_wkzl8x.webp', '[]', 1, '2026-08-11 23:34:02', '2026-10-12 09:18:14'),
(2, 'handman', 'Handman', 'Office task management and collaboration platform with real-time tracking and scheduling Citra Husada.', 'Platform manajemen tugas kantor dan kolaborasi dengan pelacakan dan penjadwalan waktu nyata di PT. Citra Husada.', 'HANDMAN is an office task management and company internal collaboration platform designed to improve team workflow efficiency. Featuring Admin, Manager, and Staff roles, the app supports real-time task delegation, operational issue ticketing, interactive work agendas, and dynamic PDF report exports with filters.', 'HANDMAN adalah platform manajemen tugas kantor dan kolaborasi internal perusahaan yang dirancang untuk meningkatkan efisiensi alur kerja tim. Menampilkan peran Admin, Manajer, dan Staf, aplikasi ini mendukung delegasi tugas secara real-time, pembuatan tiket masalah operasional, agenda kerja interaktif, dan ekspor laporan PDF dinamis dengan filter.', 'https://github.com/Adya30/HANDMAN', 'https://handman-production.up.railway.app/', '[\"5\",\"14\",\"22\",\"15\",\"16\"]', '[\"Real-Time Task Delegation\",\"Work Agenda Calendar\",\"Issue Ticketing System\",\"Filtered PDF Report Export\",\"Role Based Access Control\"]', '[\"Delegasi Tugas Waktu Nyata\",\"Kalender Agenda Kerja\",\"Sistem Tiket Masalah\",\"Ekspor Laporan PDF yang Difilter\",\"Kontrol Akses Berbasis Peran\"]', 4, 'https://res.cloudinary.com/droanqrew/image/upload/v1787533598/portfolio/projects/phpa7p9uhobtnooazAtjcU_yzozba.webp', NULL, 2, '2026-08-11 23:34:02', '2026-08-25 10:05:35'),
(3, 'kasirku', 'Kasirku', 'Web based cashier/POS (Point of Sale) system for managing sales transactions and inventory.', 'Sistem kasir/POS (Point of Sale) berbasis web untuk mengelola transaksi penjualan dan inventaris.', 'Kasirku is a web-based cashier and Point of Sale (POS) system built using Laravel, PHP, and MySQL. It helps small businesses manage sales transactions, track product inventory, and generate digital transaction records in real-time.', 'Deskripsi Lengkap (Bahasa Inggris)\r\nKasirku adalah sistem kasir dan Point of Sale (POS) berbasis web yang dibangun menggunakan Laravel, PHP, dan MySQL. Sistem ini membantu bisnis kecil mengelola transaksi penjualan, melacak inventaris produk, dan menghasilkan catatan transaksi digital secara real-time.', 'https://github.com/Adya30/Kasirku', 'https://kasir-barcode.up.railway.app/', '[\"5\",\"14\",\"22\",\"15\",\"16\"]', '[\"Point of Sale (POS)\",\"Inventory Management\",\"Transaction History\",\"Realtime Calculation\"]', '[\"Sistem Point of Sale (POS)\",\"Manajemen Inventaris\",\"Riwayat Transaksi\",\"Perhitungan Realtime\"]', 4, 'https://res.cloudinary.com/droanqrew/image/upload/v1787533692/portfolio/projects/phpfiqn5tpl2e50ce8y5ib_nvv1cb.webp', NULL, 3, '2026-08-11 23:34:02', '2026-08-25 10:03:12'),
(4, 'tanamin', 'Tanamin', 'Agriculture and plant growth monitoring platform developed with C#, .NET, and PostgreSQL.', 'Platform pemantauan pertanian dan pertumbuhan tanaman yang dikembangkan dengan C#, .NET, dan PostgreSQL.', 'Tanamin is a plant growth monitoring and agricultural management platform built using C#, .NET, and PostgreSQL. It helps users track planting schedules, monitor growth progress, and manage crop health.', 'Tanamin adalah platform pemantauan pertumbuhan tanaman dan manajemen pertanian yang dibangun menggunakan C#, .NET, dan PostgreSQL. Platform ini membantu pengguna melacak jadwal penanaman, memantau perkembangan pertumbuhan, dan mengelola kesehatan tanaman.', 'https://github.com/Adya30/Project-Tanamin', NULL, '[\"7\",\"20\",\"13\"]', '[\"Plant Growth Tracker\",\"Planting Schedule\",\"Database Integration\",\"Health Monitoring\"]', '[\"Pelacak Pertumbuhan Tanaman\",\"Jadwal Penanaman\",\"Integrasi Basis Data\",\"Pemantauan Kesehatan\"]', 4, 'https://res.cloudinary.com/droanqrew/image/upload/v1787533723/portfolio/projects/php2an4c6oe06qs6kwAVyS_nsugx1.webp', NULL, 4, '2026-08-11 23:34:02', '2026-08-25 09:56:12'),
(5, 'iphone-ui', 'Iphone UI', 'Website UI slicing replica of Apple iPhone official website using vanilla CSS and JavaScript.', 'Replika UI website dari website resmi Apple iPhone menggunakan CSS dan JavaScript murni.', 'A frontend UI slicing project of the Apple iPhone official website. Built using clean HTML, external CSS, and vanilla JS with a mobile-first responsive design, flexbox/grid layout, and Animate On Scroll (AOS) libraries.', 'Sebuah proyek UI frontend untuk situs web resmi Apple iPhone. Dibangun menggunakan HTML bersih, CSS eksternal, dan JavaScript murni dengan desain responsif mobile-first, tata letak flexbox/grid, dan pustaka Animate On Scroll (AOS).', 'https://github.com/Adya30/Iphone-UI', 'https://adya30.github.io/Iphone-UI/', '[\"17\",\"18\",\"4\",\"21\"]', '[\"Mobile-First Responsive\",\"Navbar Toggle DOM\",\"Flexbox & Grid Layout\",\"AOS Scroll Animation\"]', '[\"Responsif untuk Perangkat Seluler\",\"Toggle Navbar DOM\",\"Tata Letak Flexbox & Grid\",\"Animasi Gulir AOS\"]', 1, 'https://res.cloudinary.com/droanqrew/image/upload/v1787535158/portfolio/projects/phpqio1100ln33tbSHKyvk_u5fbh0.webp', NULL, 5, '2026-08-11 23:34:02', '2026-08-25 09:54:28'),
(6, 'fire-force', 'Fire Force', 'A responsive anime landing page or character gallery built with HTML, CSS, JavaScript, and Bootstrap.', 'Halaman arahan anime atau galeri karakter yang responsif, dibangun dengan HTML, CSS, JavaScript, dan Bootstrap.', 'Fire Force is a frontend landing page dedicated to the Fire Force anime series. Developed using HTML, CSS, JavaScript, and Bootstrap, the project features a responsive character gallery, lore explanations, and interactive visual elements.', 'Fire Force adalah landing page frontend yang didedikasikan untuk serial anime Fire Force. Dikembangkan menggunakan HTML, CSS, JavaScript, dan Bootstrap, proyek ini menampilkan galeri karakter responsif, penjelasan latar belakang cerita, dan elemen visual interaktif.', 'https://github.com/Adya30/Fire-Force', 'https://adya30.github.io/Fire-Force/', '[\"17\",\"18\",\"4\",\"6\"]', '[\"Responsive Layout\",\"Character Gallery\",\"Anime Information Hub\",\"Interactive DOM Elements\"]', '[\"Tata Letak Responsif\",\"Galeri Karakter\",\"Pusat Informasi Anime\",\"Elemen DOM\"]', 1, 'https://res.cloudinary.com/droanqrew/image/upload/v1787535188/portfolio/projects/phpvvq3q3rfksh5cFRo3OX_la9ttk.webp', NULL, 6, '2026-08-11 23:34:02', '2026-08-25 09:48:32'),
(7, 'gorengin-aja', 'Gorengin Aja!', 'Online fritter ordering platform for the Mastrip area built with basic web technologies.', 'Platform pemesanan gorengan online untuk area Mastrip yang dibangun dengan teknologi web dasar.', 'Gorengin Aja! is an online fritter ordering platform built for Mastrip area vendors. Developed using vanilla HTML, CSS, and JavaScript, the application allows customers to browse the menu and place orders digitally.', 'Gorengin Aja! adalah platform pemesanan gorengan online yang dibangun untuk para pedagang di area Mastrip. Dikembangkan menggunakan HTML, CSS, dan JavaScript murni, aplikasi ini memungkinkan pelanggan untuk menelusuri menu dan melakukan pemesanan secara digital.', 'https://github.com/Adya30/gorengan_template', 'https://adya30.github.io/gorengan_template/', '[\"17\",\"18\",\"4\"]', '[\"Menu Catalog\",\"Ordering System\",\"Responsive Design\"]', '[\"Katalog Menu\",\"Sistem Pemesanan\",\"Desain Responsive\"]', 1, 'https://res.cloudinary.com/droanqrew/image/upload/v1787535215/portfolio/projects/phpof12ovo0r8451oBgyuY_j8m5ti.webp', NULL, 7, '2026-08-11 23:34:02', '2026-08-25 09:47:15'),
(8, 'smagitv-blog', 'SMAGITV Blog', 'Online magazine and news blog for SMAN 1 Giri built on the Blogger platform.', 'Majalah online dan blog berita untuk SMAN 1 Giri yang dibangun di atas platform Blogger.', 'SMAGITV Blog is the online magazine and journal portal for SMAN 1 Giri. Built on the Blogger platform with custom HTML and CSS styling, it serves as a central news and activities portal for the school.', 'Blog SMAGITV adalah portal majalah dan jurnal online untuk SMAN 1 Giri. Dibangun di atas platform Blogger dengan gaya HTML dan CSS khusus, portal ini berfungsi sebagai portal berita dan kegiatan utama untuk sekolah.', NULL, 'https://majalahonlinesman1giri.blogspot.com/', '[\"17\",\"18\",\"19\"]', '[\"School News\",\"Activity Gallery\",\"Educational Articles\"]', '[\"Berita Sekolah\",\"Galeri Aktivitas\",\"Artikel Pendidikan\"]', 3, 'https://res.cloudinary.com/droanqrew/image/upload/v1787535255/portfolio/projects/php8d8kl5c4hg7a6VlD40m_c4ohuu.webp', NULL, 8, '2026-08-11 23:34:02', '2026-08-25 09:42:56'),
(9, 'adya-blog', 'Adya Blog', 'Personal blog containing professional ethics resumes and articles built with Blogger.', 'Blog pribadi berisi resume dan artikel tentang etika profesional yang dibuat menggunakan Blogger.', 'Adya Blog is a personal blog containing resumes and articles about professional ethics in information technology. Built on the Blogger platform with layout customization.', 'Adya Blog adalah blog pribadi yang berisi resume dan artikel tentang etika profesional di bidang teknologi informasi. Dibangun di atas platform Blogger dengan kustomisasi tata letak.', NULL, 'https://adyahan1.blogspot.com', '[]', '[\"Blog Articles\",\"Post Categories\",\"Responsive Layout\"]', '[\"Artikel Blog\",\"Kategori Posting\",\"Tata Letak Responsif\"]', 3, 'https://res.cloudinary.com/droanqrew/image/upload/v1787535312/portfolio/projects/phpennrd83fqgt62dghyO4_llaiyd.webp', NULL, 9, '2026-08-11 23:34:02', '2026-08-25 09:54:43'),
(10, 'sinabil', 'SINABIL', 'Database and relational tables design of the SINABIL Catering Information System.', 'Desain basis data dan tabel relasional dari Sistem Informasi Katering SINABIL.', 'SINABIL is a database system for catering management. Developed using Python and PostgreSQL, it features relational database design with tables for orders, customers, menu, and financial reports.', 'SINABIL adalah sistem basis data untuk manajemen katering. Dikembangkan menggunakan Python dan PostgreSQL, sistem ini memiliki desain basis data relasional dengan tabel untuk pesanan, pelanggan, menu, dan laporan keuangan.', NULL, 'https://docs.google.com/document/d/18WRWZXAJY-URu0uZjnjDEM4nNbl70Gbgjl6FYmt7pg0/edit?usp=sharing', '[\"7\",\"8\"]', '[\"Relational Database\",\"Order Management\",\"Financial Reports\"]', '[\"Basis Data Relasional\",\"Manajemen Pesanan\",\"Laporan Keuangan\"]', 5, 'https://res.cloudinary.com/droanqrew/image/upload/v1787535383/portfolio/projects/phpo7o3gvflunpk7Kt1gFT_rqfd0i.webp', NULL, 10, '2026-08-11 23:34:02', '2026-08-25 09:40:03'),
(11, 'garap', 'GARAP', 'Console based Python application providing agricultural land care services.', 'Aplikasi Python berbasis konsol yang menyediakan layanan perawatan lahan pertanian.', 'GARAP is a console-based Python application providing agricultural land care services, allowing users to register land, select maintenance services, and simulate transaction records.', 'GARAP adalah aplikasi Python berbasis konsol yang menyediakan layanan perawatan lahan pertanian, memungkinkan pengguna untuk mendaftarkan lahan, memilih layanan pemeliharaan, dan mensimulasikan catatan transaksi.', 'https://github.com/Adya30/garap', NULL, '[\"8\"]', '[\"Land Registration\",\"Maintenance Services\",\"Transaction System\"]', '[\"Pendaftaran Tanah\",\"Layanan Pemeliharaan\",\"Sistem Transaksi\"]', 2, 'https://res.cloudinary.com/droanqrew/image/upload/v1787674966/portfolio/projects/iddojpqcfldxlquk2eul.svg', NULL, 11, '2026-08-11 23:34:02', '2026-08-25 09:23:22'),
(12, 'sipa', 'SIPA', 'Console-based Python application for agricultural land scheduling and management.', 'Aplikasi Python berbasis konsol untuk penjadwalan dan pengelolaan lahan pertanian.', 'SIPA is a console-based Python information system for agricultural land scheduling, helping farmers organize planting, maintenance, and harvesting schedules in a structured way.', 'SIPA adalah sistem informasi berbasis konsol Python untuk penjadwalan lahan pertanian, yang membantu petani mengatur jadwal penanaman, pemeliharaan, dan panen secara terstruktur.', 'https://github.com/Adya30/SIPA', NULL, '[\"8\"]', '[\"Planting Schedule\",\"Land Management\",\"Activity History\"]', '[\"Jadwal Penanaman\",\"Pengelolaan Lahan\",\"Riwayat Aktivitas\"]', 2, 'https://res.cloudinary.com/droanqrew/image/upload/v1787535432/portfolio/projects/phpne17hkfqjniaaC90Ile_lqmdoz.webp', NULL, 12, '2026-08-11 23:34:02', '2026-08-25 09:12:36');

